window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[914]={"91400":{"example:91400:exzh":"How old is your daughter?","example:91400:exzh2":"Miss, you forgot your umbrella.","grammar:91400:ex:trans":"How old is your daughter?","grammar:91400:ex:structure":"お嬢さんは＋おいくつですか","grammar:91400:ex:explain":"「お嬢さん」 is an honorific term for someone else's daughter, often used when asking about their child in conversation. Refer to your own daughter as 「娘」. 「おいくつ」 is a polite version of 「いくつ（how old）」, with 「お」 added.","grammar:91400:ex:words:0:zh":"your daughter (polite)","grammar:91400:ex:words:0:note":"おじょうさん","grammar:91400:ex:words:0:pos":"noun","grammar:91400:ex:words:1:zh":"(topic)","grammar:91400:ex:words:1:pos":"particle","grammar:91400:ex:words:2:zh":"how old (polite expression)","grammar:91400:ex:words:2:pos":"question word","grammar:91400:ex:words:3:zh":"is (polite form)","grammar:91400:ex:words:3:pos":"copula","grammar:91400:ex:words:4:zh":"(question)","grammar:91400:ex:words:4:pos":"particle","grammar:91400:ex:points:0":"お嬢さん = a polite term for someone else's daughter; use 「娘（むすめ）」 for your own daughter","grammar:91400:ex:points:1":"おいくつですか: How old are you? More polite than 「何歳ですか」","grammar:91400:ex2:trans":"Miss, you forgot your umbrella.","grammar:91400:ex2:structure":"お嬢さん、＋〜よ","grammar:91400:ex2:words:0:zh":"miss","grammar:91400:ex2:words:0:note":"おじょうさん","grammar:91400:ex2:words:0:pos":"noun","grammar:91400:ex2:words:1:zh":"umbrella","grammar:91400:ex2:words:1:note":"かさ","grammar:91400:ex2:words:1:pos":"noun","grammar:91400:ex2:words:2:zh":"(object marker)","grammar:91400:ex2:words:2:pos":"particle","grammar:91400:ex2:words:3:zh":"Forgot","grammar:91400:ex2:words:3:note":"わすれました; past tense of the masu-form of 忘れる","grammar:91400:ex2:words:3:pos":"verb","grammar:91400:ex2:words:4:zh":"(reminder) よ","grammar:91400:ex2:words:4:pos":"particle","grammar:91400:ex2:points:0":"お嬢さん: can also be used to address a young woman you do not know; sounds somewhat old-fashioned","grammar:91400:ex2:points:1":"Sentence-final 「よ」: draws the listener's attention to something they do not know"},"91401":{"example:91401:exzh":"This stone has an interesting shape.","example:91401:exzh2":"I made star-shaped cookies.","grammar:91401:ex:trans":"This stone has an interesting shape.","grammar:91401:ex:structure":"〔something〕は＋〔description〕形をしています","grammar:91401:ex:explain":"「形」 on its own is pronounced 「かたち」 and refers to an object's shape. Japanese often uses 「〜形をしている」 to describe what something looks like. Here, 「する」 means “to have” or “to exhibit,” rather than “to do.”","grammar:91401:ex:words:0:zh":"this","grammar:91401:ex:words:0:pos":"pre-noun adjectival","grammar:91401:ex:words:1:zh":"stone","grammar:91401:ex:words:1:note":"いし","grammar:91401:ex:words:1:pos":"noun","grammar:91401:ex:words:2:zh":"(topic)","grammar:91401:ex:words:2:pos":"particle","grammar:91401:ex:words:3:zh":"interesting","grammar:91401:ex:words:3:note":"おもしろい","grammar:91401:ex:words:3:pos":"adjective","grammar:91401:ex:words:4:zh":"shape","grammar:91401:ex:words:4:note":"かたち","grammar:91401:ex:words:4:pos":"noun","grammar:91401:ex:words:5:zh":"(object marker)","grammar:91401:ex:words:5:pos":"particle","grammar:91401:ex:words:6:zh":"have; exhibit","grammar:91401:ex:words:6:note":"して; the te-form of する","grammar:91401:ex:words:6:pos":"verb","grammar:91401:ex:words:7:zh":"(in the state of ~)","grammar:91401:ex:words:7:note":"います; the masu-form of いる","grammar:91401:ex:words:7:pos":"auxiliary verb","grammar:91401:ex:points:0":"形 = shape or form; 「〜形をしている」 = to have a ~ shape","grammar:91401:ex:points:1":"Japanese often uses 「〜をしている」 to describe appearance: 青い目をしている (to have blue eyes)","grammar:91401:ex2:trans":"I made star-shaped cookies.","grammar:91401:ex2:structure":"〔something〕の形の＋〔noun〕","grammar:91401:ex2:words:0:zh":"star","grammar:91401:ex2:words:0:note":"ほし","grammar:91401:ex2:words:0:pos":"noun","grammar:91401:ex2:words:1:zh":"'s","grammar:91401:ex2:words:1:pos":"particle","grammar:91401:ex2:words:2:zh":"shape","grammar:91401:ex2:words:2:note":"かたち","grammar:91401:ex2:words:2:pos":"noun","grammar:91401:ex2:words:3:zh":"'s","grammar:91401:ex2:words:3:pos":"particle","grammar:91401:ex2:words:4:zh":"cookies","grammar:91401:ex2:words:4:pos":"noun","grammar:91401:ex2:words:5:zh":"(object marker)","grammar:91401:ex2:words:5:pos":"particle","grammar:91401:ex2:words:6:zh":"did","grammar:91401:ex2:words:6:note":"つくりました; past tense of the masu-form of 作る","grammar:91401:ex2:words:6:pos":"verb","grammar:91401:ex2:points:0":"星の形のクッキー: star-shaped cookies","grammar:91401:ex2:points:1":"Use 「の」 to connect one noun to another"},"91402":{"example:91402:exzh":"I completely forgot about our promise.","example:91402:exzh2":"I've completely recovered from my illness.","grammar:91402:ex:trans":"I completely forgot about our appointment.","grammar:91402:ex:structure":"すっかり＋忘れる","grammar:91402:ex:explain":"「すっかり」 indicates that a change is complete and is often used with 「忘れる」, 「変わる」, and 「良くなる」. 「すっかり忘れていました」 means that you had completely forgotten about something until just now; it is often used in apologies.","grammar:91402:ex:words:0:zh":"appointment","grammar:91402:ex:words:0:note":"やくそく","grammar:91402:ex:words:0:pos":"noun","grammar:91402:ex:words:1:zh":"(object marker)","grammar:91402:ex:words:1:pos":"particle","grammar:91402:ex:words:2:zh":"completely","grammar:91402:ex:words:2:pos":"adverb","grammar:91402:ex:words:3:zh":"forgot","grammar:91402:ex:words:3:note":"wasurete; the te-form of 忘れる","grammar:91402:ex:words:3:pos":"verb","grammar:91402:ex:words:4:zh":"(had remained in a ~ state)","grammar:91402:ex:words:4:note":"いました; the past masu-form of いる","grammar:91402:ex:words:4:pos":"auxiliary verb","grammar:91402:ex:points:0":"すっかり = completely, thoroughly; 「すっかり忘れる」 is the most common combination","grammar:91402:ex:points:1":"〜ていました: had remained in a ~ state (only realizing it just now)","grammar:91402:ex2:trans":"I have completely recovered from my illness.","grammar:91402:ex2:structure":"すっかり＋〜くなりました","grammar:91402:ex2:words:0:zh":"illness","grammar:91402:ex2:words:0:note":"びょうき","grammar:91402:ex2:words:0:pos":"noun","grammar:91402:ex2:words:1:zh":"(topic)","grammar:91402:ex2:words:1:pos":"particle","grammar:91402:ex2:words:2:zh":"completely","grammar:91402:ex2:words:2:pos":"adverb","grammar:91402:ex2:words:3:zh":"better","grammar:91402:ex2:words:3:note":"よく; adverbial form of 良い","grammar:91402:ex2:words:3:pos":"adjective","grammar:91402:ex2:words:4:zh":"become","grammar:91402:ex2:words:4:note":"なりました; past masu-form of なる","grammar:91402:ex2:words:4:pos":"verb","grammar:91402:ex2:points:0":"すっかり良くなる: to recover completely","grammar:91402:ex2:points:1":"い-adjective＋なる: 良い→良くなる (to get better)"},"91403":{"example:91403:exzh":"My older sister is an announcer at a TV station.","example:91403:exzh2":"The announcer is reading the news.","grammar:91403:ex:trans":"My older sister is a news anchor at a TV station.","grammar:91403:ex:structure":"〔person〕は＋〔organization〕のアナウンサーです","grammar:91403:ex:explain":"「アナウンサー」 comes from the English word “announcer.” In Japan, it specifically refers to announcers and program hosts employed by TV or radio stations. 「テレビ局のアナウンサー」 means a TV station's news anchor.","grammar:91403:ex:words:0:zh":"older sister","grammar:91403:ex:words:0:note":"あね","grammar:91403:ex:words:0:pos":"noun","grammar:91403:ex:words:1:zh":"(topic)","grammar:91403:ex:words:1:pos":"particle","grammar:91403:ex:words:2:zh":"TV station","grammar:91403:ex:words:2:note":"テレビきょく","grammar:91403:ex:words:2:pos":"noun","grammar:91403:ex:words:3:zh":"'s","grammar:91403:ex:words:3:pos":"particle","grammar:91403:ex:words:4:zh":"news anchor","grammar:91403:ex:words:4:pos":"noun","grammar:91403:ex:words:5:zh":"is (polite form)","grammar:91403:ex:words:5:pos":"copula","grammar:91403:ex:points:0":"アナウンサー = a TV or radio announcer or news anchor (from “announcer”)","grammar:91403:ex:points:1":"テレビ局 = TV station; 「局」 denotes an organization","grammar:91403:ex2:trans":"The news anchor is reading the news.","grammar:91403:ex2:structure":"アナウンサーが＋ニュースを読む","grammar:91403:ex2:words:0:zh":"news anchor","grammar:91403:ex2:words:0:pos":"noun","grammar:91403:ex2:words:1:zh":"(nominative)","grammar:91403:ex2:words:1:pos":"particle","grammar:91403:ex2:words:2:zh":"news","grammar:91403:ex2:words:2:pos":"noun","grammar:91403:ex2:words:3:zh":"(object marker)","grammar:91403:ex2:words:3:pos":"particle","grammar:91403:ex2:words:4:zh":"read the news","grammar:91403:ex2:words:4:note":"yonde; te-form of 読む","grammar:91403:ex2:words:4:pos":"verb","grammar:91403:ex2:words:5:zh":"(in the middle of) ~ing","grammar:91403:ex2:words:5:note":"います; the masu-form of いる","grammar:91403:ex2:words:5:pos":"auxiliary verb","grammar:91403:ex2:points:0":"ニュースを読む: to report the news; Japanese says “read” the news","grammar:91403:ex2:points:1":"〜ています: be doing ~"},"91404":{"example:91404:exzh":"Please lend me an eraser.","example:91404:exzh2":"I erased the characters I had written wrong with an eraser.","grammar:91404:ex:trans":"Please lend me an eraser.","grammar:91404:ex:structure":"〔something〕を＋貸してください","grammar:91404:ex:explain":"「消しゴム」 literally means “rubber for erasing,” or an eraser. When asking to borrow something, use 「貸してください（Please lend it to me）」, not 「借りてください」. This is a common mistake among native Chinese speakers.","grammar:91404:ex:words:0:zh":"(for) erasing","grammar:91404:ex:words:0:note":"けし; noun form of 消す, combined with ゴム to form 「消しゴム」","grammar:91404:ex:words:0:pos":"noun","grammar:91404:ex:words:1:zh":"rubber; combined with the preceding part, means “eraser”","grammar:91404:ex:words:1:pos":"noun","grammar:91404:ex:words:2:zh":"(object marker)","grammar:91404:ex:words:2:pos":"particle","grammar:91404:ex:words:3:zh":"lend (to me)","grammar:91404:ex:words:3:note":"かして; te-form of 貸す","grammar:91404:ex:words:3:pos":"verb","grammar:91404:ex:words:4:zh":"please ~","grammar:91404:ex:words:4:note":"ください; the imperative form of くださる","grammar:91404:ex:words:4:pos":"auxiliary verb","grammar:91404:ex:points:0":"消しゴム = eraser; 「消す」 (to erase) + 「ゴム」 (rubber)","grammar:91404:ex:points:1":"貸す = to lend; to ask someone to lend you something, say 「貸してください」","grammar:91404:ex2:trans":"I erased the character I had written wrong with an eraser.","grammar:91404:ex2:structure":"〔thing〕を消しゴムで＋消す","grammar:91404:ex2:words:0:zh":"written wrong","grammar:91404:ex2:words:0:note":"まちがえた; ta-form of 間違える","grammar:91404:ex2:words:0:pos":"verb","grammar:91404:ex2:words:1:zh":"letters","grammar:91404:ex2:words:1:note":"じ","grammar:91404:ex2:words:1:pos":"noun","grammar:91404:ex2:words:2:zh":"(object marker)","grammar:91404:ex2:words:2:pos":"particle","grammar:91404:ex2:words:3:zh":"(for) erasing","grammar:91404:ex2:words:3:note":"けし; noun form of 消す, combined with ゴム to form 「消しゴム」","grammar:91404:ex2:words:3:pos":"noun","grammar:91404:ex2:words:4:zh":"rubber; combined with the preceding part, means “eraser”","grammar:91404:ex2:words:4:pos":"noun","grammar:91404:ex2:words:5:zh":"with (a tool)","grammar:91404:ex2:words:5:pos":"particle","grammar:91404:ex2:words:6:zh":"erased","grammar:91404:ex2:words:6:note":"けしました; past masu-form of 消す","grammar:91404:ex2:words:6:pos":"verb","grammar:91404:ex2:points:0":"消しゴムで消す: erase with an eraser","grammar:91404:ex2:points:1":"「で」 marks the tool used"},"91405":{"example:91405:exzh":"I stayed at a Japanese inn with a hot spring.","example:91405:exzh2":"The dinner at the inn was very good.","grammar:91405:ex:trans":"I stayed at a ryokan with a hot spring.","grammar:91405:ex:structure":"〜のある＋旅館に泊まる","grammar:91405:ex:explain":"In Japan, 「旅館」 means a traditional Japanese-style inn: the rooms have tatami and it provides yukata and dinner, unlike a Western-style 「ホテル」. 「〜に泊まる」 marks the place you stay. 「温泉のある旅館」 comes from 「温泉がある旅館」; when modifying a noun, 「が」 is often replaced by 「の」.","grammar:91405:ex:words:0:zh":"hot spring","grammar:91405:ex:words:0:note":"おんせん","grammar:91405:ex:words:0:pos":"noun","grammar:91405:ex:words:1:zh":"'s","grammar:91405:ex:words:1:pos":"particle","grammar:91405:ex:words:2:zh":"there is / are","grammar:91405:ex:words:2:note":"ある","grammar:91405:ex:words:2:pos":"verb","grammar:91405:ex:words:3:zh":"Japanese-style inn","grammar:91405:ex:words:3:note":"りょかん","grammar:91405:ex:words:3:pos":"noun","grammar:91405:ex:words:4:zh":"at (the place you stay)","grammar:91405:ex:words:4:pos":"particle","grammar:91405:ex:words:5:zh":"stayed","grammar:91405:ex:words:5:note":"tomarimashita; the masu-form past of 泊まる","grammar:91405:ex:words:5:pos":"verb","grammar:91405:ex:points:0":"旅館 = traditional Japanese inn (tatami rooms, often with a hot spring and dinner); a Western-style one is called 「ホテル」","grammar:91405:ex:points:1":"〔place〕に泊まる: stay at ~; 「温泉のある」 = having a hot spring (inside a modifying clause, 「が」 can become 「の」)","grammar:91405:ex2:trans":"The dinner at the inn was very good.","grammar:91405:ex2:structure":"〔noun〕は＋〔past form of an adjective〕です","grammar:91405:ex2:words:0:zh":"inn","grammar:91405:ex2:words:0:note":"りょかん","grammar:91405:ex2:words:0:pos":"noun","grammar:91405:ex2:words:1:zh":"'s","grammar:91405:ex2:words:1:pos":"particle","grammar:91405:ex2:words:2:zh":"dinner","grammar:91405:ex2:words:2:note":"ばんごはん","grammar:91405:ex2:words:2:pos":"noun","grammar:91405:ex2:words:3:zh":"(topic)","grammar:91405:ex2:words:3:pos":"particle","grammar:91405:ex2:words:4:zh":"extremely","grammar:91405:ex2:words:4:pos":"adverb","grammar:91405:ex2:words:5:zh":"delicious","grammar:91405:ex2:words:5:note":"おいしかった; past form of おいしい","grammar:91405:ex2:words:5:pos":"adjective","grammar:91405:ex2:words:6:zh":"is (polite form)","grammar:91405:ex2:words:6:pos":"copula","grammar:91405:ex2:points:0":"旅館の晩ご飯: the inn's dinner (often included at a ryokan)","grammar:91405:ex2:points:1":"i-adjective past form: おいしい→おいしかったです"},"91406":{"example:91406:exzh":"I commute to work by train every day.","example:91406:exzh2":"My child goes to a nearby elementary school.","grammar:91406:ex:trans":"I commute to work by train every day.","grammar:91406:ex:structure":"〔means of transport〕で＋〔place〕に通っています","grammar:91406:ex:explain":"The point of 「通う」 is going regularly and repeatedly, not just once. It works for commuting to work, going to school, or visiting a doctor regularly. It usually appears as 「〜ています」 to show a habit over time. The means of transport takes 「で」.","grammar:91406:ex:words:0:zh":"every day","grammar:91406:ex:words:0:note":"まいにち","grammar:91406:ex:words:0:pos":"noun","grammar:91406:ex:words:1:zh":"train","grammar:91406:ex:words:1:note":"でんしゃ","grammar:91406:ex:words:1:pos":"noun","grammar:91406:ex:words:2:zh":"by (means of transport)","grammar:91406:ex:words:2:pos":"particle","grammar:91406:ex:words:3:zh":"company","grammar:91406:ex:words:3:note":"かいしゃ","grammar:91406:ex:words:3:pos":"noun","grammar:91406:ex:words:4:zh":"to (the destination)","grammar:91406:ex:words:4:pos":"particle","grammar:91406:ex:words:5:zh":"commute","grammar:91406:ex:words:5:note":"かよって; the te-form of 通う","grammar:91406:ex:words:5:pos":"verb","grammar:91406:ex:words:6:zh":"(habitually) is ~ing","grammar:91406:ex:words:6:note":"います; the masu-form of いる","grammar:91406:ex:words:6:pos":"auxiliary verb","grammar:91406:ex:points:0":"通う = to come and go to the same place regularly: 会社に通う, 学校に通う, 病院に通う","grammar:91406:ex:points:1":"〜ています: shows a daily habit","grammar:91406:ex2:trans":"The child goes to a nearby elementary school.","grammar:91406:ex2:structure":"〔person〕は＋〔school〕に通っています","grammar:91406:ex2:words:0:zh":"child","grammar:91406:ex2:words:0:note":"こども","grammar:91406:ex2:words:0:pos":"noun","grammar:91406:ex2:words:1:zh":"(topic)","grammar:91406:ex2:words:1:pos":"particle","grammar:91406:ex2:words:2:zh":"nearby","grammar:91406:ex2:words:2:note":"ちかく","grammar:91406:ex2:words:2:pos":"noun","grammar:91406:ex2:words:3:zh":"'s","grammar:91406:ex2:words:3:pos":"particle","grammar:91406:ex2:words:4:zh":"elementary school","grammar:91406:ex2:words:4:note":"しょうがっこう","grammar:91406:ex2:words:4:pos":"noun","grammar:91406:ex2:words:5:zh":"to (the destination)","grammar:91406:ex2:words:5:pos":"particle","grammar:91406:ex2:words:6:zh":"attending school","grammar:91406:ex2:words:6:note":"かよって; the te-form of 通う","grammar:91406:ex2:words:6:pos":"verb","grammar:91406:ex2:words:7:zh":"(habitually) is ~ing","grammar:91406:ex2:words:7:note":"います; the masu-form of いる","grammar:91406:ex2:words:7:pos":"auxiliary verb","grammar:91406:ex2:points:0":"小学校に通う: attend elementary school","grammar:91406:ex2:points:1":"近くの〜: nearby ~"},"91407":{"example:91407:exzh":"On weekends I take my child to the park.","example:91407:exzh2":"May I bring a friend over to my house?","grammar:91407:ex:trans":"On weekends I take my child to the park.","grammar:91407:ex:structure":"〔person〕を＋〔place〕に連れて行く","grammar:91407:ex:explain":"「連れる」 is used only for people or animals and means to move together with them. In practice it almost always appears as 「連れて行く」 or 「連れて来る」. For things like an umbrella or a lunch box, use 「持って行く」.","grammar:91407:ex:words:0:zh":"weekend","grammar:91407:ex:words:0:note":"しゅうまつ","grammar:91407:ex:words:0:pos":"noun","grammar:91407:ex:words:1:zh":"(topic)","grammar:91407:ex:words:1:pos":"particle","grammar:91407:ex:words:2:zh":"child","grammar:91407:ex:words:2:note":"こども","grammar:91407:ex:words:2:pos":"noun","grammar:91407:ex:words:3:zh":"(object marker)","grammar:91407:ex:words:3:pos":"particle","grammar:91407:ex:words:4:zh":"park","grammar:91407:ex:words:4:note":"こうえん","grammar:91407:ex:words:4:pos":"noun","grammar:91407:ex:words:5:zh":"to (the destination)","grammar:91407:ex:words:5:pos":"particle","grammar:91407:ex:words:6:zh":"taking along","grammar:91407:ex:words:6:note":"つれて; te-form of 連れる","grammar:91407:ex:words:6:pos":"verb","grammar:91407:ex:words:7:zh":"go","grammar:91407:ex:words:7:note":"いきます; masu-form of 行く","grammar:91407:ex:words:7:pos":"verb","grammar:91407:ex:points:0":"連れる = to take a person or animal along; usually in the forms 「連れて行く」 (take there) and 「連れて来る」 (bring here)","grammar:91407:ex:points:1":"For things use 「持って行く」; for people use 「連れて行く」","grammar:91407:ex2:trans":"Is it okay if I bring a friend home?","grammar:91407:ex2:structure":"〔person〕を連れてきても＋いいですか","grammar:91407:ex2:words:0:zh":"friend","grammar:91407:ex2:words:0:note":"ともだち","grammar:91407:ex2:words:0:pos":"noun","grammar:91407:ex2:words:1:zh":"(object marker)","grammar:91407:ex2:words:1:pos":"particle","grammar:91407:ex2:words:2:zh":"house","grammar:91407:ex2:words:2:note":"いえ","grammar:91407:ex2:words:2:pos":"noun","grammar:91407:ex2:words:3:zh":"to (the destination)","grammar:91407:ex2:words:3:pos":"particle","grammar:91407:ex2:words:4:zh":"taking along","grammar:91407:ex2:words:4:note":"つれて; te-form of 連れる","grammar:91407:ex2:words:4:pos":"verb","grammar:91407:ex2:words:5:zh":"come","grammar:91407:ex2:words:5:note":"きて; te-form of くる","grammar:91407:ex2:words:5:pos":"auxiliary verb","grammar:91407:ex2:words:6:zh":"also, too","grammar:91407:ex2:words:6:pos":"particle","grammar:91407:ex2:words:7:zh":"it's okay","grammar:91407:ex2:words:7:note":"いい","grammar:91407:ex2:words:7:pos":"adjective","grammar:91407:ex2:words:8:zh":"is (polite form)","grammar:91407:ex2:words:8:pos":"copula","grammar:91407:ex2:words:9:zh":"(question)","grammar:91407:ex2:words:9:pos":"particle","grammar:91407:ex2:points:0":"連れてくる: bring (a person) here","grammar:91407:ex2:points:1":"〜てもいいですか: may I ~? (asking permission)"},"91408":{"example:91408:exzh":"I'll be at the office all day tomorrow.","example:91408:exzh2":"My father is out right now.","grammar:91408:ex:trans":"Tomorrow I will be at the office all day.","grammar:91408:ex:structure":"〔place〕に＋おります","grammar:91408:ex:explain":"「おる」 is the humble form of 「いる」 (to be). It lowers yourself to show politeness to the other person and is normally used as 「おります」. It is very common when telling a customer or a boss where you are. In ordinary conversation 「います」 is enough.","grammar:91408:ex:words:0:zh":"tomorrow","grammar:91408:ex:words:0:note":"あした","grammar:91408:ex:words:0:pos":"noun","grammar:91408:ex:words:1:zh":"(topic)","grammar:91408:ex:words:1:pos":"particle","grammar:91408:ex:words:2:zh":"all day","grammar:91408:ex:words:2:note":"いちにちじゅう","grammar:91408:ex:words:2:pos":"noun","grammar:91408:ex:words:3:zh":"company","grammar:91408:ex:words:3:note":"かいしゃ","grammar:91408:ex:words:3:pos":"noun","grammar:91408:ex:words:4:zh":"in (the place where something exists)","grammar:91408:ex:words:4:pos":"particle","grammar:91408:ex:words:5:zh":"be (humble)","grammar:91408:ex:words:5:note":"おります; masu-form of おる","grammar:91408:ex:words:5:pos":"verb","grammar:91408:ex:points:0":"おる = humble form of 「いる」; used when telling a client or boss where you are","grammar:91408:ex:points:1":"一日中 = all day; 「中」 (じゅう) covers the whole span of time","grammar:91408:ex2:trans":"My father is out right now.","grammar:91408:ex2:structure":"〜て＋おります","grammar:91408:ex2:words:0:zh":"my father (humble)","grammar:91408:ex2:words:0:note":"ちち","grammar:91408:ex2:words:0:pos":"noun","grammar:91408:ex2:words:1:zh":"(topic)","grammar:91408:ex2:words:1:pos":"particle","grammar:91408:ex2:words:2:zh":"now","grammar:91408:ex2:words:2:note":"いま","grammar:91408:ex2:words:2:pos":"noun","grammar:91408:ex2:words:3:zh":"going out","grammar:91408:ex2:words:3:note":"でかけて: the te-form of 出かける.","grammar:91408:ex2:words:3:pos":"verb","grammar:91408:ex2:words:4:zh":"(be in the state of ~, humble)","grammar:91408:ex2:words:4:note":"おります; masu-form of おる","grammar:91408:ex2:words:4:pos":"auxiliary verb","grammar:91408:ex2:points:0":"〜ております = the humble version of 「〜ています」","grammar:91408:ex2:points:1":"Humble language is also used for your own family when speaking to outsiders: 父は出かけております"},"91409":{"example:91409:exzh":"How do you do? My name is Tanaka.","example:91409:exzh2":"My mother asked me to give you her regards.","grammar:91409:ex:trans":"Nice to meet you, my name is Tanaka.","grammar:91409:ex:structure":"〔name〕と＋申します","grammar:91409:ex:explain":"「申す」 is the humble form of 「言う」 (to say), and 「〔name〕と申します」 literally means I am called ~; it is the most formal self-introduction. In everyday situations 「田中です」 is enough.","grammar:91409:ex:words:0:zh":"Nice to meet you","grammar:91409:ex:words:0:pos":"set phrase","grammar:91409:ex:words:1:zh":"Tanaka (surname)","grammar:91409:ex:words:1:note":"たなか","grammar:91409:ex:words:1:pos":"noun","grammar:91409:ex:words:2:zh":"(quotation) be called","grammar:91409:ex:words:2:pos":"particle","grammar:91409:ex:words:3:zh":"be called (humble)","grammar:91409:ex:words:3:note":"もうします; masu-form of 申す","grammar:91409:ex:words:3:pos":"verb","grammar:91409:ex:points:0":"申す = humble form of 「言う」; 「〜と申します」 is a formal self-introduction","grammar:91409:ex:points:1":"More polite than 「〜です」; common in interviews and business settings","grammar:91409:ex2:trans":"My mother asked me to give you her regards.","grammar:91409:ex2:structure":"〔person〕が＋よろしくと申しておりました","grammar:91409:ex2:words:0:zh":"my mother (humble)","grammar:91409:ex2:words:0:note":"はは","grammar:91409:ex2:words:0:pos":"noun","grammar:91409:ex2:words:1:zh":"(nominative)","grammar:91409:ex2:words:1:pos":"particle","grammar:91409:ex2:words:2:zh":"give regards on someone's behalf","grammar:91409:ex2:words:2:pos":"adverb","grammar:91409:ex2:words:3:zh":"(quotation)","grammar:91409:ex2:words:3:pos":"particle","grammar:91409:ex2:words:4:zh":"say (humble)","grammar:91409:ex2:words:4:note":"もうして; te-form of 申す","grammar:91409:ex2:words:4:pos":"verb","grammar:91409:ex2:words:5:zh":"be ~ (at that time, humble)","grammar:91409:ex2:words:5:note":"おりました; past masu-form of おる","grammar:91409:ex2:words:5:pos":"auxiliary verb","grammar:91409:ex2:points:0":"〜がよろしくと申しておりました: someone asked me to give you their regards","grammar:91409:ex2:points:1":"Even for words from your own family, use the humble 「申す」 toward outsiders"},"91410":{"example:91410:exzh":"Yes, here's three hundred yen in change.","example:91410:exzh2":"I forgot to take my change.","grammar:91410:ex:trans":"Sure, here is 300 yen in change.","grammar:91410:ex:structure":"〔amount〕の＋おつりです","grammar:91410:ex:explain":"「おつり」 is what a shop clerk says when giving change, so 「〔金額〕のおつりです」 means here is ~ in change. It differs from 「小銭」 (こぜに, coins), since 「おつり」 is always money handed back to you.","grammar:91410:ex:words:0:zh":"good","grammar:91410:ex:words:0:pos":"set phrase","grammar:91410:ex:words:1:zh":"three hundred","grammar:91410:ex:words:1:note":"さんびゃく","grammar:91410:ex:words:1:pos":"numeral","grammar:91410:ex:words:2:zh":"yen","grammar:91410:ex:words:2:note":"えん","grammar:91410:ex:words:2:pos":"suffix","grammar:91410:ex:words:3:zh":"'s","grammar:91410:ex:words:3:pos":"particle","grammar:91410:ex:words:4:zh":"change (money handed back)","grammar:91410:ex:words:4:pos":"noun","grammar:91410:ex:words:5:zh":"is (polite form)","grammar:91410:ex:words:5:pos":"copula","grammar:91410:ex:points:0":"おつり = the change a shop gives back when you pay more than the price; also written 「お釣り」","grammar:91410:ex:points:1":"三百 is read 「さんびゃく」: 「百」 becomes 「びゃく」 after 「三」","grammar:91410:ex2:trans":"I forgot to take the change.","grammar:91410:ex2:structure":"〔verb dictionary form〕のを＋忘れました","grammar:91410:ex2:words:0:zh":"change (money handed back)","grammar:91410:ex2:words:0:pos":"noun","grammar:91410:ex2:words:1:zh":"(object marker)","grammar:91410:ex2:words:1:pos":"particle","grammar:91410:ex2:words:2:zh":"receive","grammar:91410:ex2:words:2:pos":"verb","grammar:91410:ex2:words:3:zh":"(turns the action into a noun)","grammar:91410:ex2:words:3:pos":"formal noun","grammar:91410:ex2:words:4:zh":"(object marker)","grammar:91410:ex2:words:4:pos":"particle","grammar:91410:ex2:words:5:zh":"Forgot","grammar:91410:ex2:words:5:note":"わすれました; past tense of the masu-form of 忘れる","grammar:91410:ex2:words:5:pos":"verb","grammar:91410:ex2:points:0":"おつりをもらう: get the change","grammar:91410:ex2:points:1":"〜のを忘れる: forget to do ~; 「の」 turns the preceding action into a noun"},"91411":{"example:91411:exzh":"This town has convenient transportation.","example:91411:exzh2":"Transportation has come to a stop because of an accident.","grammar:91411:ex:trans":"This town has convenient transportation.","grammar:91411:ex:structure":"〔place〕は＋交通が便利です","grammar:91411:ex:explain":"「交通」 means transportation, the movement of cars, trains, and so on. When describing a place, people often say 「交通が便利です」. This is the 「AはBが〜」 pattern: 「は」 introduces the town, and 「が」 says which aspect of it is convenient.","grammar:91411:ex:words:0:zh":"this","grammar:91411:ex:words:0:pos":"pre-noun adjectival","grammar:91411:ex:words:1:zh":"town","grammar:91411:ex:words:1:note":"まち","grammar:91411:ex:words:1:pos":"noun","grammar:91411:ex:words:2:zh":"(topic)","grammar:91411:ex:words:2:pos":"particle","grammar:91411:ex:words:3:zh":"transportation","grammar:91411:ex:words:3:note":"こうつう","grammar:91411:ex:words:3:pos":"noun","grammar:91411:ex:words:4:zh":"(nominative)","grammar:91411:ex:words:4:pos":"particle","grammar:91411:ex:words:5:zh":"convenient","grammar:91411:ex:words:5:note":"べんり","grammar:91411:ex:words:5:pos":"na-adjective","grammar:91411:ex:words:6:zh":"is (polite form)","grammar:91411:ex:words:6:pos":"copula","grammar:91411:ex:points:0":"交通が便利 = transportation is convenient; the opposite is 「交通が不便」","grammar:91411:ex:points:1":"「AはBが〜」: as for place A, B is such and such","grammar:91411:ex2:trans":"Transportation has stopped because of an accident.","grammar:91411:ex2:structure":"〔cause〕で＋交通が止まっています","grammar:91411:ex2:words:0:zh":"accident","grammar:91411:ex2:words:0:note":"じこ","grammar:91411:ex2:words:0:pos":"noun","grammar:91411:ex2:words:1:zh":"because of (cause)","grammar:91411:ex2:words:1:pos":"particle","grammar:91411:ex2:words:2:zh":"transportation","grammar:91411:ex2:words:2:note":"こうつう","grammar:91411:ex2:words:2:pos":"noun","grammar:91411:ex2:words:3:zh":"(nominative)","grammar:91411:ex2:words:3:pos":"particle","grammar:91411:ex2:words:4:zh":"cut off","grammar:91411:ex2:words:4:note":"とまって; the te-form of 止まる","grammar:91411:ex2:words:4:pos":"verb","grammar:91411:ex2:words:5:zh":"(in the state of ~)","grammar:91411:ex2:words:5:note":"います; the masu-form of いる","grammar:91411:ex2:words:5:pos":"auxiliary verb","grammar:91411:ex2:points:0":"交通が止まる: transportation stops or is halted","grammar:91411:ex2:points:1":"事故で: because of an accident; 「で」 marks the cause"},"91412":{"example:91412:exzh":"It was cold, so I put on gloves.","example:91412:exzh2":"I left my gloves on the train.","grammar:91412:ex:trans":"It was cold, so I put on gloves.","grammar:91412:ex:structure":"手袋を＋する","grammar:91412:ex:explain":"「手袋」 is read 「てぶくろ」 and literally means a bag for the hands. To wear gloves, Japanese usually says 「手袋をする」, and the slightly more formal verb is 「はめる」. 「〜ので」 gives the reason: it was cold, so I put on gloves.","grammar:91412:ex:words:0:zh":"cold","grammar:91412:ex:words:0:note":"さむい","grammar:91412:ex:words:0:pos":"adjective","grammar:91412:ex:words:1:zh":"because","grammar:91412:ex:words:1:pos":"particle","grammar:91412:ex:words:2:zh":"gloves","grammar:91412:ex:words:2:note":"てぶくろ","grammar:91412:ex:words:2:pos":"noun","grammar:91412:ex:words:3:zh":"(object marker)","grammar:91412:ex:words:3:pos":"particle","grammar:91412:ex:words:4:zh":"put on","grammar:91412:ex:words:4:note":"しました; the past masu-form of する","grammar:91412:ex:words:4:pos":"verb","grammar:91412:ex:points:0":"手袋をする = wear gloves; 「手袋をはめる」 also works","grammar:91412:ex:points:1":"In Japanese the verb for wearing something changes with the body part: 「かぶる」 for a hat, 「かける」 for glasses, 「する／はめる」 for gloves","grammar:91412:ex2:trans":"I left the gloves on the train.","grammar:91412:ex2:structure":"〔place〕に＋〔thing〕を忘れる","grammar:91412:ex2:words:0:zh":"train","grammar:91412:ex2:words:0:note":"でんしゃ","grammar:91412:ex2:words:0:pos":"noun","grammar:91412:ex2:words:1:zh":"'s","grammar:91412:ex2:words:1:pos":"particle","grammar:91412:ex2:words:2:zh":"inside","grammar:91412:ex2:words:2:note":"なか","grammar:91412:ex2:words:2:pos":"noun","grammar:91412:ex2:words:3:zh":"in (the place where it was left)","grammar:91412:ex2:words:3:pos":"particle","grammar:91412:ex2:words:4:zh":"gloves","grammar:91412:ex2:words:4:note":"てぶくろ","grammar:91412:ex2:words:4:pos":"noun","grammar:91412:ex2:words:5:zh":"(object marker)","grammar:91412:ex2:words:5:pos":"particle","grammar:91412:ex2:words:6:zh":"forgot (to take it with me)","grammar:91412:ex2:words:6:note":"わすれました; past tense of the masu-form of 忘れる","grammar:91412:ex2:words:6:pos":"verb","grammar:91412:ex2:points:0":"〜に〜を忘れる: leave something at a place","grammar:91412:ex2:points:1":"忘れる can also mean to forget to take something with you"},"91413":{"example:91413:exzh":"In the morning, the principal gave a talk.","example:91413:exzh2":"The new principal is a woman.","grammar:91413:ex:trans":"In the morning there was a talk by the principal.","grammar:91413:ex:structure":"〔person〕の話が＋ありました","grammar:91413:ex:explain":"「校長」 is read 「こうちょう」 and means the principal of an elementary, junior high, or high school; a university president is 「学長」. Students usually say 「校長先生」 to show respect. 「話がある」 means there is a talk or there is something to say.","grammar:91413:ex:words:0:zh":"morning","grammar:91413:ex:words:0:note":"あさ","grammar:91413:ex:words:0:pos":"noun","grammar:91413:ex:words:1:zh":"principal","grammar:91413:ex:words:1:note":"こうちょう","grammar:91413:ex:words:1:pos":"noun","grammar:91413:ex:words:2:zh":"(respectful title for teachers and principals)","grammar:91413:ex:words:2:note":"せんせい","grammar:91413:ex:words:2:pos":"suffix","grammar:91413:ex:words:3:zh":"'s","grammar:91413:ex:words:3:pos":"particle","grammar:91413:ex:words:4:zh":"speaking","grammar:91413:ex:words:4:note":"はなし","grammar:91413:ex:words:4:pos":"noun","grammar:91413:ex:words:5:zh":"(nominative)","grammar:91413:ex:words:5:pos":"particle","grammar:91413:ex:words:6:zh":"there was","grammar:91413:ex:words:6:note":"ありました; the masu-form past of ある","grammar:91413:ex:words:6:pos":"verb","grammar:91413:ex:points:0":"校長 = principal of an elementary or secondary school; a university president is called 「学長」 (がくちょう)","grammar:91413:ex:points:1":"Japanese students customarily add 「先生」 when addressing the principal: 校長先生","grammar:91413:ex2:trans":"The new principal is a woman.","grammar:91413:ex2:structure":"〔noun〕は＋〔noun〕です","grammar:91413:ex2:words:0:zh":"new","grammar:91413:ex2:words:0:note":"あたらしい","grammar:91413:ex2:words:0:pos":"adjective","grammar:91413:ex2:words:1:zh":"principal","grammar:91413:ex2:words:1:note":"こうちょう","grammar:91413:ex2:words:1:pos":"noun","grammar:91413:ex2:words:2:zh":"(topic)","grammar:91413:ex2:words:2:pos":"particle","grammar:91413:ex2:words:3:zh":"female","grammar:91413:ex2:words:3:note":"じょせい","grammar:91413:ex2:words:3:pos":"noun","grammar:91413:ex2:words:4:zh":"is (polite form)","grammar:91413:ex2:words:4:pos":"copula","grammar:91413:ex2:points:0":"新しい校長: the new principal","grammar:91413:ex2:points:1":"女性 = woman (formal)"},"91414":{"example:91414:exzh":"It's hot, so let's turn on the air conditioning.","example:91414:exzh2":"The air conditioning in this room is too strong.","grammar:91414:ex:trans":"It is hot, so let's turn on the air conditioning.","grammar:91414:ex:structure":"〜から、＋冷房をつけましょう","grammar:91414:ex:explain":"「冷房」 is the equipment or function that cools a room; in daily life people also say 「クーラー」 or 「エアコン」. To turn the cooling on use 「つける」, to turn it off use 「消す」. This sentence uses 「から」 for the reason and 「〜ましょう」 to suggest doing it together.","grammar:91414:ex:words:0:zh":"hot","grammar:91414:ex:words:0:note":"あつい","grammar:91414:ex:words:0:pos":"adjective","grammar:91414:ex:words:1:zh":"because","grammar:91414:ex:words:1:pos":"particle","grammar:91414:ex:words:2:zh":"air conditioner","grammar:91414:ex:words:2:note":"れいぼう","grammar:91414:ex:words:2:pos":"noun","grammar:91414:ex:words:3:zh":"(object marker)","grammar:91414:ex:words:3:pos":"particle","grammar:91414:ex:words:4:zh":"let's turn on","grammar:91414:ex:words:4:note":"つけましょう; masu-form of つける + ましょう","grammar:91414:ex:words:4:pos":"verb","grammar:91414:ex:points:0":"冷房 = air conditioning (the function that cools a room); heating is 「暖房」 (だんぼう)","grammar:91414:ex:points:1":"冷房をつける: turn on the air conditioning; turn it off with 「冷房を消す」","grammar:91414:ex2:trans":"The air conditioning in this room is too strong.","grammar:91414:ex2:structure":"冷房が＋効きすぎです","grammar:91414:ex2:words:0:zh":"this","grammar:91414:ex2:words:0:pos":"pre-noun adjectival","grammar:91414:ex2:words:1:zh":"room","grammar:91414:ex2:words:1:note":"へや","grammar:91414:ex2:words:1:pos":"noun","grammar:91414:ex2:words:2:zh":"(topic)","grammar:91414:ex2:words:2:pos":"particle","grammar:91414:ex2:words:3:zh":"air conditioner","grammar:91414:ex2:words:3:note":"れいぼう","grammar:91414:ex2:words:3:pos":"noun","grammar:91414:ex2:words:4:zh":"(nominative)","grammar:91414:ex2:words:4:pos":"particle","grammar:91414:ex2:words:5:zh":"the effect is too strong","grammar:91414:ex2:words:5:note":"ききすぎ; noun form of 効く + すぎる","grammar:91414:ex2:words:5:pos":"noun","grammar:91414:ex2:words:6:zh":"is (polite form)","grammar:91414:ex2:words:6:pos":"copula","grammar:91414:ex2:points:0":"冷房が効く: the air conditioning works and the room gets cool; 「効きすぎ」 = too cool","grammar:91414:ex2:points:1":"〜すぎ: too ~; masu-stem of a verb + すぎ"},"91415":{"example:91415:exzh":"Don't be shy—have plenty.","example:91415:exzh2":"Please refrain from smoking here.","grammar:91415:ex:trans":"Don't hold back, eat a lot.","grammar:91415:ex:structure":"遠慮しないで、＋〜てください","grammar:91415:ex:explain":"「遠慮」 means holding back out of consideration for others, being reserved. When treating someone, people often say 「遠慮しないで」 to invite them to eat freely. Another use is a soft decline or refraining from something (see the second sentence). Japanese culture values 「遠慮」 highly, so the word comes up very often.","grammar:91415:ex:words:0:zh":"don't hold back","grammar:91415:ex:words:0:note":"えんりょしないで; nai-form of 遠慮する + で","grammar:91415:ex:words:0:pos":"verb","grammar:91415:ex:words:1:zh":"a lot","grammar:91415:ex:words:1:pos":"adverb","grammar:91415:ex:words:2:zh":"eat","grammar:91415:ex:words:2:note":"たべて; te-form of 食べる","grammar:91415:ex:words:2:pos":"verb","grammar:91415:ex:words:3:zh":"please ~","grammar:91415:ex:words:3:note":"ください; the imperative form of くださる","grammar:91415:ex:words:3:pos":"auxiliary verb","grammar:91415:ex:points:0":"遠慮する = to hold back, to be reserved; 「遠慮しないで」 = don't hold back","grammar:91415:ex:points:1":"〜ないで: without doing ~ (then do what follows)","grammar:91415:ex2:trans":"Please refrain from smoking here.","grammar:91415:ex2:structure":"〔matter〕は＋ご遠慮ください","grammar:91415:ex2:words:0:zh":"here","grammar:91415:ex2:words:0:pos":"pronoun","grammar:91415:ex2:words:1:zh":"in (a place)","grammar:91415:ex2:words:1:pos":"particle","grammar:91415:ex2:words:2:zh":"'s","grammar:91415:ex2:words:2:pos":"particle","grammar:91415:ex2:words:3:zh":"cigarette","grammar:91415:ex2:words:3:pos":"noun","grammar:91415:ex2:words:4:zh":"(topic)","grammar:91415:ex2:words:4:pos":"particle","grammar:91415:ex2:words:5:zh":"(respectful prefix)","grammar:91415:ex2:words:5:pos":"prefix","grammar:91415:ex2:words:6:zh":"refused","grammar:91415:ex2:words:6:note":"えんりょ","grammar:91415:ex2:words:6:pos":"noun","grammar:91415:ex2:words:7:zh":"please ~","grammar:91415:ex2:words:7:note":"ください; the imperative form of くださる","grammar:91415:ex2:words:7:pos":"auxiliary verb","grammar:91415:ex2:points:0":"ご遠慮ください = please refrain from ~; a polite way of prohibiting something in public places","grammar:91415:ex2:points:1":"「ここでの」: here, at this place; 「で」 + 「の」 modifies a noun"},"91416":{"example:91416:exzh":"Please speak a little more clearly.","example:91416:exzh2":"I can see the mountains clearly today.","grammar:91416:ex:trans":"Please speak a little more clearly.","grammar:91416:ex:structure":"もう少し＋はっきり＋〔verb te-form〕ください","grammar:91416:ex:explain":"「はっきり」 describes a sound, appearance, or meaning that is clear with nothing vague about it. 「はっきり話す」 means to speak clearly, while 「はっきり言う」 means to say something directly, without beating around the bush. Like 「ゆっくり話してください」, this is a very useful request when you cannot catch what someone says.","grammar:91416:ex:words:0:zh":"a little more","grammar:91416:ex:words:0:note":"もうすこし","grammar:91416:ex:words:0:pos":"adverb","grammar:91416:ex:words:1:zh":"clearly","grammar:91416:ex:words:1:pos":"adverb","grammar:91416:ex:words:2:zh":"tell","grammar:91416:ex:words:2:note":"はなして; te-form of 話す","grammar:91416:ex:words:2:pos":"verb","grammar:91416:ex:words:3:zh":"please ~","grammar:91416:ex:words:3:note":"ください; the imperative form of くださる","grammar:91416:ex:words:3:pos":"auxiliary verb","grammar:91416:ex:points:0":"はっきり = clearly, distinctly; it works for sounds, visible things, and attitudes","grammar:91416:ex:points:1":"〜てください: please ~; adding 「もう少し」 makes the request gentler","grammar:91416:ex2:trans":"The mountains are clearly visible today.","grammar:91416:ex2:structure":"〔thing〕が＋はっきり見えます","grammar:91416:ex2:words:0:zh":"today","grammar:91416:ex2:words:0:note":"きょう","grammar:91416:ex2:words:0:pos":"noun","grammar:91416:ex2:words:1:zh":"(topic)","grammar:91416:ex2:words:1:pos":"particle","grammar:91416:ex2:words:2:zh":"mountain","grammar:91416:ex2:words:2:note":"やま","grammar:91416:ex2:words:2:pos":"noun","grammar:91416:ex2:words:3:zh":"(nominative)","grammar:91416:ex2:words:3:pos":"particle","grammar:91416:ex2:words:4:zh":"clearly","grammar:91416:ex2:words:4:pos":"adverb","grammar:91416:ex2:words:5:zh":"to be visible","grammar:91416:ex2:words:5:note":"みえます; the masu-form of 見える","grammar:91416:ex2:words:5:pos":"verb","grammar:91416:ex2:points:0":"はっきり見える: be clearly visible","grammar:91416:ex2:points:1":"見える: to be visible naturally; the thing seen takes 「が」"},"91417":{"example:91417:exzh":"I gave my teacher a souvenir.","example:91417:exzh2":"I'll give you a call later.","grammar:91417:ex:trans":"I gave a souvenir to the teacher.","grammar:91417:ex:structure":"〔someone above you〕に＋〔thing〕を差し上げる","grammar:91417:ex:explain":"「差し上げる」 is more polite than 「あげる」: it lowers yourself to show respect to the person receiving. The recipient takes 「に」. 「お土産」 is a souvenir brought back from a trip, and its reading 「おみやげ」 is unusual.","grammar:91417:ex:words:0:zh":"teacher","grammar:91417:ex:words:0:note":"せんせい","grammar:91417:ex:words:0:pos":"noun","grammar:91417:ex:words:1:zh":"to give (to someone)","grammar:91417:ex:words:1:pos":"particle","grammar:91417:ex:words:2:zh":"(beautifying prefix)","grammar:91417:ex:words:2:pos":"prefix","grammar:91417:ex:words:3:zh":"souvenir","grammar:91417:ex:words:3:note":"みやげ","grammar:91417:ex:words:3:pos":"noun","grammar:91417:ex:words:4:zh":"(object marker)","grammar:91417:ex:words:4:pos":"particle","grammar:91417:ex:words:5:zh":"give (humble)","grammar:91417:ex:words:5:note":"さしあげました; past masu-form of 差し上げる","grammar:91417:ex:words:5:pos":"verb","grammar:91417:ex:points:0":"差し上げる = humble form of 「あげる」; used when giving something to someone older, a boss, or a guest","grammar:91417:ex:points:1":"Use 「あげる」 for equals, and 「やる」 for people below you, animals, or plants","grammar:91417:ex2:trans":"I will call you later.","grammar:91417:ex2:structure":"お〔noun〕を＋差し上げます","grammar:91417:ex2:words:0:zh":"later, afterwards","grammar:91417:ex2:words:0:pos":"adverb","grammar:91417:ex2:words:1:zh":"(humble prefix)","grammar:91417:ex2:words:1:pos":"prefix","grammar:91417:ex2:words:2:zh":"phone call","grammar:91417:ex2:words:2:note":"でんわ","grammar:91417:ex2:words:2:pos":"noun","grammar:91417:ex2:words:3:zh":"(object marker)","grammar:91417:ex2:words:3:pos":"particle","grammar:91417:ex2:words:4:zh":"give (humble)","grammar:91417:ex2:words:4:note":"さしあげます; masu-form of 差し上げる","grammar:91417:ex2:words:4:pos":"verb","grammar:91417:ex2:points:0":"お電話を差し上げます: I will give you a call; common in business phone calls","grammar:91417:ex2:points:1":"「差し上げる」 can also be used for things done for the other person, such as calling or getting in touch"},"91418":{"example:91418:exzh":"My younger brother starts elementary school next year.","example:91418:exzh2":"The entrance ceremony is in April.","grammar:91418:ex:trans":"My younger brother starts elementary school next year.","grammar:91418:ex:structure":"〔school〕に＋入学する","grammar:91418:ex:explain":"「入学」 means entering a school and becoming a student; adding 「する」 to the noun gives the verb 「入学する」. Watch the particles: entering takes 「〜に入学する」, while graduating takes 「〜を卒業する」. In Japan the school year starts in April.","grammar:91418:ex:words:0:zh":"younger brother","grammar:91418:ex:words:0:note":"おとうと","grammar:91418:ex:words:0:pos":"noun","grammar:91418:ex:words:1:zh":"(topic)","grammar:91418:ex:words:1:pos":"particle","grammar:91418:ex:words:2:zh":"next year","grammar:91418:ex:words:2:note":"らいねん","grammar:91418:ex:words:2:pos":"noun","grammar:91418:ex:words:3:zh":"elementary school","grammar:91418:ex:words:3:note":"しょうがっこう","grammar:91418:ex:words:3:pos":"noun","grammar:91418:ex:words:4:zh":"into (the place entered)","grammar:91418:ex:words:4:pos":"particle","grammar:91418:ex:words:5:zh":"enter school","grammar:91418:ex:words:5:note":"にゅうがくします; masu-form of 入学する","grammar:91418:ex:words:5:pos":"verb","grammar:91418:ex:points:0":"入学する = enter a school as a student; the school entered takes 「に」","grammar:91418:ex:points:1":"Graduating is 「卒業する」 (そつぎょうする), which takes 「を」: 大学を卒業する","grammar:91418:ex2:trans":"The entrance ceremony is in April.","grammar:91418:ex2:structure":"〔event〕は＋〔time〕にあります","grammar:91418:ex2:words:0:zh":"enter school","grammar:91418:ex2:words:0:note":"にゅうがく","grammar:91418:ex2:words:0:pos":"noun","grammar:91418:ex2:words:1:zh":"ceremony","grammar:91418:ex2:words:1:note":"しき","grammar:91418:ex2:words:1:pos":"suffix","grammar:91418:ex2:words:2:zh":"(topic)","grammar:91418:ex2:words:2:pos":"particle","grammar:91418:ex2:words:3:zh":"April","grammar:91418:ex2:words:3:note":"しがつ","grammar:91418:ex2:words:3:pos":"noun","grammar:91418:ex2:words:4:zh":"(point in time)","grammar:91418:ex2:words:4:pos":"particle","grammar:91418:ex2:words:5:zh":"to be held, to take place","grammar:91418:ex2:words:5:note":"あります; the masu-form (polite form) of ある","grammar:91418:ex2:words:5:pos":"verb","grammar:91418:ex2:points:1":"the time of an event: 〜にあります"},"91419":{"example:91419:exzh":"I copied my friend's notes.","example:91419:exzh2":"Who took this photo?","grammar:91419:ex:trans":"I copied a friend's notes.","grammar:91419:ex:structure":"〔thing〕を＋写す","grammar:91419:ex:explain":"The basic meaning of 「写す」 is to copy something just as it is: with a pen it means to copy out, with a camera it means to photograph. In Japanese 「ノート」 means a notebook or notes, not a laptop (a laptop is 「ノートパソコン」).","grammar:91419:ex:words:0:zh":"friend","grammar:91419:ex:words:0:note":"ともだち","grammar:91419:ex:words:0:pos":"noun","grammar:91419:ex:words:1:zh":"'s","grammar:91419:ex:words:1:pos":"particle","grammar:91419:ex:words:2:zh":"notes","grammar:91419:ex:words:2:pos":"noun","grammar:91419:ex:words:3:zh":"(object marker)","grammar:91419:ex:words:3:pos":"particle","grammar:91419:ex:words:4:zh":"copied","grammar:91419:ex:words:4:note":"うつしました; past masu-form of 写す","grammar:91419:ex:words:4:pos":"verb","grammar:91419:ex:points:0":"写す = to copy something as it is; ノートを写す = copy notes","grammar:91419:ex:points:1":"It can also mean to take a photo (see the second sentence)","grammar:91419:ex2:trans":"Who took this photo?","grammar:91419:ex2:structure":"〔thing〕は＋だれが〜たんですか","grammar:91419:ex2:words:0:zh":"this","grammar:91419:ex2:words:0:pos":"pre-noun adjectival","grammar:91419:ex2:words:1:zh":"photo","grammar:91419:ex2:words:1:note":"しゃしん","grammar:91419:ex2:words:1:pos":"noun","grammar:91419:ex2:words:2:zh":"(topic)","grammar:91419:ex2:words:2:pos":"particle","grammar:91419:ex2:words:3:zh":"who","grammar:91419:ex2:words:3:pos":"question word","grammar:91419:ex2:words:4:zh":"(nominative)","grammar:91419:ex2:words:4:pos":"particle","grammar:91419:ex2:words:5:zh":"took (a photo)","grammar:91419:ex2:words:5:note":"うつした; ta-form of 写す","grammar:91419:ex2:words:5:pos":"verb","grammar:91419:ex2:words:6:zh":"(explanatory tone)","grammar:91419:ex2:words:6:pos":"formal noun","grammar:91419:ex2:words:7:zh":"is (polite form)","grammar:91419:ex2:words:7:pos":"copula","grammar:91419:ex2:words:8:zh":"(question)","grammar:91419:ex2:words:8:pos":"particle","grammar:91419:ex2:points:0":"写真を写す: take a photo; in casual speech 「写真を撮る」 (とる) is more common","grammar:91419:ex2:points:1":"〜んですか: adds an explanatory tone when asking about a reason or background"},"91420":{"example:91420:exzh":"Two plus three makes five.","example:91420:exzh2":"Please add a little salt to the soup.","grammar:91420:ex:trans":"Two plus three makes five.","grammar:91420:ex:structure":"A に B を足すと＋C になります","grammar:91420:ex:explain":"「足す」 means to add an amount on, so in arithmetic it is plus. The pattern is 「AにBを足す」: the number added to takes 「に」 and the number added takes 「を」. Other operations: 引く (minus), かける (times), 割る (divided by).","grammar:91420:ex:words:0:zh":"two","grammar:91420:ex:words:0:note":"に","grammar:91420:ex:words:0:pos":"numeral","grammar:91420:ex:words:1:zh":"(the thing being added to)","grammar:91420:ex:words:1:pos":"particle","grammar:91420:ex:words:2:zh":"three","grammar:91420:ex:words:2:note":"さん","grammar:91420:ex:words:2:pos":"numeral","grammar:91420:ex:words:3:zh":"(object marker)","grammar:91420:ex:words:3:pos":"particle","grammar:91420:ex:words:4:zh":"to add, to apply","grammar:91420:ex:words:4:note":"たす","grammar:91420:ex:words:4:pos":"verb","grammar:91420:ex:words:5:zh":"(when ~, then)","grammar:91420:ex:words:5:pos":"particle","grammar:91420:ex:words:6:zh":"five","grammar:91420:ex:words:6:note":"ご","grammar:91420:ex:words:6:pos":"numeral","grammar:91420:ex:words:7:zh":"(the resulting color)","grammar:91420:ex:words:7:pos":"particle","grammar:91420:ex:words:8:zh":"become","grammar:91420:ex:words:8:note":"なります; masu-form of なる","grammar:91420:ex:words:8:pos":"verb","grammar:91420:ex:points:0":"足す = to add; 「A に B を足す」 = add B to A","grammar:91420:ex:points:1":"〜と〜になります: if ~, it becomes ~; common in arithmetic","grammar:91420:ex2:trans":"Please add a little salt to the soup.","grammar:91420:ex2:structure":"〔thing〕に＋〔thing〕を足す","grammar:91420:ex2:words:0:zh":"soup","grammar:91420:ex2:words:0:pos":"noun","grammar:91420:ex2:words:1:zh":"(the thing you add into)","grammar:91420:ex2:words:1:pos":"particle","grammar:91420:ex2:words:2:zh":"salt","grammar:91420:ex2:words:2:note":"しお","grammar:91420:ex2:words:2:pos":"noun","grammar:91420:ex2:words:3:zh":"(object marker)","grammar:91420:ex2:words:3:pos":"particle","grammar:91420:ex2:words:4:zh":"just a little bit","grammar:91420:ex2:words:4:note":"すこし","grammar:91420:ex2:words:4:pos":"adverb","grammar:91420:ex2:words:5:zh":"add","grammar:91420:ex2:words:5:note":"たして; te-form of 足す","grammar:91420:ex2:words:5:pos":"verb","grammar:91420:ex2:words:6:zh":"please ~","grammar:91420:ex2:words:6:note":"ください; the imperative form of くださる","grammar:91420:ex2:words:6:pos":"auxiliary verb","grammar:91420:ex2:points:0":"塩を足す: add a bit more salt; 「足す」 implies topping something up because it is not enough","grammar:91420:ex2:points:1":"the thing you add into takes 「に」"},"91421":{"example:91421:exzh":"They are students at the same university.","example:91421:exzh2":"They've already gone home.","grammar:91421:ex:trans":"They are students at the same university.","grammar:91421:ex:structure":"彼らは＋〔noun〕です","grammar:91421:ex:explain":"「彼ら」 is 「彼」 (he) plus the plural 「ら」 and refers to a group of people. Using 「彼ら」 for a group standing right in front of you is rather impolite; 「あの方たち」 is better. 「同じ」 is a special word that attaches directly to a noun, so you cannot say 「同じな」.","grammar:91421:ex:words:0:zh":"they","grammar:91421:ex:words:0:note":"かれら","grammar:91421:ex:words:0:pos":"pronoun","grammar:91421:ex:words:1:zh":"(topic)","grammar:91421:ex:words:1:pos":"particle","grammar:91421:ex:words:2:zh":"the same","grammar:91421:ex:words:2:note":"おなじ","grammar:91421:ex:words:2:pos":"pre-noun adjectival","grammar:91421:ex:words:3:zh":"university","grammar:91421:ex:words:3:note":"だいがく","grammar:91421:ex:words:3:pos":"noun","grammar:91421:ex:words:4:zh":"'s","grammar:91421:ex:words:4:pos":"particle","grammar:91421:ex:words:5:zh":"student","grammar:91421:ex:words:5:note":"がくせい","grammar:91421:ex:words:5:pos":"noun","grammar:91421:ex:words:6:zh":"is (polite form)","grammar:91421:ex:words:6:pos":"copula","grammar:91421:ex:points:0":"彼ら = they; 「〜ら」 added to a personal pronoun makes it plural","grammar:91421:ex:points:1":"同じ goes directly before a noun, without 「の」 or 「な」: 同じ大学","grammar:91421:ex2:trans":"They have already gone home.","grammar:91421:ex2:structure":"彼らは＋もう〜ました","grammar:91421:ex2:words:0:zh":"they","grammar:91421:ex2:words:0:note":"かれら","grammar:91421:ex2:words:0:pos":"pronoun","grammar:91421:ex2:words:1:zh":"(topic)","grammar:91421:ex2:words:1:pos":"particle","grammar:91421:ex2:words:2:zh":"already","grammar:91421:ex2:words:2:pos":"adverb","grammar:91421:ex2:words:3:zh":"went home","grammar:91421:ex2:words:3:note":"かえりました; past masu-form of 帰る","grammar:91421:ex2:words:3:pos":"verb","grammar:91421:ex2:points:0":"彼らは: they","grammar:91421:ex2:points:1":"もう + past form: already ~"},"91422":{"example:91422:exzh":"I wore a kimono at New Year's.","example:91422:exzh2":"I took a photo wearing a kimono.","grammar:91422:ex:trans":"I wore a kimono at New Year.","grammar:91422:ex:structure":"着物を＋着る","grammar:91422:ex:explain":"「着物」 is read 「きもの」 and today mainly means the traditional Japanese kimono, often worn at New Year, coming-of-age ceremonies, and weddings. Literally it means things you wear, so older speakers also use it for clothes in general. To wear a kimono, use 「着る」.","grammar:91422:ex:words:0:zh":"(beautifying prefix)","grammar:91422:ex:words:0:pos":"prefix","grammar:91422:ex:words:1:zh":"New Year","grammar:91422:ex:words:1:note":"しょうがつ","grammar:91422:ex:words:1:pos":"noun","grammar:91422:ex:words:2:zh":"(point in time)","grammar:91422:ex:words:2:pos":"particle","grammar:91422:ex:words:3:zh":"kimono","grammar:91422:ex:words:3:note":"きもの","grammar:91422:ex:words:3:pos":"noun","grammar:91422:ex:words:4:zh":"(object marker)","grammar:91422:ex:words:4:pos":"particle","grammar:91422:ex:words:5:zh":"put on","grammar:91422:ex:words:5:note":"きました; past masu-form of 着る","grammar:91422:ex:words:5:pos":"verb","grammar:91422:ex:points:0":"着物 = kimono (traditional Japanese clothing); broadly it can also mean clothes","grammar:91422:ex:points:1":"着物を着る: wear a kimono; 「着る」 is for upper-body or one-piece garments","grammar:91422:ex2:trans":"I took a photo wearing a kimono.","grammar:91422:ex2:structure":"着物を着て、＋写真をとる","grammar:91422:ex2:words:0:zh":"kimono","grammar:91422:ex2:words:0:note":"きもの","grammar:91422:ex2:words:0:pos":"noun","grammar:91422:ex2:words:1:zh":"(object marker)","grammar:91422:ex2:words:1:pos":"particle","grammar:91422:ex2:words:2:zh":"wear","grammar:91422:ex2:words:2:note":"きて; the te-form of 着る","grammar:91422:ex2:words:2:pos":"verb","grammar:91422:ex2:words:3:zh":"photo","grammar:91422:ex2:words:3:note":"しゃしん","grammar:91422:ex2:words:3:pos":"noun","grammar:91422:ex2:words:4:zh":"(object marker)","grammar:91422:ex2:words:4:pos":"particle","grammar:91422:ex2:words:5:zh":"took (a photo)","grammar:91422:ex2:words:5:note":"とりました; past masu-form of とる","grammar:91422:ex2:words:5:pos":"verb","grammar:91422:ex2:points:0":"te-form linking: take a photo while wearing a kimono","grammar:91422:ex2:points:1":"写真をとる: take a photo (written 「撮る」 in kanji)"},"91423":{"example:91423:exzh":"In winter, it gets dark early.","example:91423:exzh2":"This year's almost over too, isn't it?","grammar:91423:ex:trans":"In winter it gets dark early.","grammar:91423:ex:structure":"日が暮れる＋のが早い","grammar:91423:ex:explain":"「暮れる」 means a day or a stretch of time coming to its end, and 「日が暮れる」 means the sun sets and it gets dark. It sounds the same as 「くれる」 (to give), but the kanji and meaning are completely different. In 「日が暮れるのが早い」, 「の」 turns the action into a noun and then you say it is early.","grammar:91423:ex:words:0:zh":"winter","grammar:91423:ex:words:0:note":"ふゆ","grammar:91423:ex:words:0:pos":"noun","grammar:91423:ex:words:1:zh":"(topic)","grammar:91423:ex:words:1:pos":"particle","grammar:91423:ex:words:2:zh":"sun, daylight","grammar:91423:ex:words:2:note":"ひ","grammar:91423:ex:words:2:pos":"noun","grammar:91423:ex:words:3:zh":"(nominative)","grammar:91423:ex:words:3:pos":"particle","grammar:91423:ex:words:4:zh":"it gets dark","grammar:91423:ex:words:4:note":"くれる","grammar:91423:ex:words:4:pos":"verb","grammar:91423:ex:words:5:zh":"(turns the action into a noun)","grammar:91423:ex:words:5:pos":"formal noun","grammar:91423:ex:words:6:zh":"(nominative)","grammar:91423:ex:words:6:pos":"particle","grammar:91423:ex:words:7:zh":"early","grammar:91423:ex:words:7:note":"はやい","grammar:91423:ex:words:7:pos":"adjective","grammar:91423:ex:words:8:zh":"is (polite form)","grammar:91423:ex:words:8:pos":"copula","grammar:91423:ex:points:0":"暮れる = the sun goes down and it gets dark; 「日が暮れる」 is a set phrase","grammar:91423:ex:points:1":"〜のが早い: do ~ early or quickly; 「の」 turns the preceding clause into a noun","grammar:91423:ex2:trans":"This year is almost over too, isn't it?","grammar:91423:ex2:structure":"もうすぐ＋〔time〕も暮れます","grammar:91423:ex2:words:0:zh":"soon","grammar:91423:ex2:words:0:pos":"adverb","grammar:91423:ex2:words:1:zh":"this year","grammar:91423:ex2:words:1:note":"ことし","grammar:91423:ex2:words:1:pos":"noun","grammar:91423:ex2:words:2:zh":"also, too","grammar:91423:ex2:words:2:pos":"particle","grammar:91423:ex2:words:3:zh":"(the year) draws to a close","grammar:91423:ex2:words:3:note":"くれます; masu-form of 暮れる","grammar:91423:ex2:words:3:pos":"verb","grammar:91423:ex2:words:4:zh":"(seeking agreement) ..., right?","grammar:91423:ex2:words:4:pos":"particle","grammar:91423:ex2:points:0":"年が暮れる: the year comes to an end; the year-end is called 「年の暮れ」","grammar:91423:ex2:points:1":"もうすぐ: soon; the sentence-final 「ね」 shows you expect the other person to agree"},"91424":{"example:91424:exzh":"I'm going home to my country the week after next.","example:91424:exzh2":"The test is on Monday the week after next.","grammar:91424:ex:trans":"I am going back to my home country the week after next.","grammar:91424:ex:structure":"再来週、＋〜","grammar:91424:ex:explain":"「再来週」 is read 「さらいしゅう」; as in 「再来月」 and 「再来年」, 「再」 is read 「さ」. Relative time words like this do not take 「に」; they connect directly to the sentence.","grammar:91424:ex:words:0:zh":"the week after next","grammar:91424:ex:words:0:note":"さらいしゅう","grammar:91424:ex:words:0:pos":"noun","grammar:91424:ex:words:1:zh":"(one's own) country","grammar:91424:ex:words:1:note":"くに","grammar:91424:ex:words:1:pos":"noun","grammar:91424:ex:words:2:zh":"to","grammar:91424:ex:words:2:pos":"particle","grammar:91424:ex:words:3:zh":"go home / return","grammar:91424:ex:words:3:note":"かえります; the masu-form of 帰る","grammar:91424:ex:words:3:pos":"verb","grammar:91424:ex:points:0":"再来週 = the week after next; 「再」 is read 「さ」","grammar:91424:ex2:trans":"The test is on Monday the week after next.","grammar:91424:ex2:structure":"〔matter〕は＋再来週の〔day of the week〕です","grammar:91424:ex2:words:0:zh":"test","grammar:91424:ex2:words:0:pos":"noun","grammar:91424:ex2:words:1:zh":"(topic)","grammar:91424:ex2:words:1:pos":"particle","grammar:91424:ex2:words:2:zh":"the week after next","grammar:91424:ex2:words:2:note":"さらいしゅう","grammar:91424:ex2:words:2:pos":"noun","grammar:91424:ex2:words:3:zh":"'s","grammar:91424:ex2:words:3:pos":"particle","grammar:91424:ex2:words:4:zh":"Monday","grammar:91424:ex2:words:4:note":"げつようび","grammar:91424:ex2:words:4:pos":"noun","grammar:91424:ex2:words:5:zh":"is (polite form)","grammar:91424:ex2:words:5:pos":"copula","grammar:91424:ex2:points:0":"再来週の月曜日: Monday of the week after next","grammar:91424:ex2:points:1":"Nouns are linked with 「の」"},"91425":{"example:91425:exzh":"The ramen at this shop is pretty good.","example:91425:exzh2":"The bus just won't come.","grammar:91425:ex:trans":"The ramen at this shop is quite good.","grammar:91425:ex:structure":"「なかなか」 with an affirmative means better than expected: 「なかなかおいしい」 feels like actually pretty good. With a negative it means something completely different, just will not ~ (see the second sentence). This is a common N4 test point.","grammar:91425:ex:explain":"When 「なかなか」 is used in an affirmative sentence, it means “better than expected.” For example, 「なかなかおいしい」 has the sense of “actually quite tasty.” With a negative sentence, its meaning changes completely to “just cannot ~” (see the second sentence). This distinction is often tested at N4.","grammar:91425:ex:words:0:zh":"this","grammar:91425:ex:words:0:pos":"pre-noun adjectival","grammar:91425:ex:words:1:zh":"store","grammar:91425:ex:words:1:note":"みせ","grammar:91425:ex:words:1:pos":"noun","grammar:91425:ex:words:2:zh":"'s","grammar:91425:ex:words:2:pos":"particle","grammar:91425:ex:words:3:zh":"ramen","grammar:91425:ex:words:3:pos":"noun","grammar:91425:ex:words:4:zh":"(topic)","grammar:91425:ex:words:4:pos":"particle","grammar:91425:ex:words:5:zh":"quite, considerably","grammar:91425:ex:words:5:pos":"adverb","grammar:91425:ex:words:6:zh":"tasty","grammar:91425:ex:words:6:pos":"adjective","grammar:91425:ex:words:7:zh":"is (polite form)","grammar:91425:ex:words:7:pos":"copula","grammar:91425:ex:points:0":"なかなか＋affirmative: better than expected, quite good; carries a slight sense of surprise and praise","grammar:91425:ex:points:1":"Usually not used when evaluating someone older or of higher status (it can sound a little condescending)","grammar:91425:ex2:trans":"The bus just won't come.","grammar:91425:ex2:structure":"なかなか＋〔negative〕","grammar:91425:ex2:words:0:zh":"bus","grammar:91425:ex2:words:0:pos":"noun","grammar:91425:ex2:words:1:zh":"(nominative)","grammar:91425:ex2:words:1:pos":"particle","grammar:91425:ex2:words:2:zh":"(with a negative) still not; just won't","grammar:91425:ex2:words:2:pos":"adverb","grammar:91425:ex2:words:3:zh":"won't come","grammar:91425:ex2:words:3:note":"きません; the masu-form negative of 来る","grammar:91425:ex2:words:3:pos":"verb","grammar:91425:ex2:points:0":"なかなか＋negative: you keep waiting but it just doesn't happen; carries impatience","grammar:91425:ex2:points:1":"来ません: the negative of 来る"},"91426":{"example:91426:exzh":"Your Japanese has gotten a lot better, hasn't it?","example:91426:exzh2":"It's quite a long way to the station, you know.","grammar:91426:ex:trans":"Your Japanese has gotten so much better.","grammar:91426:ex:structure":"ずいぶん＋〔change〕","grammar:91426:ex:explain":"「ずいぶん」 expresses a fairly high degree and often carries the surprise of \"I didn't expect it to be this much.\" This sentence is a compliment at seeing how much the other person has improved. Compared with 「とても」, 「ずいぶん」 emphasizes the gap from before or from what was expected.","grammar:91426:ex:words:0:zh":"Japanese","grammar:91426:ex:words:0:note":"にほんご","grammar:91426:ex:words:0:pos":"noun","grammar:91426:ex:words:1:zh":"(nominative)","grammar:91426:ex:words:1:pos":"particle","grammar:91426:ex:words:2:zh":"considerably; quite","grammar:91426:ex:words:2:pos":"adverb","grammar:91426:ex:words:3:zh":"good; skilled","grammar:91426:ex:words:3:note":"じょうず","grammar:91426:ex:words:3:pos":"na-adjective","grammar:91426:ex:words:4:zh":"(turns into ～)","grammar:91426:ex:words:4:pos":"particle","grammar:91426:ex:words:5:zh":"become","grammar:91426:ex:words:5:note":"なりました; past masu-form of なる","grammar:91426:ex:words:5:pos":"verb","grammar:91426:ex:words:6:zh":"(seeking agreement) ..., right?","grammar:91426:ex:words:6:pos":"particle","grammar:91426:ex:points:0":"ずいぶん = a greater degree than imagined, often with a feeling of surprise","grammar:91426:ex:points:1":"na-adjective＋になる: 上手→上手になる (to get good)","grammar:91426:ex2:trans":"It's quite far to the station.","grammar:91426:ex2:structure":"〔place〕までは＋ずいぶん遠いです","grammar:91426:ex2:words:0:zh":"station","grammar:91426:ex2:words:0:note":"えき","grammar:91426:ex2:words:0:pos":"noun","grammar:91426:ex2:words:1:zh":"until","grammar:91426:ex2:words:1:pos":"particle","grammar:91426:ex2:words:2:zh":"(topic)","grammar:91426:ex2:words:2:pos":"particle","grammar:91426:ex2:words:3:zh":"quite","grammar:91426:ex2:words:3:pos":"adverb","grammar:91426:ex2:words:4:zh":"far","grammar:91426:ex2:words:4:note":"とおい","grammar:91426:ex2:words:4:pos":"adjective","grammar:91426:ex2:words:5:zh":"is (polite form)","grammar:91426:ex2:words:5:pos":"copula","grammar:91426:ex2:words:6:zh":"(reminder) よ","grammar:91426:ex2:words:6:pos":"particle","grammar:91426:ex2:points:0":"ずいぶん遠い: quite far (farther than the other person thinks)","grammar:91426:ex2:points:1":"Sentence-final 「よ」: telling the other person something they may not know"},"91427":{"example:91427:exzh":"This curry is really good.","example:91427:exzh2":"My older brother is good at drawing pictures.","grammar:91427:ex:trans":"This curry is really good.","grammar:91427:ex:structure":"〔food〕は＋うまい","grammar:91427:ex:explain":"Both 「うまい」 and 「おいしい」 mean \"tasty,\" but 「うまい」 is rougher and more casual, and it often shows up between friends or in men's speech. It also means \"skillful, good at\" (see the second sentence). The sentence-final 「ね」 shares the feeling with the other person.","grammar:91427:ex:words:0:zh":"this","grammar:91427:ex:words:0:pos":"pre-noun adjectival","grammar:91427:ex:words:1:zh":"curry","grammar:91427:ex:words:1:pos":"noun","grammar:91427:ex:words:2:zh":"(topic)","grammar:91427:ex:words:2:pos":"particle","grammar:91427:ex:words:3:zh":"tasty","grammar:91427:ex:words:3:pos":"adjective","grammar:91427:ex:words:4:zh":"(seeking agreement) ..., right?","grammar:91427:ex:words:4:pos":"particle","grammar:91427:ex:points:0":"うまい = tasty; more casual and relaxed than 「おいしい」, and mostly used by men","grammar:91427:ex:points:1":"In formal situations or when speaking to someone older, 「おいしい」 is the better choice","grammar:91427:ex2:trans":"My older brother is good at drawing.","grammar:91427:ex2:structure":"〔person〕は＋〔verb〕のがうまいです","grammar:91427:ex2:words:0:zh":"older brother","grammar:91427:ex2:words:0:note":"あに","grammar:91427:ex2:words:0:pos":"noun","grammar:91427:ex2:words:1:zh":"(topic)","grammar:91427:ex2:words:1:pos":"particle","grammar:91427:ex2:words:2:zh":"picture","grammar:91427:ex2:words:2:note":"え","grammar:91427:ex2:words:2:pos":"noun","grammar:91427:ex2:words:3:zh":"(object marker)","grammar:91427:ex2:words:3:pos":"particle","grammar:91427:ex2:words:4:zh":"picture","grammar:91427:ex2:words:4:note":"かく","grammar:91427:ex2:words:4:pos":"verb","grammar:91427:ex2:words:5:zh":"(turns the action into a noun)","grammar:91427:ex2:words:5:pos":"formal noun","grammar:91427:ex2:words:6:zh":"(nominative)","grammar:91427:ex2:words:6:pos":"particle","grammar:91427:ex2:words:7:zh":"good at","grammar:91427:ex2:words:7:pos":"adjective","grammar:91427:ex2:words:8:zh":"is (polite form)","grammar:91427:ex2:words:8:pos":"copula","grammar:91427:ex2:points:0":"うまい = skilled, technically good; close in meaning to 「上手（じょうず）」","grammar:91427:ex2:points:1":"〜のがうまい: to be good at doing ～; 「の」 turns the action into a noun"},"91428":{"example:91428:exzh":"I'm going to make tea, so I'll boil some water.","example:91428:exzh2":"I've already heated the bath water.","grammar:91428:ex:trans":"I'm going to make tea, so I'll boil some water.","grammar:91428:ex:structure":"〜ので、〔noun〕を＋沸かします","grammar:91428:ex:explain":"「沸かす」 means to heat water up and bring it to a boil; the subject is a person and the object takes 「を」. The first half, 「お茶を入れるので」, uses 「ので」 to give the reason, and the second half states the action politely in masu-form. Note that Japanese says 「お湯を沸かす」, literally \"boil hot water,\" which is simply \"boil water\" in English.","grammar:91428:ex:words:0:zh":"tea","grammar:91428:ex:words:0:note":"おちゃ; the 「お」 is a beautifying prefix","grammar:91428:ex:words:0:pos":"noun","grammar:91428:ex:words:1:zh":"(object)","grammar:91428:ex:words:1:pos":"particle","grammar:91428:ex:words:2:zh":"to make (tea)","grammar:91428:ex:words:2:note":"いれる; お茶を入れる = to make tea","grammar:91428:ex:words:2:pos":"verb","grammar:91428:ex:words:3:zh":"because","grammar:91428:ex:words:3:pos":"particle","grammar:91428:ex:words:4:zh":"hot water","grammar:91428:ex:words:4:note":"おゆ","grammar:91428:ex:words:4:pos":"noun","grammar:91428:ex:words:5:zh":"(object)","grammar:91428:ex:words:5:pos":"particle","grammar:91428:ex:words:6:zh":"to boil","grammar:91428:ex:words:6:note":"わかします; the masu-form of 沸かす","grammar:91428:ex:words:6:pos":"verb","grammar:91428:ex:points:0":"沸かす = to heat water and so on until it boils: お湯を沸かす (boil water), お風呂を沸かす (heat the bathwater)","grammar:91428:ex:points:1":"〜ので: gives the reason, \"because ～, so …\"; softer than から","grammar:91428:ex:points:2":"お茶を入れる: the fixed way to say \"make tea\"; it uses 「入れる」, not 「作る」","grammar:91428:ex2:trans":"I've already heated the bathwater.","grammar:91428:ex2:structure":"〔noun〕を＋沸かしておきました","grammar:91428:ex2:words:0:zh":"the bath(tub); bathwater","grammar:91428:ex2:words:0:note":"おふろ","grammar:91428:ex2:words:0:pos":"noun","grammar:91428:ex2:words:1:zh":"(object)","grammar:91428:ex2:words:1:pos":"particle","grammar:91428:ex2:words:2:zh":"to heat up","grammar:91428:ex2:words:2:note":"わかして; the te-form of 沸かす","grammar:91428:ex2:words:2:pos":"verb","grammar:91428:ex2:words:3:zh":"(did it) in advance","grammar:91428:ex2:words:3:note":"; the past masu-form of ておく","grammar:91428:ex2:words:3:pos":"auxiliary verb","grammar:91428:ex2:points:0":"お風呂を沸かす: to heat the bathwater; when Japanese people say \"boil the bath,\" they mean getting the bath ready","grammar:91428:ex2:points:1":"〜ておく: to do something in advance, as preparation for later"},"91429":{"example:91429:exzh":"Is this seat taken? (Is this seat free?)","example:91429:exzh2":"If it's next Tuesday, I'm free.","grammar:91429:ex:trans":"Is this seat taken? (Is this seat free?)","grammar:91429:ex:structure":"〔noun〕は＋空いていますか","grammar:91429:ex:explain":"「空く」 is read 「あく」 and means a place that was occupied becomes free. 「空いています」 expresses that it is free right now. Ask this on a train or at a restaurant when you want to sit down; if the other person answers 「はい、どうぞ」, you can sit.","grammar:91429:ex:words:0:zh":"this","grammar:91429:ex:words:0:pos":"pre-noun adjectival","grammar:91429:ex:words:1:zh":"seat","grammar:91429:ex:words:1:note":"せき","grammar:91429:ex:words:1:pos":"noun","grammar:91429:ex:words:2:zh":"(topic)","grammar:91429:ex:words:2:pos":"particle","grammar:91429:ex:words:3:zh":"free / open","grammar:91429:ex:words:3:note":"あいています; 空く＋ている","grammar:91429:ex:words:3:pos":"verb","grammar:91429:ex:words:4:zh":"(question)","grammar:91429:ex:words:4:pos":"particle","grammar:91429:ex:points:0":"空く = (a seat, space, or time) to open up; 空いている describes the state of being free right now","grammar:91429:ex:points:1":"〜ている: here it shows a continuing state, not an action in progress","grammar:91429:ex:points:2":"この席は空いていますか is the most common line when looking for a seat","grammar:91429:ex2:trans":"If it's next Tuesday, I'm free.","grammar:91429:ex2:structure":"〔time〕なら＋時間が空いています","grammar:91429:ex2:words:0:zh":"next week","grammar:91429:ex2:words:0:note":"らいしゅう","grammar:91429:ex2:words:0:pos":"noun","grammar:91429:ex2:words:1:zh":"'s","grammar:91429:ex2:words:1:pos":"particle","grammar:91429:ex2:words:2:zh":"Tuesday","grammar:91429:ex2:words:2:note":"かようび","grammar:91429:ex2:words:2:pos":"noun","grammar:91429:ex2:words:3:zh":"if it's ～","grammar:91429:ex2:words:3:pos":"particle","grammar:91429:ex2:words:4:zh":"time","grammar:91429:ex2:words:4:note":"じかん","grammar:91429:ex2:words:4:pos":"noun","grammar:91429:ex2:words:5:zh":"(subject)","grammar:91429:ex2:words:5:pos":"particle","grammar:91429:ex2:words:6:zh":"free / open","grammar:91429:ex2:words:6:note":"あいています; 空く＋ている","grammar:91429:ex2:words:6:pos":"verb","grammar:91429:ex2:points:0":"時間が空いている = to have free time; 空く can also be used for time","grammar:91429:ex2:points:1":"〜なら: attaches to a noun and means \"if it's ～\"; often used to set a condition"},"91430":{"example:91430:exzh":"About what time will the president be arriving?","example:91430:exzh2":"The professor is in the office right now.","grammar:91430:ex:trans":"About what time will the company president be coming?","grammar:91430:ex:structure":"〔person〕は＋何時ごろ＋おいでになりますか","grammar:91430:ex:explain":"「おいでになる」 is sonkeigo and can stand in for 「来る」 (come), 「行く」 (go), and 「いる」 (be); here it means \"come.\" Use it to show respect when talking about the actions of the company president, a teacher, or a guest — never for your own actions. It means about the same as 「いらっしゃる」 but is a little more polite.","grammar:91430:ex:words:0:zh":"company president","grammar:91430:ex:words:0:note":"しゃちょう","grammar:91430:ex:words:0:pos":"noun","grammar:91430:ex:words:1:zh":"(topic)","grammar:91430:ex:words:1:pos":"particle","grammar:91430:ex:words:2:zh":"what time","grammar:91430:ex:words:2:note":"なんじ","grammar:91430:ex:words:2:pos":"question word","grammar:91430:ex:words:3:zh":"around; approximately","grammar:91430:ex:words:3:pos":"suffix","grammar:91430:ex:words:4:zh":"(respectful) come","grammar:91430:ex:words:4:note":"; the masu-form of おいでになる","grammar:91430:ex:words:4:pos":"verb","grammar:91430:ex:words:5:zh":"(question)","grammar:91430:ex:words:5:pos":"particle","grammar:91430:ex:points:0":"おいでになる = the sonkeigo of 来る, 行く, and いる, used for superiors and people older than you","grammar:91430:ex:points:1":"〜ごろ: attaches to a time to mean \"around\"; 何時ごろ = around what time","grammar:91430:ex2:trans":"The teacher is in the research office right now.","grammar:91430:ex2:structure":"〔person〕は〔place〕に＋おいでになります","grammar:91430:ex2:words:0:zh":"teacher","grammar:91430:ex2:words:0:note":"せんせい","grammar:91430:ex2:words:0:pos":"noun","grammar:91430:ex2:words:1:zh":"(topic)","grammar:91430:ex2:words:1:pos":"particle","grammar:91430:ex2:words:2:zh":"now","grammar:91430:ex2:words:2:note":"いま","grammar:91430:ex2:words:2:pos":"noun","grammar:91430:ex2:words:3:zh":"research office","grammar:91430:ex2:words:3:note":"けんきゅうしつ","grammar:91430:ex2:words:3:pos":"noun","grammar:91430:ex2:words:4:zh":"in (a place)","grammar:91430:ex2:words:4:pos":"particle","grammar:91430:ex2:words:5:zh":"(respectful) be (somewhere)","grammar:91430:ex2:words:5:note":"; the masu-form of おいでになる","grammar:91430:ex2:words:5:pos":"verb","grammar:91430:ex2:points:0":"Here おいでになる = the sonkeigo of いる (to be)","grammar:91430:ex2:points:1":"〔place〕に＋いる／おいでになる: use 「に」 for the place where someone or something exists"},"91431":{"example:91431:exzh":"I had a hamburger steak for lunch.","example:91431:exzh2":"My favorite is the hamburger steak my mom makes.","grammar:91431:ex:trans":"I had a hamburger steak for lunch.","grammar:91431:ex:structure":"〔meal〕に＋〔food〕を食べました","grammar:91431:ex:explain":"「ハンバーグ」 is a patty made from ground meat and a staple of Japanese home cooking; a burger served in a bun is 「ハンバーガー」, and the two similar words are easy to mix up. The 「に」 in 「昼ごはんに」 marks what the food was for, meaning \"for lunch I had ～.\"","grammar:91431:ex:words:0:zh":"lunch","grammar:91431:ex:words:0:note":"ひるごはん","grammar:91431:ex:words:0:pos":"noun","grammar:91431:ex:words:1:zh":"as (～)","grammar:91431:ex:words:1:pos":"particle","grammar:91431:ex:words:2:zh":"hamburger steak","grammar:91431:ex:words:2:pos":"noun","grammar:91431:ex:words:3:zh":"(object)","grammar:91431:ex:words:3:pos":"particle","grammar:91431:ex:words:4:zh":"ate","grammar:91431:ex:words:4:note":"たべました; the past masu-form of 食べる","grammar:91431:ex:words:4:pos":"verb","grammar:91431:ex:points:0":"ハンバーグ = a Japanese-style hamburger steak (a ground-meat patty that's pan-fried), not a burger in a bun (that's ハンバーガー)","grammar:91431:ex:points:1":"〔meal〕に〜を食べる: 「に」 marks it as \"for lunch\"","grammar:91431:ex2:trans":"My favorite is the hamburger steak my mom makes.","grammar:91431:ex2:structure":"〔母が作る〕ハンバーグが＋一番好きです","grammar:91431:ex2:words:0:zh":"(my) mom","grammar:91431:ex2:words:0:note":"はは","grammar:91431:ex2:words:0:pos":"noun","grammar:91431:ex2:words:1:zh":"(the subject inside the modifying clause)","grammar:91431:ex2:words:1:pos":"particle","grammar:91431:ex2:words:2:zh":"do","grammar:91431:ex2:words:2:note":"つくる","grammar:91431:ex2:words:2:pos":"verb","grammar:91431:ex2:words:3:zh":"hamburger steak","grammar:91431:ex2:words:3:pos":"noun","grammar:91431:ex2:words:4:zh":"(the thing liked)","grammar:91431:ex2:words:4:pos":"particle","grammar:91431:ex2:words:5:zh":"the most","grammar:91431:ex2:words:5:note":"いちばん","grammar:91431:ex2:words:5:pos":"adverb","grammar:91431:ex2:words:6:zh":"to like","grammar:91431:ex2:words:6:note":"すき","grammar:91431:ex2:words:6:pos":"na-adjective","grammar:91431:ex2:words:7:zh":"is","grammar:91431:ex2:words:7:pos":"copula","grammar:91431:ex2:points:0":"母が作るハンバーグ: the verb goes directly before the noun to modify it, \"the hamburger steak my mom makes\"","grammar:91431:ex2:points:1":"〜が好きです: the thing you like takes 「が」; 一番 = the most"},"91432":{"example:91432:exzh":"A tree branch broke in the strong wind.","example:91432:exzh2":"I fell and broke a bone in my leg.","grammar:91432:ex:trans":"The strong wind broke a tree branch.","grammar:91432:ex:structure":"〔cause〕で＋〔noun〕が折れました","grammar:91432:ex:explain":"「折れる」 means something breaks on its own, so you say 「枝が折れました」; if a person breaks it, you use 「枝を折る」. The 「で」 in 「強い風で」 marks the cause. English may say \"the branch was broken by the wind,\" but the subject of the Japanese sentence is the branch.","grammar:91432:ex:words:0:zh":"strong","grammar:91432:ex:words:0:note":"つよい","grammar:91432:ex:words:0:pos":"adjective","grammar:91432:ex:words:1:zh":"wind","grammar:91432:ex:words:1:note":"かぜ","grammar:91432:ex:words:1:pos":"noun","grammar:91432:ex:words:2:zh":"because","grammar:91432:ex:words:2:pos":"particle","grammar:91432:ex:words:3:zh":"tree","grammar:91432:ex:words:3:note":"き","grammar:91432:ex:words:3:pos":"noun","grammar:91432:ex:words:4:zh":"'s","grammar:91432:ex:words:4:pos":"particle","grammar:91432:ex:words:5:zh":"tree branch","grammar:91432:ex:words:5:note":"えだ","grammar:91432:ex:words:5:pos":"noun","grammar:91432:ex:words:6:zh":"(subject)","grammar:91432:ex:words:6:pos":"particle","grammar:91432:ex:words:7:zh":"was cut off","grammar:91432:ex:words:7:note":"おれました; the past masu-form of 折れる","grammar:91432:ex:words:7:pos":"verb","grammar:91432:ex:points:0":"折れる = (for something long and thin) to snap or bend and break; it's an intransitive verb and takes 「が」. The transitive verb is 折る (to break ～)","grammar:91432:ex:points:1":"〔cause〕で: 「で」 marks the cause; 強い風で = because of the strong wind","grammar:91432:ex2:trans":"I fell and broke my leg.","grammar:91432:ex2:structure":"〜て、〔noun〕が折れました","grammar:91432:ex2:words:0:zh":"to fall down","grammar:91432:ex2:words:0:note":"ころんで; the te-form of 転ぶ","grammar:91432:ex2:words:0:pos":"verb","grammar:91432:ex2:words:1:zh":"leg, foot","grammar:91432:ex2:words:1:note":"あし","grammar:91432:ex2:words:1:pos":"noun","grammar:91432:ex2:words:2:zh":"'s","grammar:91432:ex2:words:2:pos":"particle","grammar:91432:ex2:words:3:zh":"bone","grammar:91432:ex2:words:3:note":"ほね","grammar:91432:ex2:words:3:pos":"noun","grammar:91432:ex2:words:4:zh":"(subject)","grammar:91432:ex2:words:4:pos":"particle","grammar:91432:ex2:words:5:zh":"was cut off","grammar:91432:ex2:words:5:note":"おれました; the past masu-form of 折れる","grammar:91432:ex2:words:5:pos":"verb","grammar:91432:ex2:points:0":"骨が折れる = to break a bone; you can also say 「骨折する」","grammar:91432:ex2:points:1":"〜て: links two events; here it carries the causal sense of \"because I fell\""},"91433":{"example:91433:exzh":"Japan imports a lot of food.","example:91433:exzh2":"This wine was imported from France.","grammar:91433:ex:trans":"Japan imports a lot of food.","grammar:91433:ex:structure":"〔country〕は〔item〕を＋輸入しています","grammar:91433:ex:explain":"「輸入」 is a noun, and adding 「する」 makes it the verb 「輸入する」. This sentence uses 「輸入しています」 to show that Japan has long been importing — an ongoing state. A common pattern is 「〔country〕から〜を輸入する」.","grammar:91433:ex:words:0:zh":"Japan","grammar:91433:ex:words:0:note":"にほん","grammar:91433:ex:words:0:pos":"noun","grammar:91433:ex:words:1:zh":"(topic)","grammar:91433:ex:words:1:pos":"particle","grammar:91433:ex:words:2:zh":"many","grammar:91433:ex:words:2:note":"おおく","grammar:91433:ex:words:2:pos":"noun","grammar:91433:ex:words:3:zh":"'s","grammar:91433:ex:words:3:pos":"particle","grammar:91433:ex:words:4:zh":"food","grammar:91433:ex:words:4:note":"たべもの","grammar:91433:ex:words:4:pos":"noun","grammar:91433:ex:words:5:zh":"(object)","grammar:91433:ex:words:5:pos":"particle","grammar:91433:ex:words:6:zh":"imports","grammar:91433:ex:words:6:note":"ゆにゅうしています; 輸入する＋ている","grammar:91433:ex:words:6:pos":"verb","grammar:91433:ex:points:1":"〜ている: shows an ongoing state or habit, not just \"right now\"","grammar:91433:ex:points:2":"多くの〜: many ～; a little more formal than たくさんの","grammar:91433:ex2:trans":"This wine was imported from France.","grammar:91433:ex2:structure":"〔country〕から輸入したもの＋です","grammar:91433:ex2:words:0:zh":"this","grammar:91433:ex2:words:0:pos":"pre-noun adjectival","grammar:91433:ex2:words:1:zh":"wine","grammar:91433:ex2:words:1:pos":"noun","grammar:91433:ex2:words:2:zh":"(topic)","grammar:91433:ex2:words:2:pos":"particle","grammar:91433:ex2:words:3:zh":"France","grammar:91433:ex2:words:3:pos":"noun","grammar:91433:ex2:words:4:zh":"from","grammar:91433:ex2:words:4:pos":"particle","grammar:91433:ex2:words:5:zh":"imported","grammar:91433:ex2:words:5:note":"ゆにゅうした; the ta-form of 輸入する","grammar:91433:ex2:words:5:pos":"verb","grammar:91433:ex2:words:6:zh":"things","grammar:91433:ex2:words:6:pos":"formal noun","grammar:91433:ex2:words:7:zh":"is","grammar:91433:ex2:words:7:pos":"copula","grammar:91433:ex2:points:0":"〔country〕から輸入する: to import from ～; 「から」 marks the source","grammar:91433:ex2:points:1":"〜したものです: \"it's a thing that was ～,\" used to explain where an item comes from"},"91434":{"example:91434:exzh":"It's not that cold today.","example:91434:exzh2":"The test wasn't that hard.","grammar:91434:ex:trans":"It's not that cold today.","grammar:91434:ex:structure":"それほど＋〜ない","grammar:91434:ex:explain":"「それほど」 is always followed by a negative and means \"not as ～ as you think.\" This sentence says that today is cold, but not very. In casual speech people often say 「そんなに寒くない」, which means almost the same thing.","grammar:91434:ex:words:0:zh":"today","grammar:91434:ex:words:0:note":"きょう","grammar:91434:ex:words:0:pos":"noun","grammar:91434:ex:words:1:zh":"(topic)","grammar:91434:ex:words:1:pos":"particle","grammar:91434:ex:words:2:zh":"not that (much)","grammar:91434:ex:words:2:pos":"adverb","grammar:91434:ex:words:3:zh":"doesn't get cold","grammar:91434:ex:words:3:note":"さむくない; the negative of 寒い","grammar:91434:ex:words:3:pos":"adjective","grammar:91434:ex:words:4:zh":"(polite)","grammar:91434:ex:words:4:pos":"copula","grammar:91434:ex:points:0":"それほど takes a negative after it and means \"not that ～\"; the degree is low","grammar:91434:ex:points:1":"i-adjective negative: 寒い→寒くない; add です for the polite form","grammar:91434:ex2:trans":"The test wasn't that hard.","grammar:91434:ex2:structure":"それほど＋〜くありませんでした","grammar:91434:ex2:words:0:zh":"test","grammar:91434:ex2:words:0:pos":"noun","grammar:91434:ex2:words:1:zh":"(topic)","grammar:91434:ex2:words:1:pos":"particle","grammar:91434:ex2:words:2:zh":"not that (much)","grammar:91434:ex2:words:2:pos":"adverb","grammar:91434:ex2:words:3:zh":"difficult","grammar:91434:ex2:words:3:note":"むずかしく; continuative form of 難しい","grammar:91434:ex2:words:3:pos":"adjective","grammar:91434:ex2:words:4:zh":"there wasn't (past)","grammar:91434:ex2:words:4:note":"; the past negative polite form of ある","grammar:91434:ex2:words:4:pos":"verb","grammar:91434:ex2:points:0":"それほど＋negative: not that ～","grammar:91434:ex2:points:1":"難しくありませんでした = 難しくなかったです; the more formal past negative"},"91435":{"example:91435:exzh":"If you take the limited express, you'll get there in an hour.","example:91435:exzh2":"The limited express costs a little more.","grammar:91435:ex:trans":"If you take the limited express, you'll get there in an hour.","grammar:91435:ex:structure":"〔transport〕に乗れば＋〔time〕で着きます","grammar:91435:ex:explain":"「特急」 is short for 「特別急行」, the fastest train with the fewest stops; on most lines you need to buy a limited-express ticket on top of the fare. 「特急に乗れば」 uses 「ば」 for the condition: if you take the limited express, you get there in an hour. Note that the particle for boarding is 「に」, not 「を」.","grammar:91435:ex:words:0:zh":"limited express","grammar:91435:ex:words:0:note":"とっきゅう","grammar:91435:ex:words:0:pos":"noun","grammar:91435:ex:words:1:zh":"(what you ride)","grammar:91435:ex:words:1:pos":"particle","grammar:91435:ex:words:2:zh":"if you take","grammar:91435:ex:words:2:note":"のれば; the ba-form of 乗る","grammar:91435:ex:words:2:pos":"verb","grammar:91435:ex:words:3:zh":"one hour","grammar:91435:ex:words:3:note":"いちじかん","grammar:91435:ex:words:3:pos":"numeral with counter","grammar:91435:ex:words:4:zh":"takes (time)","grammar:91435:ex:words:4:pos":"particle","grammar:91435:ex:words:5:zh":"arrive","grammar:91435:ex:words:5:note":"つきます; masu-form of 着く","grammar:91435:ex:words:5:pos":"verb","grammar:91435:ex:points:0":"特急 = a limited-express train, faster than an express or rapid train and with fewer stops; you usually pay a limited-express fee on top","grammar:91435:ex:points:1":"〜に乗る: vehicles take 「に」","grammar:91435:ex:points:2":"〜ば: the conditional \"if ～\"; the 「で」 in 一時間で marks the time required","grammar:91435:ex2:trans":"The limited express costs a little more.","grammar:91435:ex2:structure":"〔A〕は〔B〕が＋adjective","grammar:91435:ex2:words:0:zh":"limited express","grammar:91435:ex2:words:0:note":"とっきゅう","grammar:91435:ex2:words:0:pos":"noun","grammar:91435:ex2:words:1:zh":"(topic)","grammar:91435:ex2:words:1:pos":"particle","grammar:91435:ex2:words:2:zh":"fare; charge","grammar:91435:ex2:words:2:note":"りょうきん","grammar:91435:ex2:words:2:pos":"noun","grammar:91435:ex2:words:3:zh":"(subject)","grammar:91435:ex2:words:3:pos":"particle","grammar:91435:ex2:words:4:zh":"a little","grammar:91435:ex2:words:4:note":"すこし","grammar:91435:ex2:words:4:pos":"adverb","grammar:91435:ex2:words:5:zh":"expensive","grammar:91435:ex2:words:5:note":"たかい","grammar:91435:ex2:words:5:pos":"adjective","grammar:91435:ex2:words:6:zh":"(polite)","grammar:91435:ex2:words:6:pos":"copula","grammar:91435:ex2:points:1":"AはBが〜: \"A's B is ～\"; 特急は料金が高い = the limited express fare is high"},"91436":{"example:91436:exzh":"I parked the car in the parking lot.","example:91436:exzh2":"This shop doesn't have a parking lot.","grammar:91436:ex:trans":"I parked the car in the parking lot.","grammar:91436:ex:structure":"〔place〕に＋車を止めました","grammar:91436:ex:explain":"The 「場」 in 「駐車場」 is read 「じょう」 here, not 「ば」. 「車を止める」 is the usual way to say \"park a car,\" and the place where you park takes 「に」, as in 「駐車場に止める」.","grammar:91436:ex:words:0:zh":"parking lot","grammar:91436:ex:words:0:note":"ちゅうしゃじょう","grammar:91436:ex:words:0:pos":"noun","grammar:91436:ex:words:1:zh":"at (the destination)","grammar:91436:ex:words:1:pos":"particle","grammar:91436:ex:words:2:zh":"car","grammar:91436:ex:words:2:note":"くるま","grammar:91436:ex:words:2:pos":"noun","grammar:91436:ex:words:3:zh":"(object)","grammar:91436:ex:words:3:pos":"particle","grammar:91436:ex:words:4:zh":"stopped","grammar:91436:ex:words:4:note":"とめました; the past masu-form of 止める","grammar:91436:ex:words:4:pos":"verb","grammar:91436:ex:points:0":"駐車場 = parking lot; read ちゅうしゃじょう, with 「場」 read じょう","grammar:91436:ex:points:1":"車を止める = to park the car; the place where it's parked takes 「に」","grammar:91436:ex2:trans":"This shop doesn't have a parking lot.","grammar:91436:ex2:structure":"〔place〕には＋〔noun〕がありません","grammar:91436:ex2:words:0:zh":"this","grammar:91436:ex2:words:0:pos":"pre-noun adjectival","grammar:91436:ex2:words:1:zh":"store","grammar:91436:ex2:words:1:note":"みせ","grammar:91436:ex2:words:1:pos":"noun","grammar:91436:ex2:words:2:zh":"exist","grammar:91436:ex2:words:2:pos":"particle","grammar:91436:ex2:words:3:zh":"(contrast, emphasis)","grammar:91436:ex2:words:3:pos":"particle","grammar:91436:ex2:words:4:zh":"parking lot","grammar:91436:ex2:words:4:note":"ちゅうしゃじょう","grammar:91436:ex2:words:4:pos":"noun","grammar:91436:ex2:words:5:zh":"(subject)","grammar:91436:ex2:words:5:pos":"particle","grammar:91436:ex2:words:6:zh":"don't have","grammar:91436:ex2:words:6:note":"; the negative masu-form of ある","grammar:91436:ex2:words:6:pos":"verb","grammar:91436:ex2:points:0":"〔place〕に〔thing〕がある: something is somewhere; the negative is ありません","grammar:91436:ex2:points:1":"には: 「に」＋「は」, making \"this shop\" the topic"},"91437":{"example:91437:exzh":"According to the weather forecast, it will rain tomorrow.","example:91437:exzh2":"I watch the weather forecast on TV every morning.","grammar:91437:ex:trans":"According to the weather forecast, it will rain tomorrow.","grammar:91437:ex:structure":"〔source〕によると、〜","grammar:91437:ex:explain":"「天気予報」 is made of 「天気」 (weather) ＋ 「予報」 (forecast). 「〜によると」 means \"according to ～\" and states where the information comes from. Japanese often describes the weather with a simple noun sentence like 「明日は雨です」, which means it will rain tomorrow.","grammar:91437:ex:words:0:zh":"weather forecast","grammar:91437:ex:words:0:note":"てんきよほう","grammar:91437:ex:words:0:pos":"noun","grammar:91437:ex:words:1:zh":"basis, grounds","grammar:91437:ex:words:1:pos":"Expression","grammar:91437:ex:words:2:zh":"tomorrow","grammar:91437:ex:words:2:note":"あした","grammar:91437:ex:words:2:pos":"noun","grammar:91437:ex:words:3:zh":"(topic)","grammar:91437:ex:words:3:pos":"particle","grammar:91437:ex:words:4:zh":"rain","grammar:91437:ex:words:4:note":"あめ","grammar:91437:ex:words:4:pos":"noun","grammar:91437:ex:words:5:zh":"is","grammar:91437:ex:words:5:pos":"copula","grammar:91437:ex:points:0":"天気予報 = weather forecast; 天気予報を見る／聞く = to watch／listen to the weather forecast","grammar:91437:ex:points:1":"〜によると: states the source of information; it's often followed by 「〜そうです」","grammar:91437:ex2:trans":"I watch the weather forecast on TV every morning.","grammar:91437:ex2:structure":"〔means〕で＋〔noun〕を見ます","grammar:91437:ex2:words:0:zh":"every morning","grammar:91437:ex2:words:0:note":"まいあさ","grammar:91437:ex2:words:0:pos":"noun","grammar:91437:ex2:words:1:zh":"TV","grammar:91437:ex2:words:1:pos":"noun","grammar:91437:ex2:words:2:zh":"by; through; in","grammar:91437:ex2:words:2:pos":"particle","grammar:91437:ex2:words:3:zh":"weather forecast","grammar:91437:ex2:words:3:note":"てんきよほう","grammar:91437:ex2:words:3:pos":"noun","grammar:91437:ex2:words:4:zh":"(object)","grammar:91437:ex2:words:4:pos":"particle","grammar:91437:ex2:words:5:zh":"look","grammar:91437:ex2:words:5:note":"みます; the masu-form of 見る","grammar:91437:ex2:words:5:pos":"verb","grammar:91437:ex2:points:0":"天気予報を見る: to watch the weather forecast","grammar:91437:ex2:points:1":"テレビで: 「で」 marks the tool or medium you use"},"91438":{"example:91438:exzh":"I had a fever yesterday, so I didn't go to school.","example:91438:exzh2":"And then? What happened after that?","grammar:91438:ex:trans":"I had a fever yesterday, so I didn't go to school.","grammar:91438:ex:structure":"〜。それで、〜","grammar:91438:ex:explain":"「それで」 picks up the reason in the previous sentence and gives the result: \"so.\" It's more objective and softer than 「だから」 and is often used when explaining how something happened. 「学校を休む」 means to stay away from school, to take the day off — not to rest at school.","grammar:91438:ex:words:0:zh":"yesterday","grammar:91438:ex:words:0:note":"きのう","grammar:91438:ex:words:0:pos":"noun","grammar:91438:ex:words:1:zh":"(topic)","grammar:91438:ex:words:1:pos":"particle","grammar:91438:ex:words:2:zh":"fever, temperature","grammar:91438:ex:words:2:note":"ねつ","grammar:91438:ex:words:2:pos":"noun","grammar:91438:ex:words:3:zh":"(subject)","grammar:91438:ex:words:3:pos":"particle","grammar:91438:ex:words:4:zh":"there was","grammar:91438:ex:words:4:note":"; the past masu-form of ある","grammar:91438:ex:words:4:pos":"verb","grammar:91438:ex:words:5:zh":"so / therefore","grammar:91438:ex:words:5:pos":"conjunction","grammar:91438:ex:words:6:zh":"school","grammar:91438:ex:words:6:note":"がっこう","grammar:91438:ex:words:6:pos":"noun","grammar:91438:ex:words:7:zh":"(the place being left)","grammar:91438:ex:words:7:pos":"particle","grammar:91438:ex:words:8:zh":"take time off / stay away","grammar:91438:ex:words:8:note":"やすみました; the past masu-form of 休む","grammar:91438:ex:words:8:pos":"verb","grammar:91438:ex:points:0":"それで: placed at the start of a sentence to link it to the previous one, meaning \"because of that, ～\"","grammar:91438:ex:points:1":"熱がある = to have a fever","grammar:91438:ex:points:2":"学校を休む = to take the day off school","grammar:91438:ex2:trans":"So? What happened after that?","grammar:91438:ex2:structure":"それで、〜んですか","grammar:91438:ex2:words:0:zh":"and then?","grammar:91438:ex2:words:0:pos":"conjunction","grammar:91438:ex2:words:1:zh":"later, afterwards","grammar:91438:ex2:words:1:note":"そのご","grammar:91438:ex2:words:1:pos":"noun","grammar:91438:ex2:words:2:zh":"how","grammar:91438:ex2:words:2:pos":"adverb","grammar:91438:ex2:words:3:zh":"became","grammar:91438:ex2:words:3:note":"; the ta-form of なる","grammar:91438:ex2:words:3:pos":"verb","grammar:91438:ex2:words:4:zh":"(explanatory tone)","grammar:91438:ex2:words:4:note":"; the casual form of のだ","grammar:91438:ex2:words:4:pos":"formal noun","grammar:91438:ex2:words:5:zh":"(polite)","grammar:91438:ex2:words:5:pos":"copula","grammar:91438:ex2:words:6:zh":"(question)","grammar:91438:ex2:words:6:pos":"particle","grammar:91438:ex2:points:0":"それで can also urge the other person to keep talking: \"And then?\"","grammar:91438:ex2:points:1":"どうなったんですか: \"what happened after that?\"; 〜んですか shows you're curious and want to know"},"91439":{"example:91439:exzh":"Please send the map by fax.","example:91439:exzh2":"A fax arrived at the company.","grammar:91439:ex:trans":"Please send the map by fax.","grammar:91439:ex:structure":"〔thing〕を〔tool〕で＋送ってください","grammar:91439:ex:explain":"「ファックス」 means fax and is also written 「FAX」. The 「で」 in 「ファックスで送る」 marks the method used to send, the same pattern as 「メールで送る」. The sentence-final 「〜てください」 is a polite way to ask someone to do something.","grammar:91439:ex:words:0:zh":"map","grammar:91439:ex:words:0:note":"ちず","grammar:91439:ex:words:0:pos":"noun","grammar:91439:ex:words:1:zh":"(object)","grammar:91439:ex:words:1:pos":"particle","grammar:91439:ex:words:2:zh":"fax","grammar:91439:ex:words:2:pos":"noun","grammar:91439:ex:words:3:zh":"use","grammar:91439:ex:words:3:pos":"particle","grammar:91439:ex:words:4:zh":"to send","grammar:91439:ex:words:4:note":"おくって; te-form of 送る","grammar:91439:ex:words:4:pos":"verb","grammar:91439:ex:words:5:zh":"please","grammar:91439:ex:words:5:pos":"auxiliary verb","grammar:91439:ex:points:0":"ファックスで送る = to send by fax; ファックスが届く = a fax arrives","grammar:91439:ex:points:1":"〜で: marks the tool or method","grammar:91439:ex:points:2":"〜てください: a polite request for someone to do something","grammar:91439:ex2:trans":"A fax arrived at the office.","grammar:91439:ex2:structure":"〔place〕に＋〔thing〕が届きました","grammar:91439:ex2:words:0:zh":"company","grammar:91439:ex2:words:0:note":"かいしゃ","grammar:91439:ex2:words:0:pos":"noun","grammar:91439:ex2:words:1:zh":"to (a place)","grammar:91439:ex2:words:1:pos":"particle","grammar:91439:ex2:words:2:zh":"fax","grammar:91439:ex2:words:2:pos":"noun","grammar:91439:ex2:words:3:zh":"(subject)","grammar:91439:ex2:words:3:pos":"particle","grammar:91439:ex2:words:4:zh":"arrived","grammar:91439:ex2:words:4:note":"とどきました; the past masu-form of 届く","grammar:91439:ex2:words:4:pos":"verb","grammar:91439:ex2:points:0":"ファックスが届く: a fax arrives","grammar:91439:ex2:points:1":"〔place〕に〜が届く: something reaches a place; the thing is the subject, so it takes 「が」"},"91440":{"example:91440:exzh":"During summer vacation I'm going to my grandmother's house in the countryside.","example:91440:exzh2":"My hometown is near the mountains.","grammar:91440:ex:trans":"I'm going to my grandmother's house in the country over summer break.","grammar:91440:ex:structure":"〔time〕に＋〔place〕へ行きます","grammar:91440:ex:explain":"「田舎」 is read 「いなか」; it's an irregular reading, so memorize it as a whole. It has two meanings: the countryside (as opposed to the city) and your hometown. In this sentence, 「田舎の祖母の家」 means \"my grandmother's house in the country.\"","grammar:91440:ex:words:0:zh":"summer vacation","grammar:91440:ex:words:0:note":"なつやすみ","grammar:91440:ex:words:0:pos":"noun","grammar:91440:ex:words:1:zh":"in (time)","grammar:91440:ex:words:1:pos":"particle","grammar:91440:ex:words:2:zh":"countryside; hometown","grammar:91440:ex:words:2:note":"いなか","grammar:91440:ex:words:2:pos":"noun","grammar:91440:ex:words:3:zh":"'s","grammar:91440:ex:words:3:pos":"particle","grammar:91440:ex:words:4:zh":"(my) grandmother","grammar:91440:ex:words:4:note":"そぼ","grammar:91440:ex:words:4:pos":"noun","grammar:91440:ex:words:5:zh":"'s","grammar:91440:ex:words:5:pos":"particle","grammar:91440:ex:words:6:zh":"house","grammar:91440:ex:words:6:note":"いえ","grammar:91440:ex:words:6:pos":"noun","grammar:91440:ex:words:7:zh":"to","grammar:91440:ex:words:7:pos":"particle","grammar:91440:ex:words:8:zh":"go","grammar:91440:ex:words:8:note":"いきます; masu-form of 行く","grammar:91440:ex:words:8:pos":"verb","grammar:91440:ex:points:0":"田舎 = the countryside; it also often means your hometown, the place you were born","grammar:91440:ex:points:1":"〔place〕へ行く: 「へ」 marks direction and works much like 「に」","grammar:91440:ex:points:2":"祖母: use 祖母 for your own grandmother when talking to outsiders, and おばあさん for someone else's grandmother","grammar:91440:ex2:trans":"My hometown is near the mountains.","grammar:91440:ex2:structure":"わたしの田舎は＋〔place〕です","grammar:91440:ex2:words:0:zh":"I","grammar:91440:ex2:words:0:pos":"pronoun","grammar:91440:ex2:words:1:zh":"'s","grammar:91440:ex2:words:1:pos":"particle","grammar:91440:ex2:words:2:zh":"Family home","grammar:91440:ex2:words:2:note":"いなか","grammar:91440:ex2:words:2:pos":"noun","grammar:91440:ex2:words:3:zh":"(topic)","grammar:91440:ex2:words:3:pos":"particle","grammar:91440:ex2:words:4:zh":"mountain","grammar:91440:ex2:words:4:note":"やま","grammar:91440:ex2:words:4:pos":"noun","grammar:91440:ex2:words:5:zh":"'s","grammar:91440:ex2:words:5:pos":"particle","grammar:91440:ex2:words:6:zh":"nearby","grammar:91440:ex2:words:6:note":"ちかく","grammar:91440:ex2:words:6:pos":"noun","grammar:91440:ex2:words:7:zh":"is","grammar:91440:ex2:words:7:pos":"copula","grammar:91440:ex2:points:0":"わたしの田舎 = my hometown; here 田舎 means the place where you were born","grammar:91440:ex2:points:1":"〜の近く: near ～"},"91441":{"example:91441:exzh":"My older sister is a high school student.","example:91441:exzh2":"When I was in high school, I was in the tennis club.","grammar:91441:ex:trans":"My older sister is a high school student.","grammar:91441:ex:structure":"〔person〕は＋〔status〕です","grammar:91441:ex:explain":"The Japanese 「高校」 is short for 「高等学校」 and means high school, so 「高校生」 is a high school student. A junior high student is 「中学生」 and a university student is 「大学生」. 「姉」 is how you refer to your own older sister when talking to outsiders.","grammar:91441:ex:words:0:zh":"(my) older sister","grammar:91441:ex:words:0:note":"あね","grammar:91441:ex:words:0:pos":"noun","grammar:91441:ex:words:1:zh":"(topic)","grammar:91441:ex:words:1:pos":"particle","grammar:91441:ex:words:2:zh":"high school student","grammar:91441:ex:words:2:note":"こうこうせい","grammar:91441:ex:words:2:pos":"noun","grammar:91441:ex:words:3:zh":"is","grammar:91441:ex:words:3:pos":"copula","grammar:91441:ex:points:0":"高校生 = high school student; Japanese 「高校」 is high school, not college","grammar:91441:ex:points:1":"AはBです: the most basic \"A is B\" sentence pattern","grammar:91441:ex2:trans":"I was in the tennis club in high school.","grammar:91441:ex2:structure":"〔noun〕のとき、〔club〕に入っていました","grammar:91441:ex2:words:0:zh":"high school student","grammar:91441:ex2:words:0:note":"こうこうせい","grammar:91441:ex2:words:0:pos":"noun","grammar:91441:ex2:words:1:zh":"'s","grammar:91441:ex2:words:1:pos":"particle","grammar:91441:ex2:words:2:zh":"time","grammar:91441:ex2:words:2:pos":"formal noun","grammar:91441:ex2:words:3:zh":"tennis club","grammar:91441:ex2:words:3:note":"テニスぶ","grammar:91441:ex2:words:3:pos":"noun","grammar:91441:ex2:words:4:zh":"to join (a group)","grammar:91441:ex2:words:4:pos":"particle","grammar:91441:ex2:words:5:zh":"join","grammar:91441:ex2:words:5:note":"はいって; te-form of 入る","grammar:91441:ex2:words:5:pos":"verb","grammar:91441:ex2:words:6:zh":"was (in it) the whole time","grammar:91441:ex2:words:6:note":"; the past masu-form of ている","grammar:91441:ex2:words:6:pos":"auxiliary verb","grammar:91441:ex2:points:0":"高校生のとき = when I was in high school; noun＋のとき","grammar:91441:ex2:points:1":"〜部に入る = to join a club; 入っていました describes the state of being in the club back then"},"91442":{"example:91442:exzh":"You don't have to hurry so much, you know.","example:91442:exzh2":"This book wasn't that interesting.","grammar:91442:ex:trans":"You don't have to rush so much, you know.","grammar:91442:ex:structure":"そんなに＋〜なくても大丈夫です","grammar:91442:ex:explain":"「そんなに」 refers to how the other person is right now or to that degree, meaning \"as ～ as you are.\" Seeing the other person hurry, you say \"you don't have to rush that much.\" 「〜なくても大丈夫です」 is a handy pattern for reassuring someone.","grammar:91442:ex:words:0:zh":"that much","grammar:91442:ex:words:0:pos":"adverb","grammar:91442:ex:words:1:zh":"even if you don't hurry","grammar:91442:ex:words:1:note":"いそがなくても; the negative of 急ぐ＋ても","grammar:91442:ex:words:1:pos":"verb","grammar:91442:ex:words:2:zh":"it's okay","grammar:91442:ex:words:2:note":"だいじょうぶ","grammar:91442:ex:words:2:pos":"na-adjective","grammar:91442:ex:words:3:zh":"(polite)","grammar:91442:ex:words:3:pos":"copula","grammar:91442:ex:words:4:zh":"(telling the other person)","grammar:91442:ex:words:4:pos":"particle","grammar:91442:ex:points:0":"そんなに = that much, to that degree; it points to the degree of what the other person is doing (as rushed as they are)","grammar:91442:ex:points:1":"〜なくても大丈夫: you don't have to ～; used to put the other person at ease","grammar:91442:ex2:trans":"This book wasn't that interesting.","grammar:91442:ex2:structure":"そんなに＋〜なかったです","grammar:91442:ex2:words:0:zh":"this","grammar:91442:ex2:words:0:pos":"pre-noun adjectival","grammar:91442:ex2:words:1:zh":"book","grammar:91442:ex2:words:1:note":"ほん","grammar:91442:ex2:words:1:pos":"noun","grammar:91442:ex2:words:2:zh":"(topic)","grammar:91442:ex2:words:2:pos":"particle","grammar:91442:ex2:words:3:zh":"not that (much)","grammar:91442:ex2:words:3:pos":"adverb","grammar:91442:ex2:words:4:zh":"wasn't interesting (past)","grammar:91442:ex2:words:4:note":"; the past negative of おもしろい","grammar:91442:ex2:words:4:pos":"adjective","grammar:91442:ex2:words:5:zh":"(polite)","grammar:91442:ex2:words:5:pos":"copula","grammar:91442:ex2:points:0":"そんなに＋negative = not that ～; close in meaning to それほど","grammar:91442:ex2:points:1":"i-adjective past negative: おもしろい→おもしろくなかった"},"91443":{"example:91443:exzh":"During the lunch break I take a walk in the park with a friend.","example:91443:exzh2":"The lunch break at the company is one hour.","grammar:91443:ex:trans":"During lunch break I take a walk in the park with a friend.","grammar:91443:ex:structure":"〔time〕に＋〔place〕を散歩します","grammar:91443:ex:explain":"「昼休み」 is 「昼」 (midday) ＋ 「休み」 (rest) and means the lunch break at school or work. The 「を」 in 「公園を散歩します」 marks the place you walk through; that's a special use with verbs of walking and strolling.","grammar:91443:ex:words:0:zh":"lunch break","grammar:91443:ex:words:0:note":"ひるやすみ","grammar:91443:ex:words:0:pos":"noun","grammar:91443:ex:words:1:zh":"in (time)","grammar:91443:ex:words:1:pos":"particle","grammar:91443:ex:words:2:zh":"friend","grammar:91443:ex:words:2:note":"ともだち","grammar:91443:ex:words:2:pos":"noun","grammar:91443:ex:words:3:zh":"with","grammar:91443:ex:words:3:pos":"particle","grammar:91443:ex:words:4:zh":"park","grammar:91443:ex:words:4:note":"こうえん","grammar:91443:ex:words:4:pos":"noun","grammar:91443:ex:words:5:zh":"(the place you pass through)","grammar:91443:ex:words:5:pos":"particle","grammar:91443:ex:words:6:zh":"take a walk","grammar:91443:ex:words:6:note":"さんぽします; the masu-form of 散歩する","grammar:91443:ex:words:6:pos":"verb","grammar:91443:ex:points:0":"昼休み = the midday break (at school or work)","grammar:91443:ex:points:1":"〔place〕を散歩する: walking around a place takes 「を」, not 「で」","grammar:91443:ex:points:2":"〔person〕と: together with someone","grammar:91443:ex2:trans":"The lunch break at the office is one hour.","grammar:91443:ex2:structure":"〔noun〕の昼休みは＋〔time〕です","grammar:91443:ex2:words:0:zh":"company","grammar:91443:ex2:words:0:note":"かいしゃ","grammar:91443:ex2:words:0:pos":"noun","grammar:91443:ex2:words:1:zh":"'s","grammar:91443:ex2:words:1:pos":"particle","grammar:91443:ex2:words:2:zh":"lunch break","grammar:91443:ex2:words:2:note":"ひるやすみ","grammar:91443:ex2:words:2:pos":"noun","grammar:91443:ex2:words:3:zh":"(topic)","grammar:91443:ex2:words:3:pos":"particle","grammar:91443:ex2:words:4:zh":"one hour","grammar:91443:ex2:words:4:note":"いちじかん","grammar:91443:ex2:words:4:pos":"numeral with counter","grammar:91443:ex2:words:5:zh":"is","grammar:91443:ex2:words:5:pos":"copula","grammar:91443:ex2:points:0":"昼休み can also be the topic, used to talk about how long the break is","grammar:91443:ex2:points:1":"一時間 = one hour; the 「間」 in a time word marks duration"},"91444":{"example:91444:exzh":"That child really looks like their father.","example:91444:exzh2":"These two colors are very similar, aren't they?","grammar:91444:ex:trans":"That child looks a lot like their father.","grammar:91444:ex:structure":"〔A〕は〔B〕に＋似ています","grammar:91444:ex:explain":"「似る」 means to look or be similar. Two things to note: the person or thing you resemble takes 「に」, and it's usually said as 「似ています」 to describe an ongoing state. Here 「よく」 doesn't mean \"often\" — it means \"very.\"","grammar:91444:ex:words:0:zh":"that","grammar:91444:ex:words:0:pos":"pre-noun adjectival","grammar:91444:ex:words:1:zh":"child","grammar:91444:ex:words:1:note":"こ","grammar:91444:ex:words:1:pos":"noun","grammar:91444:ex:words:2:zh":"(topic)","grammar:91444:ex:words:2:pos":"particle","grammar:91444:ex:words:3:zh":"dad","grammar:91444:ex:words:3:note":"おとうさん","grammar:91444:ex:words:3:pos":"noun","grammar:91444:ex:words:4:zh":"(the one being resembled)","grammar:91444:ex:words:4:pos":"particle","grammar:91444:ex:words:5:zh":"well","grammar:91444:ex:words:5:pos":"adverb","grammar:91444:ex:words:6:zh":"like","grammar:91444:ex:words:6:note":"にています; 似る＋ている","grammar:91444:ex:words:6:pos":"verb","grammar:91444:ex:points:0":"似る = to resemble; \"resembles who\" takes 「に」: AはBに似ている","grammar:91444:ex:points:1":"似る almost always appears as 「似ている」 to describe a state; 「似ます」 is rare","grammar:91444:ex:points:2":"よく似ている = looks very much alike","grammar:91444:ex2:trans":"These two colors look a lot alike, don't they?","grammar:91444:ex2:structure":"〔A と B〕は＋似ています","grammar:91444:ex2:words:0:zh":"this","grammar:91444:ex2:words:0:pos":"pre-noun adjectival","grammar:91444:ex2:words:1:zh":"two","grammar:91444:ex2:words:1:note":"ふたつ","grammar:91444:ex2:words:1:pos":"numeral with counter","grammar:91444:ex2:words:2:zh":"'s","grammar:91444:ex2:words:2:pos":"particle","grammar:91444:ex2:words:3:zh":"color","grammar:91444:ex2:words:3:note":"いろ","grammar:91444:ex2:words:3:pos":"noun","grammar:91444:ex2:words:4:zh":"(topic)","grammar:91444:ex2:words:4:pos":"particle","grammar:91444:ex2:words:5:zh":"Resemble","grammar:91444:ex2:words:5:note":"にています; 似る＋ている","grammar:91444:ex2:words:5:pos":"verb","grammar:91444:ex2:words:6:zh":"(seeking agreement) ..., right?","grammar:91444:ex2:words:6:pos":"particle","grammar:91444:ex2:points:0":"When two things resemble each other, you don't use 「に」 — just say 「〜は似ている」","grammar:91444:ex2:points:1":"〜ね: seeking the other person's agreement"},"91445":{"example:91445:exzh":"There are many old temples in Kyoto.","example:91445:exzh2":"On the weekend I went to see some temples.","grammar:91445:ex:trans":"Kyoto has lots of old temples.","grammar:91445:ex:structure":"〔place〕には＋〔thing〕がたくさんあります","grammar:91445:ex:explain":"「寺」 on its own is read 「てら」; in speech it usually takes 「お」 to become 「お寺（おてら）」, which sounds more polite. Keep it distinct from 「神社」: a 寺 is Buddhist, a 神社 is Shinto. In temple names it's read 「じ」, as in 「清水寺（きよみずでら）」 and 「金閣寺（きんかくじ）」.","grammar:91445:ex:words:0:zh":"Kyoto","grammar:91445:ex:words:0:note":"きょうと","grammar:91445:ex:words:0:pos":"noun","grammar:91445:ex:words:1:zh":"exist","grammar:91445:ex:words:1:pos":"particle","grammar:91445:ex:words:2:zh":"(topic)","grammar:91445:ex:words:2:pos":"particle","grammar:91445:ex:words:3:zh":"old","grammar:91445:ex:words:3:note":"ふるい","grammar:91445:ex:words:3:pos":"adjective","grammar:91445:ex:words:4:zh":"temple","grammar:91445:ex:words:4:note":"おてら; 「お」＋寺","grammar:91445:ex:words:4:pos":"noun","grammar:91445:ex:words:5:zh":"(subject)","grammar:91445:ex:words:5:pos":"particle","grammar:91445:ex:words:6:zh":"a lot","grammar:91445:ex:words:6:pos":"adverb","grammar:91445:ex:words:7:zh":"there is / are","grammar:91445:ex:words:7:note":"; the masu-form of ある","grammar:91445:ex:words:7:pos":"verb","grammar:91445:ex:points:0":"寺 = a Buddhist temple; in speech it often takes 「お」 as 「お寺」. A Shinto shrine is 「神社」","grammar:91445:ex:points:1":"〔place〕に〜がある: somewhere has something (use ある for inanimate things)","grammar:91445:ex2:trans":"I went to see some temples over the weekend.","grammar:91445:ex2:structure":"〔verb masu-form stem〕に＋行きました","grammar:91445:ex2:words:0:zh":"weekend","grammar:91445:ex2:words:0:note":"しゅうまつ","grammar:91445:ex2:words:0:pos":"noun","grammar:91445:ex2:words:1:zh":"in (time)","grammar:91445:ex2:words:1:pos":"particle","grammar:91445:ex2:words:2:zh":"temple","grammar:91445:ex2:words:2:note":"おてら","grammar:91445:ex2:words:2:pos":"noun","grammar:91445:ex2:words:3:zh":"(object)","grammar:91445:ex2:words:3:pos":"particle","grammar:91445:ex2:words:4:zh":"look","grammar:91445:ex2:words:4:note":"み; the masu-form stem of 見る","grammar:91445:ex2:words:4:pos":"verb","grammar:91445:ex2:words:5:zh":"go (in order to do something)","grammar:91445:ex2:words:5:pos":"particle","grammar:91445:ex2:words:6:zh":"went","grammar:91445:ex2:words:6:note":"いきました; past masu-form of 行く","grammar:91445:ex2:words:6:pos":"verb","grammar:91445:ex2:points:0":"お寺を見に行く = go to see a temple","grammar:91445:ex2:points:1":"Verb masu-form minus ます + に行く: expresses 'go in order to do something'; 見ます→見に行く"},"91446":{"example:91446:exzh":"I see, so that's how it is.","example:91446:exzh2":"Indeed, that's a good idea.","grammar:91446:ex:trans":"I see, so that's how it is.","grammar:91446:ex:structure":"なるほど、〜ですか","grammar:91446:ex:explain":"「なるほど」 means 'I get it, so that's it' — a very common response when listening to someone explain something. But saying 「なるほど」 over and over to a senior or your boss can sound a bit condescending; the safer choice is 「そうなんですね」.","grammar:91446:ex:words:0:zh":"I see","grammar:91446:ex:words:0:pos":"interjection","grammar:91446:ex:words:1:zh":"such","grammar:91446:ex:words:1:pos":"pre-noun adjectival","grammar:91446:ex:words:2:zh":"thing / matter","grammar:91446:ex:words:2:pos":"formal noun","grammar:91446:ex:words:3:zh":"is","grammar:91446:ex:words:3:pos":"copula","grammar:91446:ex:words:4:zh":"(lightbulb moment) ah","grammar:91446:ex:words:4:pos":"particle","grammar:91446:ex:points:0":"なるほど: what you say when you understand the other person's explanation and it clicks","grammar:91446:ex:points:1":"そういうことですか: the 「か」 here isn't a question; it carries the tone of 'oh, so that's how it is'","grammar:91446:ex2:trans":"Indeed, that's a good idea, isn't it?","grammar:91446:ex2:structure":"なるほど、〜ですね","grammar:91446:ex2:words:0:zh":"indeed","grammar:91446:ex2:words:0:pos":"interjection","grammar:91446:ex2:words:1:zh":"that","grammar:91446:ex2:words:1:pos":"pronoun","grammar:91446:ex2:words:2:zh":"(topic)","grammar:91446:ex2:words:2:pos":"particle","grammar:91446:ex2:words:3:zh":"good","grammar:91446:ex2:words:3:pos":"adjective","grammar:91446:ex2:words:4:zh":"idea","grammar:91446:ex2:words:4:note":"かんがえ","grammar:91446:ex2:words:4:pos":"noun","grammar:91446:ex2:words:5:zh":"is","grammar:91446:ex2:words:5:pos":"copula","grammar:91446:ex2:words:6:zh":"right?","grammar:91446:ex2:words:6:pos":"particle","grammar:91446:ex2:points:0":"なるほど can also show agreement or approval of the other person: 'indeed'","grammar:91446:ex2:points:1":"いい考え = a good idea; 考え is the noun form of 考える"},"91447":{"example:91447:exzh":"How old is your child?","example:91447:exzh2":"Is your child doing well?","grammar:91447:ex:trans":"How old is your child?","grammar:91447:ex:structure":"お子さんは＋何歳ですか","grammar:91447:ex:explain":"「お子さん」 adds 「お」 and 「さん」 around 「子」 (child) and is used to refer to someone else's child respectfully. You can't use it for your own child — say 「子ども」 or 「息子／娘」 instead.","grammar:91447:ex:words:0:zh":"(your) child","grammar:91447:ex:words:0:note":"おこさん","grammar:91447:ex:words:0:pos":"noun","grammar:91447:ex:words:1:zh":"(topic)","grammar:91447:ex:words:1:pos":"particle","grammar:91447:ex:words:2:zh":"how old","grammar:91447:ex:words:2:note":"なんさい","grammar:91447:ex:words:2:pos":"question word","grammar:91447:ex:words:3:zh":"is","grammar:91447:ex:words:3:pos":"copula","grammar:91447:ex:words:4:zh":"(question)","grammar:91447:ex:words:4:pos":"particle","grammar:91447:ex:points:0":"お子さん = the other person's child (polite); for your own child say 「子ども」 or 「うちの子」","grammar:91447:ex:points:1":"何歳ですか: asks someone's age; 「おいくつですか」 is even more polite","grammar:91447:ex2:trans":"How is your child doing?","grammar:91447:ex2:structure":"〔person〕は＋お元気ですか","grammar:91447:ex2:words:0:zh":"(your) child","grammar:91447:ex2:words:0:note":"おこさん","grammar:91447:ex2:words:0:pos":"noun","grammar:91447:ex2:words:1:zh":"(topic)","grammar:91447:ex2:words:1:pos":"particle","grammar:91447:ex2:words:2:zh":"healthy, energetic","grammar:91447:ex2:words:2:note":"おげんき; 「お」＋元気","grammar:91447:ex2:words:2:pos":"na-adjective","grammar:91447:ex2:words:3:zh":"is","grammar:91447:ex2:words:3:pos":"copula","grammar:91447:ex2:words:4:zh":"(question)","grammar:91447:ex2:words:4:pos":"particle","grammar:91447:ex2:points:0":"When greeting someone's family, people often say: お子さん／ご家族はお元気ですか","grammar:91447:ex2:points:1":"お元気: 「お」 is added before 元気 when speaking about the other person, to show politeness"},"91448":{"example:91448:exzh":"Where is the concert venue?","example:91448:exzh2":"A lot of people gathered at the venue.","grammar:91448:ex:trans":"Where is the concert venue?","grammar:91448:ex:structure":"〔event〕の会場は＋どこですか","grammar:91448:ex:explain":"「会場」 is the place where an event such as a concert, exam, or wedding is held, and it often attaches directly to the name of the event, as in 「試験会場」 (exam venue). This sentence uses 「〜はどこですか」 to ask for a location — the most common way to ask for directions.","grammar:91448:ex:words:0:zh":"concert","grammar:91448:ex:words:0:pos":"noun","grammar:91448:ex:words:1:zh":"'s","grammar:91448:ex:words:1:pos":"particle","grammar:91448:ex:words:2:zh":"hall, venue","grammar:91448:ex:words:2:note":"かいじょう","grammar:91448:ex:words:2:pos":"noun","grammar:91448:ex:words:3:zh":"(topic)","grammar:91448:ex:words:3:pos":"particle","grammar:91448:ex:words:4:zh":"where","grammar:91448:ex:words:4:pos":"question word","grammar:91448:ex:words:5:zh":"is","grammar:91448:ex:words:5:pos":"copula","grammar:91448:ex:words:6:zh":"(question)","grammar:91448:ex:words:6:pos":"particle","grammar:91448:ex:points:1":"〜はどこですか: the basic pattern for asking about a place","grammar:91448:ex2:trans":"A lot of people gathered at the venue.","grammar:91448:ex2:structure":"〔place〕には＋人が集まりました","grammar:91448:ex2:words:0:zh":"hall, venue","grammar:91448:ex2:words:0:note":"かいじょう","grammar:91448:ex2:words:0:pos":"noun","grammar:91448:ex2:words:1:zh":"at (the place where people gathered)","grammar:91448:ex2:words:1:pos":"particle","grammar:91448:ex2:words:2:zh":"(topic)","grammar:91448:ex2:words:2:pos":"particle","grammar:91448:ex2:words:3:zh":"person","grammar:91448:ex2:words:3:note":"ひと","grammar:91448:ex2:words:3:pos":"noun","grammar:91448:ex2:words:4:zh":"(subject)","grammar:91448:ex2:words:4:pos":"particle","grammar:91448:ex2:words:5:zh":"a lot","grammar:91448:ex2:words:5:pos":"adverb","grammar:91448:ex2:words:6:zh":"gathered","grammar:91448:ex2:words:6:note":"あつまりました; past masu-form of 集まる","grammar:91448:ex2:words:6:pos":"verb","grammar:91448:ex2:points:0":"会場に人が集まる: people gather at the venue","grammar:91448:ex2:points:1":"集まる is an intransitive verb (people gather on their own) and takes 「が」; 集める is a transitive verb (to collect something up) and takes 「を」"},"91449":{"example:91449:exzh":"Do you know this shop?","example:91449:exzh2":"As you know, prices will go up starting next month.","grammar:91449:ex:trans":"Do you know this shop?","grammar:91449:ex:structure":"〔noun〕を＋ご存じですか","grammar:91449:ex:explain":"「ご存じ」 is the respectful way to say 'know,' and it's used with 「です」 after it. 「〜をご存じですか」 is much more polite than 「〜を知っていますか」 and suits speaking to customers or seniors. When answering, you can't say 「ご存じです」 — say 「はい、知っています」.","grammar:91449:ex:words:0:zh":"this","grammar:91449:ex:words:0:pos":"pre-noun adjectival","grammar:91449:ex:words:1:zh":"store","grammar:91449:ex:words:1:note":"みせ","grammar:91449:ex:words:1:pos":"noun","grammar:91449:ex:words:2:zh":"(object)","grammar:91449:ex:words:2:pos":"particle","grammar:91449:ex:words:3:zh":"(you) know","grammar:91449:ex:words:3:note":"ごぞんじ; sonkeigo of 知っている","grammar:91449:ex:words:3:pos":"noun","grammar:91449:ex:words:4:zh":"is","grammar:91449:ex:words:4:pos":"copula","grammar:91449:ex:words:5:zh":"(question)","grammar:91449:ex:words:5:pos":"particle","grammar:91449:ex:points:0":"ご存じ = sonkeigo of 「知っている」, used only for the other person: ご存じですか = do you know?","grammar:91449:ex:points:1":"To say that you know, use the humble 「存じております」 or the neutral 「知っています」","grammar:91449:ex2:trans":"As you know, the price goes up starting next month.","grammar:91449:ex2:structure":"ご存じのとおり、〜","grammar:91449:ex2:words:0:zh":"(you) know","grammar:91449:ex2:words:0:note":"ごぞんじ","grammar:91449:ex2:words:0:pos":"noun","grammar:91449:ex2:words:1:zh":"'s","grammar:91449:ex2:words:1:pos":"particle","grammar:91449:ex2:words:2:zh":"as","grammar:91449:ex2:words:2:pos":"formal noun","grammar:91449:ex2:words:3:zh":"next month","grammar:91449:ex2:words:3:note":"らいげつ","grammar:91449:ex2:words:3:pos":"noun","grammar:91449:ex2:words:4:zh":"from〜","grammar:91449:ex2:words:4:pos":"particle","grammar:91449:ex2:words:5:zh":"price","grammar:91449:ex2:words:5:note":"ねだん","grammar:91449:ex2:words:5:pos":"noun","grammar:91449:ex2:words:6:zh":"(subject)","grammar:91449:ex2:words:6:pos":"particle","grammar:91449:ex2:words:7:zh":"to rise","grammar:91449:ex2:words:7:note":"あがります; masu-form of 上がる","grammar:91449:ex2:words:7:pos":"verb","grammar:91449:ex2:points:0":"ご存じのとおり = as you know; a common opener in business settings and announcements","grammar:91449:ex2:points:1":"値段が上がる = the price goes up; the opposite is 値段が下がる"},"91450":{"example:91450:exzh":"I'm getting hungry. Let's eat something.","example:91450:exzh2":"The early morning trains are empty.","grammar:91450:ex:trans":"I'm hungry, aren't you? Let's eat something.","grammar:91450:ex:structure":"おなかが＋すきました","grammar:91450:ex:explain":"「すく」 originally means 'to become empty, to decrease,' so 「おなかがすく」 means your stomach is empty — you're hungry. Japanese customarily uses the past form 「すきました」 to mean 'I'm hungry now.' In kanji it's written 「空く（すく）」, the same character as 「空く（あく）」 but with a different reading.","grammar:91450:ex:words:0:zh":"stomach","grammar:91450:ex:words:0:pos":"noun","grammar:91450:ex:words:1:zh":"(subject)","grammar:91450:ex:words:1:pos":"particle","grammar:91450:ex:words:2:zh":"(my stomach) is hungry","grammar:91450:ex:words:2:note":"; past masu-form of すく","grammar:91450:ex:words:2:pos":"verb","grammar:91450:ex:words:3:zh":"right?","grammar:91450:ex:words:3:pos":"particle","grammar:91450:ex:words:4:zh":"something","grammar:91450:ex:words:4:note":"なにか","grammar:91450:ex:words:4:pos":"pronoun","grammar:91450:ex:words:5:zh":"let's eat","grammar:91450:ex:words:5:note":"たべましょう; the volitional (let's) form of 食べる","grammar:91450:ex:words:5:pos":"verb","grammar:91450:ex:points:0":"おなかがすく = to be hungry; for 'I'm hungry now,' use the past form 「すきました」 or 「すいています」","grammar:91450:ex:points:1":"〜ましょう: invites the other person to do something together","grammar:91450:ex2:trans":"The early morning trains are pretty empty.","grammar:91450:ex2:structure":"〔noun〕は＋すいています","grammar:91450:ex2:words:0:zh":"morning","grammar:91450:ex2:words:0:note":"あさ","grammar:91450:ex2:words:0:pos":"noun","grammar:91450:ex2:words:1:zh":"early","grammar:91450:ex2:words:1:note":"はやい","grammar:91450:ex2:words:1:pos":"adjective","grammar:91450:ex2:words:2:zh":"train","grammar:91450:ex2:words:2:note":"でんしゃ","grammar:91450:ex2:words:2:pos":"noun","grammar:91450:ex2:words:3:zh":"(topic)","grammar:91450:ex2:words:3:pos":"particle","grammar:91450:ex2:words:4:zh":"(people) are few; empty","grammar:91450:ex2:words:4:note":"；すく＋ている","grammar:91450:ex2:words:4:pos":"verb","grammar:91450:ex2:points:0":"電車がすいている = the train is empty; the opposite is 「混んでいる」 (crowded)","grammar:91450:ex2:points:1":"すいている: the ている form describes a state"},"91451":{"example:91451:exzh":"These shoes don't fit.","example:91451:exzh2":"Please check whether the answers are correct.","grammar:91451:ex:trans":"These shoes are the wrong size.","grammar:91451:ex:structure":"〔thing〕は＋サイズが合いません","grammar:91451:ex:explain":"「合う」 means two things fit together exactly. This sentence says the size of the shoes doesn't match the foot. It's used very widely, as in 「サイズが合う」, 「服に合う」, and 「時間が合う」.","grammar:91451:ex:words:0:zh":"this","grammar:91451:ex:words:0:pos":"pre-noun adjectival","grammar:91451:ex:words:1:zh":"shoes","grammar:91451:ex:words:1:pos":"noun","grammar:91451:ex:words:2:zh":"(topic)","grammar:91451:ex:words:2:pos":"particle","grammar:91451:ex:words:3:zh":"size","grammar:91451:ex:words:3:pos":"noun","grammar:91451:ex:words:4:zh":"(subject)","grammar:91451:ex:words:4:pos":"particle","grammar:91451:ex:words:5:zh":"doesn't fit","grammar:91451:ex:words:5:note":"あいません; negative masu-form of 合う","grammar:91451:ex:words:5:pos":"verb","grammar:91451:ex:points:0":"合う = to fit, to match: サイズが合う (the size fits), 口に合う (it suits your taste), 色が合う (the colors go together)","grammar:91451:ex:points:1":"AはBが〜: the size of these shoes doesn't fit","grammar:91451:ex2:trans":"Please check whether your answers are correct.","grammar:91451:ex2:structure":"〜か＋確かめてください","grammar:91451:ex2:words:0:zh":"answer","grammar:91451:ex2:words:0:note":"こたえ","grammar:91451:ex2:words:0:pos":"noun","grammar:91451:ex2:words:1:zh":"(subject)","grammar:91451:ex2:words:1:pos":"particle","grammar:91451:ex2:words:2:zh":"correct; matching","grammar:91451:ex2:words:2:note":"あっている; 合う＋ている","grammar:91451:ex2:words:2:pos":"verb","grammar:91451:ex2:words:3:zh":"whether","grammar:91451:ex2:words:3:pos":"particle","grammar:91451:ex2:words:4:zh":"confirm","grammar:91451:ex2:words:4:note":"たしかめて; te-form of 確かめる","grammar:91451:ex2:words:4:pos":"verb","grammar:91451:ex2:words:5:zh":"please","grammar:91451:ex2:words:5:pos":"auxiliary verb","grammar:91451:ex2:points:0":"答えが合っている = the answer is right (it matches the correct answer)","grammar:91451:ex2:points:1":"〜か: placed mid-sentence it means 'whether or not〜'; 〜か確かめる = check whether〜"},"91452":{"example:91452:exzh":"I saw an art exhibition at the museum.","example:91452:exzh2":"The exhibition runs until next Sunday.","grammar:91452:ex:trans":"I saw an art exhibition at the museum.","grammar:91452:ex:structure":"〔place〕で＋〔noun〕の展覧会を見ました","grammar:91452:ex:explain":"「展覧会」 is an event where works are displayed for people to see, usually called 「〇〇の展覧会」. To go see an exhibition you can say 「展覧会を見る」 or 「展覧会に行く」. The place where the action happens, 「美術館」, takes 「で」.","grammar:91452:ex:words:0:zh":"Art museum","grammar:91452:ex:words:0:note":"びじゅつかん","grammar:91452:ex:words:0:pos":"noun","grammar:91452:ex:words:1:zh":"exist","grammar:91452:ex:words:1:pos":"particle","grammar:91452:ex:words:2:zh":"picture","grammar:91452:ex:words:2:note":"え","grammar:91452:ex:words:2:pos":"noun","grammar:91452:ex:words:3:zh":"'s","grammar:91452:ex:words:3:pos":"particle","grammar:91452:ex:words:4:zh":"exhibition","grammar:91452:ex:words:4:note":"てんらんかい","grammar:91452:ex:words:4:pos":"noun","grammar:91452:ex:words:5:zh":"(object)","grammar:91452:ex:words:5:pos":"particle","grammar:91452:ex:words:6:zh":"watched","grammar:91452:ex:words:6:note":"みました; past masu-form of 見る","grammar:91452:ex:words:6:pos":"verb","grammar:91452:ex:points:0":"展覧会 = exhibition: 絵の展覧会 (art exhibition), 写真の展覧会 (photo exhibition)","grammar:91452:ex:points:1":"〔place〕で: 「で」 marks where the action takes place","grammar:91452:ex2:trans":"The exhibition runs until next Sunday.","grammar:91452:ex2:structure":"〔noun〕は＋〔time〕までです","grammar:91452:ex2:words:0:zh":"exhibition","grammar:91452:ex2:words:0:note":"てんらんかい","grammar:91452:ex2:words:0:pos":"noun","grammar:91452:ex2:words:1:zh":"(topic)","grammar:91452:ex2:words:1:pos":"particle","grammar:91452:ex2:words:2:zh":"next week","grammar:91452:ex2:words:2:note":"らいしゅう","grammar:91452:ex2:words:2:pos":"noun","grammar:91452:ex2:words:3:zh":"'s","grammar:91452:ex2:words:3:pos":"particle","grammar:91452:ex2:words:4:zh":"Sunday","grammar:91452:ex2:words:4:note":"にちようび","grammar:91452:ex2:words:4:pos":"noun","grammar:91452:ex2:words:5:zh":"until〜","grammar:91452:ex2:words:5:pos":"particle","grammar:91452:ex2:words:6:zh":"is","grammar:91452:ex2:words:6:pos":"copula","grammar:91452:ex2:points:0":"展覧会は〜までです: states how long the exhibition runs","grammar:91452:ex2:points:1":"〜まで: marks the ending point in time"},"91453":{"example:91453:exzh":"It's been a long time. How have you been?","example:91453:exzh2":"I went to see a movie for the first time in a long while.","grammar:91453:ex:trans":"Long time no see. How have you been?","grammar:91453:ex:structure":"久しぶりですね。〜","grammar:91453:ex:explain":"「久しぶり」 means 'after a long time,' so saying 「久しぶりですね」 when you meet someone means 'long time no see.' The follow-up 「お元気でしたか」 uses the past form because it asks about 'the period when we didn't meet.'","grammar:91453:ex:words:0:zh":"it has been a long time","grammar:91453:ex:words:0:note":"ひさしぶり","grammar:91453:ex:words:0:pos":"na-adjective","grammar:91453:ex:words:1:zh":"(polite)","grammar:91453:ex:words:1:pos":"copula","grammar:91453:ex:words:2:zh":"right?","grammar:91453:ex:words:2:pos":"particle","grammar:91453:ex:words:3:zh":"well; in good spirits","grammar:91453:ex:words:3:note":"おげんき","grammar:91453:ex:words:3:pos":"na-adjective","grammar:91453:ex:words:4:zh":"was (past)","grammar:91453:ex:words:4:note":"; past form of です","grammar:91453:ex:words:4:pos":"copula","grammar:91453:ex:words:5:zh":"(question)","grammar:91453:ex:words:5:pos":"particle","grammar:91453:ex:points:0":"久しぶりです = long time no see; with friends you can just say 「久しぶり！」","grammar:91453:ex:points:1":"お元気でしたか: asks 'have you been well during this time,' so the past form is used","grammar:91453:ex2:trans":"I finally went to see a movie for the first time in ages.","grammar:91453:ex2:structure":"久しぶりに＋〔action〕","grammar:91453:ex2:words:0:zh":"for the first time in a long while","grammar:91453:ex2:words:0:note":"ひさしぶり","grammar:91453:ex2:words:0:pos":"na-adjective","grammar:91453:ex2:words:1:zh":"(made adverbial)","grammar:91453:ex2:words:1:pos":"particle","grammar:91453:ex2:words:2:zh":"movie","grammar:91453:ex2:words:2:note":"えいが","grammar:91453:ex2:words:2:pos":"noun","grammar:91453:ex2:words:3:zh":"(object)","grammar:91453:ex2:words:3:pos":"particle","grammar:91453:ex2:words:4:zh":"look","grammar:91453:ex2:words:4:note":"み; the masu-form stem of 見る","grammar:91453:ex2:words:4:pos":"verb","grammar:91453:ex2:words:5:zh":"go (in order to do something)","grammar:91453:ex2:words:5:pos":"particle","grammar:91453:ex2:words:6:zh":"went","grammar:91453:ex2:words:6:note":"いきました; past masu-form of 行く","grammar:91453:ex2:words:6:pos":"verb","grammar:91453:ex2:points:0":"久しぶりに〜: do something again after a long time","grammar:91453:ex2:points:1":"見に行く: masu-form stem + に行く, meaning 'go in order to do something'"},"91454":{"example:91454:exzh":"I got up in the morning and opened the curtains.","example:91454:exzh2":"I want to buy blue curtains.","grammar:91454:ex:trans":"I got up in the morning and opened the curtains.","grammar:91454:ex:structure":"〜て、カーテンを開けました","grammar:91454:ex:explain":"「カーテン」 is a curtain: you open it with 「開ける」 and close it with 「閉める」, the same verbs as opening and closing a door. 「起きて」 is the te-form, used to link two actions that happen one after another.","grammar:91454:ex:words:0:zh":"morning","grammar:91454:ex:words:0:note":"あさ","grammar:91454:ex:words:0:pos":"noun","grammar:91454:ex:words:1:zh":"to get up","grammar:91454:ex:words:1:note":"おきて; te-form of 起きる","grammar:91454:ex:words:1:pos":"verb","grammar:91454:ex:words:2:zh":"curtain","grammar:91454:ex:words:2:pos":"noun","grammar:91454:ex:words:3:zh":"(object)","grammar:91454:ex:words:3:pos":"particle","grammar:91454:ex:words:4:zh":"opened","grammar:91454:ex:words:4:note":"あけました; past masu-form of 開ける","grammar:91454:ex:words:4:pos":"verb","grammar:91454:ex:points:0":"カーテンを開ける／閉める = open／close the curtains","grammar:91454:ex:points:1":"〜て: links actions in order; 起きて、開けました = got up and then opened","grammar:91454:ex2:trans":"I want to buy blue curtains.","grammar:91454:ex2:structure":"〔thing〕を＋買いたいです","grammar:91454:ex2:words:0:zh":"blue","grammar:91454:ex2:words:0:note":"あおい","grammar:91454:ex2:words:0:pos":"adjective","grammar:91454:ex2:words:1:zh":"curtain","grammar:91454:ex2:words:1:pos":"noun","grammar:91454:ex2:words:2:zh":"(object)","grammar:91454:ex2:words:2:pos":"particle","grammar:91454:ex2:words:3:zh":"want to buy","grammar:91454:ex2:words:3:note":"かいたい; 買う＋たい","grammar:91454:ex2:words:3:pos":"verb","grammar:91454:ex2:words:4:zh":"(polite)","grammar:91454:ex2:words:4:pos":"copula","grammar:91454:ex2:points:0":"i-adjectives can go directly before a noun: 青いカーテン","grammar:91454:ex2:points:1":"〜たい: want to do something; masu-form stem + たい: 買います→買いたい"},"91455":{"example:91455:exzh":"I overslept and was late for class.","example:91455:exzh2":"The train is running thirty minutes late because of the snow.","grammar:91455:ex:trans":"I overslept and was late for class.","grammar:91455:ex:structure":"〔event〕に＋遅れました","grammar:91455:ex:explain":"「遅れる」 means to miss the scheduled time, and whatever you're late for takes 「に」. It differs from 「遅い」 (slow, late): 「遅い」 is an adjective describing a state, while 「遅れる」 is a verb meaning to fall behind the time you should have arrived.","grammar:91455:ex:words:0:zh":"oversleeping","grammar:91455:ex:words:0:note":"ねぼうして; te-form of 寝坊する","grammar:91455:ex:words:0:pos":"verb","grammar:91455:ex:words:1:zh":"class","grammar:91455:ex:words:1:note":"じゅぎょう","grammar:91455:ex:words:1:pos":"noun","grammar:91455:ex:words:2:zh":"(what you were late for)","grammar:91455:ex:words:2:pos":"particle","grammar:91455:ex:words:3:zh":"was late","grammar:91455:ex:words:3:note":"おくれました; past masu-form of 遅れる","grammar:91455:ex:words:3:pos":"verb","grammar:91455:ex:points:0":"遅れる = to be late, to fall behind schedule; what you're late for takes 「に」: 授業に遅れる, 会議に遅れる","grammar:91455:ex:points:1":"〜て: here it gives the reason, 'because I overslept'","grammar:91455:ex2:trans":"Because of the snow, the train is thirty minutes late.","grammar:91455:ex2:structure":"〔cause〕で＋〔transport〕が〔time〕遅れています","grammar:91455:ex2:words:0:zh":"snow","grammar:91455:ex2:words:0:note":"ゆき","grammar:91455:ex2:words:0:pos":"noun","grammar:91455:ex2:words:1:zh":"because","grammar:91455:ex2:words:1:pos":"particle","grammar:91455:ex2:words:2:zh":"train","grammar:91455:ex2:words:2:note":"でんしゃ","grammar:91455:ex2:words:2:pos":"noun","grammar:91455:ex2:words:3:zh":"(subject)","grammar:91455:ex2:words:3:pos":"particle","grammar:91455:ex2:words:4:zh":"thirty minutes","grammar:91455:ex2:words:4:note":"さんじゅっぷん","grammar:91455:ex2:words:4:pos":"numeral with counter","grammar:91455:ex2:words:5:zh":"delay","grammar:91455:ex2:words:5:note":"おくれています; 遅れる＋ている","grammar:91455:ex2:words:5:pos":"verb","grammar:91455:ex2:points:0":"電車が遅れる = the train is delayed; 遅れている shows the delay is still going on now","grammar:91455:ex2:points:1":"雪で: 「で」 marks the cause"},"91456":{"example:91456:exzh":"Please, go ahead and eat.","example:91456:exzh2":"What would you like to drink?","grammar:91456:ex:trans":"Please, help yourself.","grammar:91456:ex:structure":"どうぞ、召し上がってください","grammar:91456:ex:explain":"「召し上がる」 is the sonkeigo of 'eat, drink'; when inviting a guest to eat you say 「どうぞ召し上がってください」, which is like 'please help yourself.' For your own eating, use the humble 「いただく」 — you can't say 召し上がる for yourself.","grammar:91456:ex:words:0:zh":"please","grammar:91456:ex:words:0:pos":"adverb","grammar:91456:ex:words:1:zh":"eat, drink (respectful)","grammar:91456:ex:words:1:note":"めしあがって; te-form of 召し上がる","grammar:91456:ex:words:1:pos":"verb","grammar:91456:ex:words:2:zh":"please","grammar:91456:ex:words:2:pos":"auxiliary verb","grammar:91456:ex:points:0":"召し上がる = sonkeigo of 食べる・飲む, used for guests and superiors","grammar:91456:ex:points:1":"どうぞ〜てください: a polite way to ask someone to do something","grammar:91456:ex2:trans":"What would you like to drink?","grammar:91456:ex2:structure":"お飲み物は＋何を召し上がりますか","grammar:91456:ex2:words:0:zh":"drink","grammar:91456:ex2:words:0:note":"おのみもの","grammar:91456:ex2:words:0:pos":"noun","grammar:91456:ex2:words:1:zh":"(topic)","grammar:91456:ex2:words:1:pos":"particle","grammar:91456:ex2:words:2:zh":"what","grammar:91456:ex2:words:2:note":"なに","grammar:91456:ex2:words:2:pos":"question word","grammar:91456:ex2:words:3:zh":"(object)","grammar:91456:ex2:words:3:pos":"particle","grammar:91456:ex2:words:4:zh":"drink (respectful)","grammar:91456:ex2:words:4:note":"めしあがります; masu-form of 召し上がる","grammar:91456:ex2:words:4:pos":"verb","grammar:91456:ex2:words:5:zh":"(question)","grammar:91456:ex2:words:5:pos":"particle","grammar:91456:ex2:points:0":"召し上がる can also be used for 'drink'","grammar:91456:ex2:points:1":"お飲み物: 「お」 before 飲み物, the polite form used in restaurants and customer service"},"91457":{"example:91457:exzh":"I ate too many snacks and gained weight.","example:91457:exzh2":"My father has put on a little weight recently.","grammar:91457:ex:trans":"I ate too many sweets and got fat.","grammar:91457:ex:structure":"〜すぎて、太ってしまいました","grammar:91457:ex:explain":"「太る」 is the change of gaining weight; for the state of already being fat, say 「太っています」. Here 「食べすぎて」 gives the reason, and 「太ってしまいました」 uses 「てしまう」 to add a note of regret.","grammar:91457:ex:words:0:zh":"sweets; snacks","grammar:91457:ex:words:0:note":"おかし","grammar:91457:ex:words:0:pos":"noun","grammar:91457:ex:words:1:zh":"(object)","grammar:91457:ex:words:1:pos":"particle","grammar:91457:ex:words:2:zh":"eating too much","grammar:91457:ex:words:2:note":"たべすぎて; te-form of 食べすぎる","grammar:91457:ex:words:2:pos":"verb","grammar:91457:ex:words:3:zh":"to gain weight","grammar:91457:ex:words:3:note":"ふとって; te-form of 太る","grammar:91457:ex:words:3:pos":"verb","grammar:91457:ex:words:4:zh":"(unintentionally) ended up〜","grammar:91457:ex:words:4:note":"; past masu-form of てしまう","grammar:91457:ex:words:4:pos":"auxiliary verb","grammar:91457:ex:points:0":"太る = to gain weight (an action); to say someone is fat now, use 「太っている」","grammar:91457:ex:points:1":"〜すぎる: to do too much; 食べる→食べすぎる","grammar:91457:ex:points:2":"〜てしまう: expresses regret, 'ended up〜 without meaning to'","grammar:91457:ex2:trans":"My father has put on a little weight recently.","grammar:91457:ex2:structure":"〔person〕は＋最近＋太りました","grammar:91457:ex2:words:0:zh":"(my) father","grammar:91457:ex2:words:0:note":"ちち","grammar:91457:ex2:words:0:pos":"noun","grammar:91457:ex2:words:1:zh":"(topic)","grammar:91457:ex2:words:1:pos":"particle","grammar:91457:ex2:words:2:zh":"lately","grammar:91457:ex2:words:2:note":"さいきん","grammar:91457:ex2:words:2:pos":"noun","grammar:91457:ex2:words:3:zh":"a little","grammar:91457:ex2:words:3:note":"すこし","grammar:91457:ex2:words:3:pos":"adverb","grammar:91457:ex2:words:4:zh":"put on weight","grammar:91457:ex2:words:4:note":"ふとりました; past masu-form of 太る","grammar:91457:ex2:words:4:pos":"verb","grammar:91457:ex2:points:0":"太りました: the past form shows the change — 'has already put on some weight'","grammar:91457:ex2:points:1":"父: used with outsiders for your own father; for someone else's father say お父さん"},"91458":{"example:91458:exzh":"The broken computer has been fixed.","example:91458:exzh2":"I hear this watch can't be fixed anymore.","grammar:91458:ex:trans":"The broken computer has been fixed.","grammar:91458:ex:structure":"〔noun〕が＋直りました","grammar:91458:ex:explain":"「直る」 means a thing returns to normal by itself, so the subject is 「パソコン」 and it takes 「が」. To say 'I fixed the computer,' use the transitive 「パソコンを直す」. Intransitive and transitive verbs come in pairs — learning them together is the most effective.","grammar:91458:ex:words:0:zh":"broken","grammar:91458:ex:words:0:note":"こわれていた; 壊れる＋ていた","grammar:91458:ex:words:0:pos":"verb","grammar:91458:ex:words:1:zh":"computer","grammar:91458:ex:words:1:pos":"noun","grammar:91458:ex:words:2:zh":"(subject)","grammar:91458:ex:words:2:pos":"particle","grammar:91458:ex:words:3:zh":"got fixed","grammar:91458:ex:words:3:note":"なおりました; past masu-form of 直る","grammar:91458:ex:words:3:pos":"verb","grammar:91458:ex:points:0":"直る = (a thing) gets fixed, an intransitive verb taking 「が」; the transitive 「直す」 = (a person) repairs","grammar:91458:ex:points:1":"壊れていたパソコン: a verb modifying a noun, 'the computer that had been broken'","grammar:91458:ex2:trans":"I hear this watch can't be repaired anymore.","grammar:91458:ex2:structure":"〜ない＋そうです","grammar:91458:ex2:words:0:zh":"this","grammar:91458:ex2:words:0:pos":"pre-noun adjectival","grammar:91458:ex2:words:1:zh":"watch; clock","grammar:91458:ex2:words:1:note":"とけい","grammar:91458:ex2:words:1:pos":"noun","grammar:91458:ex2:words:2:zh":"(topic)","grammar:91458:ex2:words:2:pos":"particle","grammar:91458:ex2:words:3:zh":"already","grammar:91458:ex2:words:3:pos":"adverb","grammar:91458:ex2:words:4:zh":"can't fix","grammar:91458:ex2:words:4:note":"なおらない; negative form of 直る","grammar:91458:ex2:words:4:pos":"verb","grammar:91458:ex2:words:5:zh":"I hear (that)","grammar:91458:ex2:words:5:pos":"auxiliary verb","grammar:91458:ex2:points:0":"もう直らない: it won't get fixed anymore; the negative of 直る means 'can't be repaired'","grammar:91458:ex2:points:1":"plain form + そうです: means 'I hear,' reporting what someone told you"},"91459":{"example:91459:exzh":"I'm not good at math.","example:91459:exzh2":"There's a math exam tomorrow.","grammar:91459:ex:trans":"I'm not good at math.","grammar:91459:ex:structure":"〔person〕は〔school subject〕が＋苦手です","grammar:91459:ex:explain":"「数学」 means math. To say you're not good at a subject, use 「〜が苦手です」, with the thing you're bad at marked by 「が」. Besides poor ability, 「苦手」 also carries a sense of 'don't like it, can't handle it,' and it's softer than 「下手」 (clumsy).","grammar:91459:ex:words:0:zh":"I","grammar:91459:ex:words:0:pos":"pronoun","grammar:91459:ex:words:1:zh":"(topic)","grammar:91459:ex:words:1:pos":"particle","grammar:91459:ex:words:2:zh":"math","grammar:91459:ex:words:2:note":"すうがく","grammar:91459:ex:words:2:pos":"noun","grammar:91459:ex:words:3:zh":"(object)","grammar:91459:ex:words:3:pos":"particle","grammar:91459:ex:words:4:zh":"not good at","grammar:91459:ex:words:4:note":"にがて","grammar:91459:ex:words:4:pos":"na-adjective","grammar:91459:ex:words:5:zh":"is","grammar:91459:ex:words:5:pos":"copula","grammar:91459:ex:points:1":"〜が苦手: not good at or not fond of something; the opposite is 〜が得意","grammar:91459:ex2:trans":"There is a math exam tomorrow.","grammar:91459:ex2:structure":"〔time〕は＋〔noun〕があります","grammar:91459:ex2:words:0:zh":"tomorrow","grammar:91459:ex2:words:0:note":"あした","grammar:91459:ex2:words:0:pos":"noun","grammar:91459:ex2:words:1:zh":"(topic)","grammar:91459:ex2:words:1:pos":"particle","grammar:91459:ex2:words:2:zh":"math","grammar:91459:ex2:words:2:note":"すうがく","grammar:91459:ex2:words:2:pos":"noun","grammar:91459:ex2:words:3:zh":"'s","grammar:91459:ex2:words:3:pos":"particle","grammar:91459:ex2:words:4:zh":"test","grammar:91459:ex2:words:4:pos":"noun","grammar:91459:ex2:words:5:zh":"(subject)","grammar:91459:ex2:words:5:pos":"particle","grammar:91459:ex2:words:6:zh":"there is / are","grammar:91459:ex2:words:6:note":"; the masu-form of ある","grammar:91459:ex2:words:6:pos":"verb","grammar:91459:ex2:points:0":"数学のテスト = a math test","grammar:91459:ex2:points:1":"〜がある: ある is also used for events and exams being held"},"91460":{"example:91460:exzh":"The bread has baked up nicely and looks delicious.","example:91460:exzh2":"The house burned down in the fire.","grammar:91460:ex:trans":"The bread baked up looking delicious.","grammar:91460:ex:structure":"〔noun〕が＋〜そうに焼けました","grammar:91460:ex:explain":"「焼ける」 means a thing finishes baking on its own, so you say 「パンが焼けました」; if you do the baking yourself, say 「パンを焼きました」. 「おいしそうに」 describes the finished look — it looks delicious.","grammar:91460:ex:words:0:zh":"bread","grammar:91460:ex:words:0:pos":"noun","grammar:91460:ex:words:1:zh":"(subject)","grammar:91460:ex:words:1:pos":"particle","grammar:91460:ex:words:2:zh":"in a way that looks delicious","grammar:91460:ex:words:2:note":"; おいしい + the に-form of そうだ","grammar:91460:ex:words:2:pos":"na-adjective","grammar:91460:ex:words:3:zh":"is done toasting","grammar:91460:ex:words:3:note":"やけました; past masu-form of 焼ける","grammar:91460:ex:words:3:pos":"verb","grammar:91460:ex:points:0":"焼ける = (a thing) finishes baking, an intransitive verb taking 「が」; the transitive is 「焼く」 (to bake)","grammar:91460:ex:points:1":"〜そうに: 'in a way that looks〜'; おいしい→おいしそうに","grammar:91460:ex2:trans":"The house burned down in the fire.","grammar:91460:ex2:structure":"〔cause〕で〔noun〕が＋焼けてしまいました","grammar:91460:ex2:words:0:zh":"fire","grammar:91460:ex2:words:0:note":"かじ","grammar:91460:ex2:words:0:pos":"noun","grammar:91460:ex2:words:1:zh":"because","grammar:91460:ex2:words:1:pos":"particle","grammar:91460:ex2:words:2:zh":"house","grammar:91460:ex2:words:2:note":"いえ","grammar:91460:ex2:words:2:pos":"noun","grammar:91460:ex2:words:3:zh":"(subject)","grammar:91460:ex2:words:3:pos":"particle","grammar:91460:ex2:words:4:zh":"to burn down completely","grammar:91460:ex2:words:4:note":"やけて; te-form of 焼ける","grammar:91460:ex2:words:4:pos":"verb","grammar:91460:ex2:words:5:zh":"(unfortunately)〜","grammar:91460:ex2:words:5:note":"; past masu-form of てしまう","grammar:91460:ex2:words:5:pos":"auxiliary verb","grammar:91460:ex2:points:0":"焼ける also means 'to be destroyed by fire': 家が焼ける = the house burns down","grammar:91460:ex2:points:1":"〜てしまう: expresses regret over something that can't be undone"},"91461":{"example:91461:exzh":"It gets much colder once night falls, doesn't it?","example:91461:exzh2":"The beer is chilling in the refrigerator.","grammar:91461:ex:trans":"Once night falls, it gets really cold, doesn't it?","grammar:91461:ex:structure":"〜になると、〜冷えます","grammar:91461:ex:explain":"「冷える」 means the temperature drops naturally, and it's often used for air temperature or the body. It differs from 「寒い」: 「寒い」 describes the feeling that it's cold right now, while 「冷える」 is the change of getting cold. 「〜になると」 means that once that time comes, this happens.","grammar:91461:ex:words:0:zh":"evening","grammar:91461:ex:words:0:note":"よる","grammar:91461:ex:words:0:pos":"noun","grammar:91461:ex:words:1:zh":"(the resulting color)","grammar:91461:ex:words:1:pos":"particle","grammar:91461:ex:words:2:zh":"became, reached","grammar:91461:ex:words:2:pos":"verb","grammar:91461:ex:words:3:zh":"as soon as…, then…","grammar:91461:ex:words:3:pos":"particle","grammar:91461:ex:words:4:zh":"considerably; quite","grammar:91461:ex:words:4:pos":"adverb","grammar:91461:ex:words:5:zh":"to get cold","grammar:91461:ex:words:5:note":"ひえます; masu-form of 冷える","grammar:91461:ex:words:5:pos":"verb","grammar:91461:ex:words:6:zh":"right?","grammar:91461:ex:words:6:pos":"particle","grammar:91461:ex:points:0":"冷える = the temperature drops, to get cold: 朝晩は冷える (mornings and evenings are chilly), 体が冷える (your body gets cold)","grammar:91461:ex:points:1":"〜と: 'whenever〜, then〜,' for things that happen every time","grammar:91461:ex:points:2":"夜になる: night comes","grammar:91461:ex2:trans":"The beer is chilling in the fridge.","grammar:91461:ex2:structure":"〔place〕で＋〔noun〕が冷えています","grammar:91461:ex2:words:0:zh":"refrigerator","grammar:91461:ex2:words:0:note":"れいぞうこ","grammar:91461:ex2:words:0:pos":"noun","grammar:91461:ex2:words:1:zh":"exist","grammar:91461:ex2:words:1:pos":"particle","grammar:91461:ex2:words:2:zh":"beer","grammar:91461:ex2:words:2:pos":"noun","grammar:91461:ex2:words:3:zh":"(subject)","grammar:91461:ex2:words:3:pos":"particle","grammar:91461:ex2:words:4:zh":"is chilled; already cold","grammar:91461:ex2:words:4:note":"ひえています; 冷える＋ている","grammar:91461:ex2:words:4:pos":"verb","grammar:91461:ex2:points:0":"冷えている: the state of already being chilled; cold beer is 「冷えたビール」","grammar:91461:ex2:points:1":"intransitive 冷える (to get cold)／transitive 冷やす (to chill something)"},"91462":{"example:91462:exzh":"The light in the room is on.","example:91462:exzh2":"This TV just won't turn on.","grammar:91462:ex:trans":"The light in the room is on.","grammar:91462:ex:structure":"〔noun〕が＋ついています","grammar:91462:ex:explain":"「つく」 means a light or appliance comes on by itself, and the subject here is 「電気」. If a person turns on the light, say 「電気をつける」. 「ついています」 shows the light is on right now — maybe someone forgot to switch it off.","grammar:91462:ex:words:0:zh":"room","grammar:91462:ex:words:0:note":"へや","grammar:91462:ex:words:0:pos":"noun","grammar:91462:ex:words:1:zh":"'s","grammar:91462:ex:words:1:pos":"particle","grammar:91462:ex:words:2:zh":"light (electric light)","grammar:91462:ex:words:2:note":"でんき","grammar:91462:ex:words:2:pos":"noun","grammar:91462:ex:words:3:zh":"(subject)","grammar:91462:ex:words:3:pos":"particle","grammar:91462:ex:words:4:zh":"is on","grammar:91462:ex:words:4:note":"；つく＋ている","grammar:91462:ex:words:4:pos":"verb","grammar:91462:ex:points:0":"つく = (a light or appliance) comes on, an intransitive verb taking 「が」; the transitive is 「つける」 (to turn on)","grammar:91462:ex:points:1":"ついている: shows the light is on right now","grammar:91462:ex2:trans":"This TV just won't turn on.","grammar:91462:ex2:structure":"なかなか＋〜ません","grammar:91462:ex2:words:0:zh":"this","grammar:91462:ex2:words:0:pos":"pre-noun adjectival","grammar:91462:ex2:words:1:zh":"TV","grammar:91462:ex2:words:1:pos":"noun","grammar:91462:ex2:words:2:zh":"(topic)","grammar:91462:ex2:words:2:pos":"particle","grammar:91462:ex2:words:3:zh":"(just) won't","grammar:91462:ex2:words:3:pos":"adverb","grammar:91462:ex2:words:4:zh":"won't turn on","grammar:91462:ex2:words:4:note":"; negative masu-form of つく","grammar:91462:ex2:words:4:pos":"verb","grammar:91462:ex2:points:0":"テレビがつかない: the TV won't turn on","grammar:91462:ex2:points:1":"なかなか + negative: 'no matter how you try, it won't〜,' with a sense that things aren't going smoothly"},"91463":{"example:91463:exzh":"Is it okay if I open the window?","example:91463:exzh2":"Don't worry about me — you all go on ahead.","grammar:91463:ex:trans":"May I open the window?","grammar:91463:ex:structure":"〜てもかまいませんか","grammar:91463:ex:explain":"「かまう」 means 'to mind,' and it's usually used in the negative 「かまいません」 (I don't mind). 「〜てもかまいませんか」 means 'would you mind if I do this?' — a very polite way to ask permission. You can answer 「ええ、どうぞ」.","grammar:91463:ex:words:0:zh":"window","grammar:91463:ex:words:0:note":"まど","grammar:91463:ex:words:0:pos":"noun","grammar:91463:ex:words:1:zh":"(object)","grammar:91463:ex:words:1:pos":"particle","grammar:91463:ex:words:2:zh":"even if (I) open","grammar:91463:ex:words:2:note":"あけても; te-form of 開ける + も","grammar:91463:ex:words:2:pos":"verb","grammar:91463:ex:words:3:zh":"it's okay","grammar:91463:ex:words:3:note":"; negative masu-form of かまう","grammar:91463:ex:words:3:pos":"verb","grammar:91463:ex:words:4:zh":"(question)","grammar:91463:ex:words:4:pos":"particle","grammar:91463:ex:points:0":"かまう is mostly used in the negative: 〜てもかまいません = it's fine to〜; 〜てもかまいませんか = may I〜?","grammar:91463:ex:points:1":"a little more polite than 「〜てもいいですか」","grammar:91463:ex2:trans":"Don't worry about me — please go on ahead.","grammar:91463:ex2:structure":"〜のことはかまわないで、〜てください","grammar:91463:ex2:words:0:zh":"I","grammar:91463:ex2:words:0:pos":"pronoun","grammar:91463:ex2:words:1:zh":"'s","grammar:91463:ex2:words:1:pos":"particle","grammar:91463:ex2:words:2:zh":"thing / matter","grammar:91463:ex2:words:2:pos":"formal noun","grammar:91463:ex2:words:3:zh":"(topic)","grammar:91463:ex2:words:3:pos":"particle","grammar:91463:ex2:words:4:zh":"don't pay any attention to","grammar:91463:ex2:words:4:note":"; negative te-form of かまう","grammar:91463:ex2:words:4:pos":"verb","grammar:91463:ex2:words:5:zh":"first","grammar:91463:ex2:words:5:note":"さきに","grammar:91463:ex2:words:5:pos":"adverb","grammar:91463:ex2:words:6:zh":"go","grammar:91463:ex2:words:6:note":"いって; te-form of 行く","grammar:91463:ex2:words:6:pos":"verb","grammar:91463:ex2:words:7:zh":"please","grammar:91463:ex2:words:7:pos":"auxiliary verb","grammar:91463:ex2:points:0":"かまう also means 'to pay attention to, to look after': わたしのことはかまわないで = don't worry about me","grammar:91463:ex2:points:1":"〜ないで: 'without doing〜,' linking to the next action"},"91464":{"example:91464:exzh":"The cup I dropped broke.","example:91464:exzh2":"The window glass broke in the earthquake.","grammar:91464:ex:trans":"The cup I dropped broke.","grammar:91464:ex:structure":"〔noun〕が＋割れました","grammar:91464:ex:explain":"「割れる」 is used for hard things like cups, plates, and glass breaking. It's an intransitive verb, so you say 「コップが割れました」. If you want to stress that you broke it yourself, say 「コップを割ってしまいました」.","grammar:91464:ex:words:0:zh":"dropped","grammar:91464:ex:words:0:note":"おとした; ta-form of 落とす","grammar:91464:ex:words:0:pos":"verb","grammar:91464:ex:words:1:zh":"cup","grammar:91464:ex:words:1:pos":"noun","grammar:91464:ex:words:2:zh":"(subject)","grammar:91464:ex:words:2:pos":"particle","grammar:91464:ex:words:3:zh":"broke","grammar:91464:ex:words:3:note":"われました; past masu-form of 割れる","grammar:91464:ex:words:3:pos":"verb","grammar:91464:ex:points:0":"割れる = (glass, ceramics, etc.) to break or crack, an intransitive verb taking 「が」; the transitive is 「割る」 (to break)","grammar:91464:ex:points:1":"落としたコップ: the ta-form modifies a noun, 'the cup I dropped'","grammar:91464:ex2:trans":"The window glass shattered in the earthquake.","grammar:91464:ex2:structure":"〔cause〕で＋〔noun〕が割れました","grammar:91464:ex2:words:0:zh":"earthquake","grammar:91464:ex2:words:0:note":"じしん","grammar:91464:ex2:words:0:pos":"noun","grammar:91464:ex2:words:1:zh":"because","grammar:91464:ex2:words:1:pos":"particle","grammar:91464:ex2:words:2:zh":"window glass","grammar:91464:ex2:words:2:note":"まどガラス","grammar:91464:ex2:words:2:pos":"noun","grammar:91464:ex2:words:3:zh":"(subject)","grammar:91464:ex2:words:3:pos":"particle","grammar:91464:ex2:words:4:zh":"broke","grammar:91464:ex2:words:4:note":"われました; past masu-form of 割れる","grammar:91464:ex2:words:4:pos":"verb","grammar:91464:ex2:points:0":"ガラスが割れる: glass shatters; the most typical pairing for 割れる","grammar:91464:ex2:points:1":"地震で: 「で」 marks the cause"},"91465":{"example:91465:exzh":"My older brother works at a newspaper company.","example:91465:exzh2":"I sent the photo to the newspaper company.","grammar:91465:ex:trans":"My older brother works at a newspaper company.","grammar:91465:ex:structure":"〔person〕は〔place〕で＋働いています","grammar:91465:ex:explain":"「新聞社」 is a company that publishes newspapers. Japanese 「新聞」 means 'newspaper,' not 'news' — news in Japanese is 「ニュース」. 「〜で働いています」 is used to say where you or a family member works.","grammar:91465:ex:words:0:zh":"(my) older brother","grammar:91465:ex:words:0:note":"あに","grammar:91465:ex:words:0:pos":"noun","grammar:91465:ex:words:1:zh":"(topic)","grammar:91465:ex:words:1:pos":"particle","grammar:91465:ex:words:2:zh":"newspaper company","grammar:91465:ex:words:2:note":"しんぶんしゃ","grammar:91465:ex:words:2:pos":"noun","grammar:91465:ex:words:3:zh":"exist","grammar:91465:ex:words:3:pos":"particle","grammar:91465:ex:words:4:zh":"work","grammar:91465:ex:words:4:note":"はたらいています; 働く＋ている","grammar:91465:ex:words:4:pos":"verb","grammar:91465:ex:points:0":"新聞社 = a newspaper company (a company that publishes newspapers), not a TV news broadcaster","grammar:91465:ex:points:1":"〔place〕で働く: 「で」 marks where you work; 働いている shows your current occupation","grammar:91465:ex2:trans":"I sent the photos to the newspaper company.","grammar:91465:ex2:structure":"〔recipient〕に＋〔thing〕を送りました","grammar:91465:ex2:words:0:zh":"newspaper company","grammar:91465:ex2:words:0:note":"しんぶんしゃ","grammar:91465:ex2:words:0:pos":"noun","grammar:91465:ex2:words:1:zh":"to; send to","grammar:91465:ex2:words:1:pos":"particle","grammar:91465:ex2:words:2:zh":"photo","grammar:91465:ex2:words:2:note":"しゃしん","grammar:91465:ex2:words:2:pos":"noun","grammar:91465:ex2:words:3:zh":"(object)","grammar:91465:ex2:words:3:pos":"particle","grammar:91465:ex2:words:4:zh":"sent","grammar:91465:ex2:words:4:note":"おくりました; past masu-form of 送る","grammar:91465:ex2:words:4:pos":"verb","grammar:91465:ex2:points:0":"新聞社に送る: to send to a newspaper company (for example, submitting something)","grammar:91465:ex2:points:1":"〔recipient〕に〔thing〕を送る: to send something to someone; the recipient takes 「に」"},"91466":{"example:91466:exzh":"You mustn't bully small children.","example:91466:exzh2":"He was bullied at school.","grammar:91466:ex:trans":"You must not bully little children.","grammar:91466:ex:structure":"〔person〕を＋いじめてはいけません","grammar:91466:ex:explain":"「いじめる」 means to deliberately make someone weaker suffer or feel bad, and the victim takes 「を」. In Japan, 「いじめ」 is a serious social issue referring to bullying at school. 「〜てはいけません」 is a prohibition pattern adults often use when telling children the rules.","grammar:91466:ex:words:0:zh":"small","grammar:91466:ex:words:0:note":"ちいさい","grammar:91466:ex:words:0:pos":"adjective","grammar:91466:ex:words:1:zh":"child","grammar:91466:ex:words:1:note":"こ","grammar:91466:ex:words:1:pos":"noun","grammar:91466:ex:words:2:zh":"(object)","grammar:91466:ex:words:2:pos":"particle","grammar:91466:ex:words:3:zh":"bully","grammar:91466:ex:words:3:note":"; te-form of いじめる","grammar:91466:ex:words:3:pos":"verb","grammar:91466:ex:words:4:zh":"(emphasis)","grammar:91466:ex:words:4:pos":"particle","grammar:91466:ex:words:5:zh":"must not","grammar:91466:ex:words:5:note":"; negative masu-form of いける","grammar:91466:ex:words:5:pos":"verb","grammar:91466:ex:points:0":"いじめる = to bully or pick on someone weaker; the noun is 「いじめ」 (bullying)","grammar:91466:ex:points:1":"〜てはいけません: a prohibition meaning you must not 〜","grammar:91466:ex2:trans":"He was being bullied at school.","grammar:91466:ex2:structure":"〔person〕は＋いじめられていました","grammar:91466:ex2:words:0:zh":"he","grammar:91466:ex2:words:0:note":"かれ","grammar:91466:ex2:words:0:pos":"pronoun","grammar:91466:ex2:words:1:zh":"(topic)","grammar:91466:ex2:words:1:pos":"particle","grammar:91466:ex2:words:2:zh":"school","grammar:91466:ex2:words:2:note":"がっこう","grammar:91466:ex2:words:2:pos":"noun","grammar:91466:ex2:words:3:zh":"exist","grammar:91466:ex2:words:3:pos":"particle","grammar:91466:ex2:words:4:zh":"(continuously) being bullied","grammar:91466:ex2:words:4:note":"; passive of いじめる + ていた","grammar:91466:ex2:words:4:pos":"verb","grammar:91466:ex2:points:0":"passive form: いじめる→いじめられる (to be bullied)","grammar:91466:ex2:points:1":"〜ていました: describes a state that continued for a period of time in the past"},"91467":{"example:91467:exzh":"Please turn the doorknob to the right.","example:91467:exzh2":"Please pass these materials around to everyone.","grammar:91467:ex:trans":"Please turn the doorknob to the right.","grammar:91467:ex:structure":"〔thing〕を〔direction〕に＋回してください","grammar:91467:ex:explain":"「回す」 means to turn something with your hand, such as a doorknob, a key, or a faucet, and the object takes 「を」. When the thing turns by itself, use 「回る」, as in 「風車が回る」. The 「に」 in 「右に」 marks the direction of the turn.","grammar:91467:ex:words:0:zh":"door","grammar:91467:ex:words:0:pos":"noun","grammar:91467:ex:words:1:zh":"'s","grammar:91467:ex:words:1:pos":"particle","grammar:91467:ex:words:2:zh":"doorknob","grammar:91467:ex:words:2:pos":"noun","grammar:91467:ex:words:3:zh":"(object)","grammar:91467:ex:words:3:pos":"particle","grammar:91467:ex:words:4:zh":"the right side","grammar:91467:ex:words:4:note":"みぎ","grammar:91467:ex:words:4:pos":"noun","grammar:91467:ex:words:5:zh":"toward (a direction)","grammar:91467:ex:words:5:pos":"particle","grammar:91467:ex:words:6:zh":"to turn; to rotate","grammar:91467:ex:words:6:note":"まわして; the te-form of 回す","grammar:91467:ex:words:6:pos":"verb","grammar:91467:ex:words:7:zh":"please","grammar:91467:ex:words:7:pos":"auxiliary verb","grammar:91467:ex:points:0":"回す = to turn (transitive verb, takes を); the intransitive verb is 「回る」 (to turn by itself)","grammar:91467:ex:points:1":"右に回す: to turn to the right; the direction takes 「に」","grammar:91467:ex2:trans":"Please pass this document around to everyone.","grammar:91467:ex2:structure":"〔thing〕を〔person〕に＋回してください","grammar:91467:ex2:words:0:zh":"this","grammar:91467:ex2:words:0:pos":"pre-noun adjectival","grammar:91467:ex2:words:1:zh":"materials","grammar:91467:ex2:words:1:note":"しりょう","grammar:91467:ex2:words:1:pos":"noun","grammar:91467:ex2:words:2:zh":"(object)","grammar:91467:ex2:words:2:pos":"particle","grammar:91467:ex2:words:3:zh":"everyone","grammar:91467:ex2:words:3:pos":"pronoun","grammar:91467:ex2:words:4:zh":"to","grammar:91467:ex2:words:4:pos":"particle","grammar:91467:ex2:words:5:zh":"convey","grammar:91467:ex2:words:5:note":"まわして; the te-form of 回す","grammar:91467:ex2:words:5:pos":"verb","grammar:91467:ex2:words:6:zh":"please","grammar:91467:ex2:words:6:pos":"auxiliary verb","grammar:91467:ex2:points:0":"回す also means to pass something around to others in turn: 資料を回す = to pass the document around","grammar:91467:ex2:points:1":"〔person〕に: the person you pass it to takes 「に」"},"91468":{"example:91468:exzh":"It's exactly as the teacher said.","example:91468:exzh2":"May I ask what your name is?","grammar:91468:ex:trans":"It is exactly as the teacher said.","grammar:91468:ex:structure":"〔person〕のおっしゃるとおりです","grammar:91468:ex:explain":"「おっしゃる」 is the sonkeigo (respectful) form of 言う (to say) and is used only for the other person or someone senior; for yourself you use 「申す」. 「おっしゃるとおりです」 is a polite way to agree completely with someone, and it is heard very often at work.","grammar:91468:ex:words:0:zh":"teacher","grammar:91468:ex:words:0:note":"せんせい","grammar:91468:ex:words:0:pos":"noun","grammar:91468:ex:words:1:zh":"(the subject inside the modifying clause)","grammar:91468:ex:words:1:pos":"particle","grammar:91468:ex:words:2:zh":"say (respectful)","grammar:91468:ex:words:2:pos":"verb","grammar:91468:ex:words:3:zh":"exactly as, just like 〜","grammar:91468:ex:words:3:pos":"formal noun","grammar:91468:ex:words:4:zh":"is","grammar:91468:ex:words:4:pos":"copula","grammar:91468:ex:points:0":"おっしゃる = sonkeigo of 言う, used for what a teacher, boss, or customer says","grammar:91468:ex:points:1":"〜とおり: exactly as 〜; おっしゃるとおりです = you are right","grammar:91468:ex:points:2":"先生の: in a modifying clause, 「の」 can replace 「が」 to mark the subject","grammar:91468:ex2:trans":"May I ask your name?","grammar:91468:ex2:structure":"お名前は＋何とおっしゃいますか","grammar:91468:ex2:words:0:zh":"(your) name","grammar:91468:ex2:words:0:note":"おなまえ","grammar:91468:ex2:words:0:pos":"noun","grammar:91468:ex2:words:1:zh":"(topic)","grammar:91468:ex2:words:1:pos":"particle","grammar:91468:ex2:words:2:zh":"what","grammar:91468:ex2:words:2:note":"なん","grammar:91468:ex2:words:2:pos":"question word","grammar:91468:ex2:words:3:zh":"(the content of what was said)","grammar:91468:ex2:words:3:pos":"particle","grammar:91468:ex2:words:4:zh":"to be called, to say (respectful)","grammar:91468:ex2:words:4:note":"; masu-form of おっしゃる","grammar:91468:ex2:words:4:pos":"verb","grammar:91468:ex2:words:5:zh":"(question)","grammar:91468:ex2:words:5:pos":"particle","grammar:91468:ex2:points:0":"the masu-form of おっしゃる is 「おっしゃいます」 (not おっしゃります)","grammar:91468:ex2:points:1":"〜と言う／おっしゃる: to be called 〜; names and content take 「と」"},"91469":{"example:91469:exzh":"I didn't have an umbrella, so my clothes got soaked.","example:91469:exzh2":"Please don't touch electrical appliances with wet hands.","grammar:91469:ex:trans":"I had no umbrella, so my clothes got soaked.","grammar:91469:ex:structure":"〜なくて、〔noun〕が濡れてしまいました","grammar:91469:ex:explain":"「濡れる」 means to get wet from rain or water, and the thing that gets wet is the subject taking 「が」. To say you got soaked by rain, you can use 「雨に濡れる」. 「傘がなくて」 uses the te-form of ない to show the cause, and 「濡れてしまいました」 adds a feeling of regret.","grammar:91469:ex:words:0:zh":"umbrella","grammar:91469:ex:words:0:note":"かさ","grammar:91469:ex:words:0:pos":"noun","grammar:91469:ex:words:1:zh":"(subject)","grammar:91469:ex:words:1:pos":"particle","grammar:91469:ex:words:2:zh":"there is no (so)","grammar:91469:ex:words:2:note":"; te-form of ない","grammar:91469:ex:words:2:pos":"adjective","grammar:91469:ex:words:3:zh":"clothes","grammar:91469:ex:words:3:note":"ふく","grammar:91469:ex:words:3:pos":"noun","grammar:91469:ex:words:4:zh":"(subject)","grammar:91469:ex:words:4:pos":"particle","grammar:91469:ex:words:5:zh":"get wet","grammar:91469:ex:words:5:note":"ぬれて; te-form of 濡れる","grammar:91469:ex:words:5:pos":"verb","grammar:91469:ex:words:6:zh":"(unfortunately)〜","grammar:91469:ex:words:6:note":"; past masu-form of てしまう","grammar:91469:ex:words:6:pos":"auxiliary verb","grammar:91469:ex:points:0":"濡れる = to get wet from water; this intransitive verb takes 「が」: 服が濡れる, 雨に濡れる; the transitive verb is 「濡らす」","grammar:91469:ex:points:1":"〜なくて: because there is no 〜, showing cause","grammar:91469:ex:points:2":"〜てしまう: shows that something you did not want to happen has happened","grammar:91469:ex2:trans":"Please do not touch electrical appliances with wet hands.","grammar:91469:ex2:structure":"〜た手で、〜に触らないでください","grammar:91469:ex2:explain":"「濡れた」 modifies 「手」 and shows that the hands are already wet; 「で」 shows that the hands are the means of touching. 「電気製品」 together means electrical appliances. The negative form of 「触る」 is 「触らない」, and adding 「でください」 creates a request for someone not to touch something.","grammar:91469:ex2:words:0:zh":"become wet","grammar:91469:ex2:words:0:note":"ぬれ","grammar:91469:ex2:words:0:pos":"verb","grammar:91469:ex2:words:1:zh":"(shows a state that has already taken form)","grammar:91469:ex2:words:1:pos":"auxiliary verb","grammar:91469:ex2:words:2:zh":"hand","grammar:91469:ex2:words:2:note":"て","grammar:91469:ex2:words:2:pos":"noun","grammar:91469:ex2:words:3:zh":"(tool, means)","grammar:91469:ex2:words:3:pos":"particle","grammar:91469:ex2:words:4:zh":"electricity, electric power","grammar:91469:ex2:words:4:note":"でんき","grammar:91469:ex2:words:4:pos":"noun","grammar:91469:ex2:words:5:zh":"product","grammar:91469:ex2:words:5:note":"せいひん","grammar:91469:ex2:words:5:pos":"noun","grammar:91469:ex2:words:6:zh":"(the thing being touched)","grammar:91469:ex2:words:6:pos":"particle","grammar:91469:ex2:words:7:zh":"touch","grammar:91469:ex2:words:7:note":"さわら","grammar:91469:ex2:words:7:pos":"verb","grammar:91469:ex2:words:8:zh":"(negative)","grammar:91469:ex2:words:8:pos":"auxiliary verb","grammar:91469:ex2:words:9:zh":"(links to a negative request)","grammar:91469:ex2:words:9:pos":"particle","grammar:91469:ex2:words:10:zh":"please","grammar:91469:ex2:words:10:pos":"verb","grammar:91469:ex2:points:0":"The ta-form in 「濡れた手」 shows a state that has already become wet, meaning wet hands.","grammar:91469:ex2:points:1":"「〜に触る」 uses 「に」 to mark the thing being touched.","grammar:91469:ex2:points:2":"「verb nai-form＋でください」 means please don't do something."},"91470":{"example:91470:exzh":"My older sister likes making accessories.","example:91470:exzh2":"Where did you buy this accessory?","grammar:91470:ex:trans":"My older sister likes making accessories.","grammar:91470:ex:structure":"〔verb〕のが＋好きです","grammar:91470:ex:explain":"「アクセサリー」 is a loanword meaning the various small ornaments you wear. The key point here is 「作るのが好き」: adding 「の」 after a verb turns it into a noun, and adding 「が好きです」 shows that you like doing something.","grammar:91470:ex:words:0:zh":"(my) older sister","grammar:91470:ex:words:0:note":"あね","grammar:91470:ex:words:0:pos":"noun","grammar:91470:ex:words:1:zh":"(topic)","grammar:91470:ex:words:1:pos":"particle","grammar:91470:ex:words:2:zh":"accessories","grammar:91470:ex:words:2:pos":"noun","grammar:91470:ex:words:3:zh":"(object)","grammar:91470:ex:words:3:pos":"particle","grammar:91470:ex:words:4:zh":"do","grammar:91470:ex:words:4:note":"つくる","grammar:91470:ex:words:4:pos":"verb","grammar:91470:ex:words:5:zh":"(turns an action into a noun)","grammar:91470:ex:words:5:pos":"formal noun","grammar:91470:ex:words:6:zh":"(the thing liked)","grammar:91470:ex:words:6:pos":"particle","grammar:91470:ex:words:7:zh":"to like","grammar:91470:ex:words:7:note":"すき","grammar:91470:ex:words:7:pos":"na-adjective","grammar:91470:ex:words:8:zh":"is","grammar:91470:ex:words:8:pos":"copula","grammar:91470:ex:points:0":"アクセサリー = a general word for accessories such as necklaces, rings, and earrings","grammar:91470:ex:points:1":"verb + の: turns an action into a noun; 〜のが好き = to like doing 〜","grammar:91470:ex2:trans":"Where did you buy this accessory?","grammar:91470:ex2:structure":"〔thing〕は＋どこで買いましたか","grammar:91470:ex2:words:0:zh":"this","grammar:91470:ex2:words:0:pos":"pre-noun adjectival","grammar:91470:ex2:words:1:zh":"accessories","grammar:91470:ex2:words:1:pos":"noun","grammar:91470:ex2:words:2:zh":"(topic)","grammar:91470:ex2:words:2:pos":"particle","grammar:91470:ex2:words:3:zh":"where","grammar:91470:ex2:words:3:pos":"question word","grammar:91470:ex2:words:4:zh":"exist","grammar:91470:ex2:words:4:pos":"particle","grammar:91470:ex2:words:5:zh":"bought","grammar:91470:ex2:words:5:note":"かいました; past masu-form of 買う","grammar:91470:ex2:words:5:pos":"verb","grammar:91470:ex2:words:6:zh":"(question)","grammar:91470:ex2:words:6:pos":"particle","grammar:91470:ex2:points:0":"When complimenting someone on an accessory, people often follow up by asking where they bought it","grammar:91470:ex2:points:1":"どこで: where (the place where an action happens takes で)"},"91471":{"example:91471:exzh":"This town has a thriving industry.","example:91471:exzh2":"I'm studying industrial design at university.","grammar:91471:ex:trans":"This town has a thriving manufacturing industry.","grammar:91471:ex:structure":"〔place〕は＋〔industry〕が盛んです","grammar:91471:ex:explain":"「工業」 refers to the industry that makes things in factories. To say that an industry is thriving in a place, Japanese commonly uses 「〜が盛んです」, a fixed combination. The structure 「AはBが盛ん」 means that B is thriving in A.","grammar:91471:ex:words:0:zh":"this","grammar:91471:ex:words:0:pos":"pre-noun adjectival","grammar:91471:ex:words:1:zh":"town","grammar:91471:ex:words:1:note":"まち","grammar:91471:ex:words:1:pos":"noun","grammar:91471:ex:words:2:zh":"(topic)","grammar:91471:ex:words:2:pos":"particle","grammar:91471:ex:words:3:zh":"industry","grammar:91471:ex:words:3:note":"こうぎょう","grammar:91471:ex:words:3:pos":"noun","grammar:91471:ex:words:4:zh":"(subject)","grammar:91471:ex:words:4:pos":"particle","grammar:91471:ex:words:5:zh":"thriving, flourishing","grammar:91471:ex:words:5:note":"さかん","grammar:91471:ex:words:5:pos":"na-adjective","grammar:91471:ex:words:6:zh":"is","grammar:91471:ex:words:6:pos":"copula","grammar:91471:ex:points:1":"〜が盛んだ: some activity is thriving or flourishing; often used for industries and sports","grammar:91471:ex2:trans":"I am studying industrial design at university.","grammar:91471:ex2:structure":"〔place〕で＋〔subject〕を勉強しています","grammar:91471:ex2:words:0:zh":"university","grammar:91471:ex2:words:0:note":"だいがく","grammar:91471:ex2:words:0:pos":"noun","grammar:91471:ex2:words:1:zh":"exist","grammar:91471:ex2:words:1:pos":"particle","grammar:91471:ex2:words:2:zh":"industry","grammar:91471:ex2:words:2:note":"こうぎょう","grammar:91471:ex2:words:2:pos":"noun","grammar:91471:ex2:words:3:zh":"design","grammar:91471:ex2:words:3:pos":"noun","grammar:91471:ex2:words:4:zh":"(object)","grammar:91471:ex2:words:4:pos":"particle","grammar:91471:ex2:words:5:zh":"studying (currently)","grammar:91471:ex2:words:5:note":"べんきょうしています; 勉強する + ている","grammar:91471:ex2:words:5:pos":"verb","grammar:91471:ex2:points:0":"工業デザイン = industrial design; 工業 can be placed before a noun to form a compound","grammar:91471:ex2:points:1":"勉強している: shows the state of studying right now"},"91472":{"example:91472:exzh":"I bought a suitcase for the trip.","example:91472:exzh2":"The suitcase didn't come out at the airport for the longest time.","grammar:91472:ex:trans":"I bought a suitcase for the trip.","grammar:91472:ex:structure":"〔noun〕のために、〜","grammar:91472:ex:explain":"「スーツケース」 is a suitcase for travel, often used on overseas trips; a backpack is called 「リュック」. 「旅行のために」 shows the purpose of buying something, and after a noun you need 「の」 before 「ために」.","grammar:91472:ex:words:0:zh":"travel / trip","grammar:91472:ex:words:0:note":"りょこう","grammar:91472:ex:words:0:pos":"noun","grammar:91472:ex:words:1:zh":"'s","grammar:91472:ex:words:1:pos":"particle","grammar:91472:ex:words:2:zh":"for the sake of","grammar:91472:ex:words:2:pos":"formal noun","grammar:91472:ex:words:3:zh":"(purpose)","grammar:91472:ex:words:3:pos":"particle","grammar:91472:ex:words:4:zh":"suitcase","grammar:91472:ex:words:4:pos":"noun","grammar:91472:ex:words:5:zh":"(object)","grammar:91472:ex:words:5:pos":"particle","grammar:91472:ex:words:6:zh":"bought","grammar:91472:ex:words:6:note":"かいました; past masu-form of 買う","grammar:91472:ex:words:6:pos":"verb","grammar:91472:ex:points:0":"スーツケース = a hard-shell suitcase with wheels","grammar:91472:ex:points:1":"noun + のために: for the sake of 〜 (purpose)","grammar:91472:ex2:trans":"At the airport, the suitcase just would not come out.","grammar:91472:ex2:structure":"なかなか＋〜ませんでした","grammar:91472:ex2:words:0:zh":"airport","grammar:91472:ex2:words:0:note":"くうこう","grammar:91472:ex2:words:0:pos":"noun","grammar:91472:ex2:words:1:zh":"exist","grammar:91472:ex2:words:1:pos":"particle","grammar:91472:ex2:words:2:zh":"suitcase","grammar:91472:ex2:words:2:pos":"noun","grammar:91472:ex2:words:3:zh":"(subject)","grammar:91472:ex2:words:3:pos":"particle","grammar:91472:ex2:words:4:zh":"(just) won't","grammar:91472:ex2:words:4:pos":"adverb","grammar:91472:ex2:words:5:zh":"did not come out","grammar:91472:ex2:words:5:note":"でてきませんでした; past negative masu-form of 出てくる","grammar:91472:ex2:words:5:pos":"verb","grammar:91472:ex2:points:0":"a scene of waiting for checked baggage at the airport","grammar:91472:ex2:points:1":"なかなか + negative: no matter how long you wait, 〜 does not happen","grammar:91472:ex2:points:2":"出てくる: to come out; 〜てくる shows movement toward the speaker"},"91473":{"example:91473:exzh":"In the afternoon I'm going to the professor's office.","example:91473:exzh2":"Students are in the office until late at night.","grammar:91473:ex:trans":"In the afternoon I am going to the professor's office.","grammar:91473:ex:structure":"〔person〕の研究室に＋行きます","grammar:91473:ex:explain":"At Japanese universities, a 「研究室」 is usually a professor's individual office, where students go to see their teacher when they have questions. It can also refer to the research group under one professor, such as 「田中研究室」.","grammar:91473:ex:words:0:zh":"afternoon","grammar:91473:ex:words:0:note":"ごご","grammar:91473:ex:words:0:pos":"noun","grammar:91473:ex:words:1:zh":"teacher, professor","grammar:91473:ex:words:1:note":"せんせい","grammar:91473:ex:words:1:pos":"noun","grammar:91473:ex:words:2:zh":"'s","grammar:91473:ex:words:2:pos":"particle","grammar:91473:ex:words:3:zh":"research office","grammar:91473:ex:words:3:note":"けんきゅうしつ","grammar:91473:ex:words:3:pos":"noun","grammar:91473:ex:words:4:zh":"until","grammar:91473:ex:words:4:pos":"particle","grammar:91473:ex:words:5:zh":"go","grammar:91473:ex:words:5:note":"いきます; masu-form of 行く","grammar:91473:ex:words:5:pos":"verb","grammar:91473:ex:points:0":"研究室 = a university professor's office or laboratory; it also refers to the research team a professor leads","grammar:91473:ex:points:1":"〔place〕に行く: the destination takes 「に」","grammar:91473:ex2:trans":"There are students in the laboratory until late at night.","grammar:91473:ex2:structure":"〔place〕には＋〔person〕がいます","grammar:91473:ex2:words:0:zh":"research office","grammar:91473:ex2:words:0:note":"けんきゅうしつ","grammar:91473:ex2:words:0:pos":"noun","grammar:91473:ex2:words:1:zh":"exist","grammar:91473:ex2:words:1:pos":"particle","grammar:91473:ex2:words:2:zh":"(topic)","grammar:91473:ex2:words:2:pos":"particle","grammar:91473:ex2:words:3:zh":"evening","grammar:91473:ex2:words:3:note":"よる","grammar:91473:ex2:words:3:pos":"noun","grammar:91473:ex2:words:4:zh":"late","grammar:91473:ex2:words:4:note":"おそく; noun-style form of 遅い","grammar:91473:ex2:words:4:pos":"noun","grammar:91473:ex2:words:5:zh":"until〜","grammar:91473:ex2:words:5:pos":"particle","grammar:91473:ex2:words:6:zh":"student","grammar:91473:ex2:words:6:note":"がくせい","grammar:91473:ex2:words:6:pos":"noun","grammar:91473:ex2:words:7:zh":"(subject)","grammar:91473:ex2:words:7:pos":"particle","grammar:91473:ex2:words:8:zh":"there is (a person)","grammar:91473:ex2:words:8:note":"; the masu-form of いる","grammar:91473:ex2:words:8:pos":"verb","grammar:91473:ex2:points:0":"夜遅くまで = until late at night","grammar:91473:ex2:points:1":"〔place〕に〔person〕がいる: use 「いる」 for people and animals, 「ある」 for things"},"91474":{"example:91474:exzh":"Shoes get dirty quickly on rainy days.","example:91474:exzh2":"I washed the dirty shirt.","grammar:91474:ex:trans":"On rainy days shoes get dirty quickly.","grammar:91474:ex:structure":"〔time〕は＋〔noun〕がすぐ汚れます","grammar:91474:ex:explain":"「汚れる」 means something gets dirty by itself, and people often say 「服が汚れる」 or 「手が汚れる」. To say I got my clothes dirty, use 「服を汚した」. The adjective 「汚い」 describes something being dirty; the meaning is close but the part of speech is different.","grammar:91474:ex:words:0:zh":"rain","grammar:91474:ex:words:0:note":"あめ","grammar:91474:ex:words:0:pos":"noun","grammar:91474:ex:words:1:zh":"'s","grammar:91474:ex:words:1:pos":"particle","grammar:91474:ex:words:2:zh":"day","grammar:91474:ex:words:2:note":"ひ","grammar:91474:ex:words:2:pos":"noun","grammar:91474:ex:words:3:zh":"(topic)","grammar:91474:ex:words:3:pos":"particle","grammar:91474:ex:words:4:zh":"shoes","grammar:91474:ex:words:4:note":"くつ","grammar:91474:ex:words:4:pos":"noun","grammar:91474:ex:words:5:zh":"(subject)","grammar:91474:ex:words:5:pos":"particle","grammar:91474:ex:words:6:zh":"soon","grammar:91474:ex:words:6:pos":"adverb","grammar:91474:ex:words:7:zh":"to become dirty","grammar:91474:ex:words:7:note":"よごれます; masu-form of 汚れる","grammar:91474:ex:words:7:pos":"verb","grammar:91474:ex:points:0":"汚れる = to get dirty; this intransitive verb takes 「が」; the transitive verb 「汚す」 = to make dirty","grammar:91474:ex:points:1":"すぐ: right away, quickly","grammar:91474:ex2:trans":"I washed the dirty shirt.","grammar:91474:ex2:structure":"汚れた＋〔noun〕を洗濯しました","grammar:91474:ex2:words:0:zh":"dirty (that has gotten dirty)","grammar:91474:ex2:words:0:note":"よごれた; ta-form of 汚れる","grammar:91474:ex2:words:0:pos":"verb","grammar:91474:ex2:words:1:zh":"shirt","grammar:91474:ex2:words:1:pos":"noun","grammar:91474:ex2:words:2:zh":"(object)","grammar:91474:ex2:words:2:pos":"particle","grammar:91474:ex2:words:3:zh":"washed (clothes)","grammar:91474:ex2:words:3:note":"せんたくしました; past masu-form of 洗濯する","grammar:91474:ex2:words:3:pos":"verb","grammar:91474:ex2:points:0":"汚れた〜: the ta-form before a noun means 〜 that has already gotten dirty","grammar:91474:ex2:points:1":"洗濯する: used specifically for washing clothes; for washing hands or dishes use 「洗う」"},"91475":{"example:91475:exzh":"I replaced the battery with a new one.","example:91475:exzh2":"The size doesn't fit — could you exchange it for me?","grammar:91475:ex:trans":"I replaced the battery with a new one.","grammar:91475:ex:structure":"〔A〕を〔B〕に＋取り替えました","grammar:91475:ex:explain":"「取り替える」 means to swap something out, and the thing you swap it for takes 「に」, so 「電池を新しいのに取り替える」 means to replace the battery with a new one. The same word is used for exchanging goods at a store. The 「の」 in 「新しいの」 stands in for 「電池」 so you do not repeat it.","grammar:91475:ex:words:0:zh":"battery","grammar:91475:ex:words:0:note":"でんち","grammar:91475:ex:words:0:pos":"noun","grammar:91475:ex:words:1:zh":"(object)","grammar:91475:ex:words:1:pos":"particle","grammar:91475:ex:words:2:zh":"new","grammar:91475:ex:words:2:note":"あたらしい","grammar:91475:ex:words:2:pos":"adjective","grammar:91475:ex:words:3:zh":"(the) one","grammar:91475:ex:words:3:pos":"formal noun","grammar:91475:ex:words:4:zh":"replace with","grammar:91475:ex:words:4:pos":"particle","grammar:91475:ex:words:5:zh":"replaced","grammar:91475:ex:words:5:note":"とりかえました; past masu-form of 取り替える","grammar:91475:ex:words:5:pos":"verb","grammar:91475:ex:points:0":"取り替える = to replace the old with the new, to swap A for B: AをBに取り替える","grammar:91475:ex:points:1":"新しいの: 「の」 stands for a noun mentioned earlier, so 新しい電池→新しいの","grammar:91475:ex2:trans":"The size does not fit, so could you exchange it for me?","grammar:91475:ex2:structure":"〜ので、〜てもらえますか","grammar:91475:ex2:words:0:zh":"size","grammar:91475:ex2:words:0:pos":"noun","grammar:91475:ex2:words:1:zh":"(subject)","grammar:91475:ex2:words:1:pos":"particle","grammar:91475:ex2:words:2:zh":"doesn't fit","grammar:91475:ex2:words:2:note":"あわない; the negative form of 合う","grammar:91475:ex2:words:2:pos":"verb","grammar:91475:ex2:words:3:zh":"because","grammar:91475:ex2:words:3:pos":"particle","grammar:91475:ex2:words:4:zh":"replacement","grammar:91475:ex2:words:4:note":"とりかえて; te-form of 取り替える","grammar:91475:ex2:words:4:pos":"verb","grammar:91475:ex2:words:5:zh":"could you (do it for me)","grammar:91475:ex2:words:5:note":"; potential masu-form of もらう","grammar:91475:ex2:words:5:pos":"auxiliary verb","grammar:91475:ex2:words:6:zh":"(question)","grammar:91475:ex2:words:6:pos":"particle","grammar:91475:ex2:points:0":"取り替えてもらう: to have the store exchange something for you","grammar:91475:ex2:points:1":"〜てもらえますか: a polite way to ask someone to do something for you"},"91476":{"example:91476:exzh":"There's no time, so please hurry.","example:91476:exzh2":"I ran to the station in a hurry.","grammar:91476:ex:trans":"There is no time, so please hurry.","grammar:91476:ex:structure":"〜ので、急いでください","grammar:91476:ex:explain":"「急ぐ」 means to speed up or rush. Its te-form needs special attention: verbs ending in 「ぐ」 change to 「いで」, so it becomes 「急いで」. The first part, 「時間がないので」, gives the reason, and the second part asks the other person to hurry.","grammar:91476:ex:words:0:zh":"time","grammar:91476:ex:words:0:note":"じかん","grammar:91476:ex:words:0:pos":"noun","grammar:91476:ex:words:1:zh":"(subject)","grammar:91476:ex:words:1:pos":"particle","grammar:91476:ex:words:2:zh":"don't have","grammar:91476:ex:words:2:pos":"adjective","grammar:91476:ex:words:3:zh":"because","grammar:91476:ex:words:3:pos":"particle","grammar:91476:ex:words:4:zh":"hurry up","grammar:91476:ex:words:4:note":"いそいで; te-form of 急ぐ","grammar:91476:ex:words:4:pos":"verb","grammar:91476:ex:words:5:zh":"please","grammar:91476:ex:words:5:pos":"auxiliary verb","grammar:91476:ex:points:0":"急ぐ = to hurry, to rush; 急いでください = please hurry","grammar:91476:ex:points:1":"the te-form of 急ぐ is 「急いで」 (ぐ→いで)","grammar:91476:ex2:trans":"I ran to the station in a hurry.","grammar:91476:ex2:structure":"急いで＋〔action〕","grammar:91476:ex2:words:0:zh":"hurriedly","grammar:91476:ex2:words:0:note":"いそいで; te-form of 急ぐ","grammar:91476:ex2:words:0:pos":"verb","grammar:91476:ex2:words:1:zh":"station","grammar:91476:ex2:words:1:note":"えき","grammar:91476:ex2:words:1:pos":"noun","grammar:91476:ex2:words:2:zh":"until","grammar:91476:ex2:words:2:pos":"particle","grammar:91476:ex2:words:3:zh":"ran","grammar:91476:ex2:words:3:note":"はしりました; past masu-form of 走る","grammar:91476:ex2:words:3:pos":"verb","grammar:91476:ex2:points:0":"急いで〜: the te-form modifies the action that follows, meaning hurriedly 〜","grammar:91476:ex2:points:1":"〜まで走る: to run as far as a place"},"91477":{"example:91477:exzh":"I reviewed today's lesson at home.","example:91477:exzh2":"I review vocabulary before a test.","grammar:91477:ex:trans":"I reviewed today's lesson at home.","grammar:91477:ex:structure":"〔content〕を＋復習しました","grammar:91477:ex:explain":"「復習」 means going over material you have already studied, and adding 「する」 makes it a verb. Reading ahead before class is called 「予習」, and the two words often appear together. Note that the Japanese word is written 「復習」, with a different character from the Chinese word for review.","grammar:91477:ex:words:0:zh":"house","grammar:91477:ex:words:0:note":"いえ","grammar:91477:ex:words:0:pos":"noun","grammar:91477:ex:words:1:zh":"exist","grammar:91477:ex:words:1:pos":"particle","grammar:91477:ex:words:2:zh":"today","grammar:91477:ex:words:2:note":"きょう","grammar:91477:ex:words:2:pos":"noun","grammar:91477:ex:words:3:zh":"'s","grammar:91477:ex:words:3:pos":"particle","grammar:91477:ex:words:4:zh":"class","grammar:91477:ex:words:4:note":"じゅぎょう","grammar:91477:ex:words:4:pos":"noun","grammar:91477:ex:words:5:zh":"(object)","grammar:91477:ex:words:5:pos":"particle","grammar:91477:ex:words:6:zh":"studied","grammar:91477:ex:words:6:note":"ふくしゅうしました; past masu-form of 復習する","grammar:91477:ex:words:6:pos":"verb","grammar:91477:ex:points:1":"noun + する makes a verb: 復習→復習する","grammar:91477:ex2:trans":"I review vocabulary before a test.","grammar:91477:ex2:structure":"〔noun〕の前に＋〜を復習します","grammar:91477:ex2:words:0:zh":"test","grammar:91477:ex2:words:0:pos":"noun","grammar:91477:ex2:words:1:zh":"'s","grammar:91477:ex2:words:1:pos":"particle","grammar:91477:ex2:words:2:zh":"before","grammar:91477:ex2:words:2:note":"まえ","grammar:91477:ex2:words:2:pos":"noun","grammar:91477:ex2:words:3:zh":"in (time)","grammar:91477:ex2:words:3:pos":"particle","grammar:91477:ex2:words:4:zh":"vocabulary word","grammar:91477:ex2:words:4:note":"たんご","grammar:91477:ex2:words:4:pos":"noun","grammar:91477:ex2:words:5:zh":"(object)","grammar:91477:ex2:words:5:pos":"particle","grammar:91477:ex2:words:6:zh":"review","grammar:91477:ex2:words:6:note":"ふくしゅうします; masu-form of 復習する","grammar:91477:ex2:words:6:pos":"verb","grammar:91477:ex2:points:0":"単語を復習する: to review vocabulary","grammar:91477:ex2:points:1":"noun + の前に: before 〜"},"91478":{"example:91478:exzh":"This dictionary is very useful.","example:91478:exzh2":"I want to do something useful.","grammar:91478:ex:trans":"This dictionary is very useful.","grammar:91478:ex:structure":"〔noun〕は＋役に立ちます","grammar:91478:ex:explain":"Literally 「役に立つ」 is to stand on a role, and it means to be useful or to come in handy. To say something is practical, say 「〜は役に立ちます」. To say useful to everyone, you can say 「みんなの役に立つ」.","grammar:91478:ex:words:0:zh":"this","grammar:91478:ex:words:0:pos":"pre-noun adjectival","grammar:91478:ex:words:1:zh":"dictionary","grammar:91478:ex:words:1:note":"じしょ","grammar:91478:ex:words:1:pos":"noun","grammar:91478:ex:words:2:zh":"(topic)","grammar:91478:ex:words:2:pos":"particle","grammar:91478:ex:words:3:zh":"extremely","grammar:91478:ex:words:3:pos":"adverb","grammar:91478:ex:words:4:zh":"useful","grammar:91478:ex:words:4:note":"やくにたちます; masu-form of 役に立つ","grammar:91478:ex:words:4:pos":"set phrase","grammar:91478:ex:points:0":"役に立つ = to be useful, to come in handy; to say it is useful to someone, use 「〔person〕の役に立つ」","grammar:91478:ex:points:1":"Memorize 「役に立つ」 as one fixed expression; do not break it apart.","grammar:91478:ex2:trans":"I want to do something helpful.","grammar:91478:ex2:structure":"何か＋〔verb〕こと＋がしたいです","grammar:91478:ex2:words:0:zh":"something; some","grammar:91478:ex2:words:0:note":"なにか","grammar:91478:ex2:words:0:pos":"pronoun","grammar:91478:ex2:words:1:zh":"helpful","grammar:91478:ex2:words:1:note":"やくにたつ","grammar:91478:ex2:words:1:pos":"set phrase","grammar:91478:ex2:words:2:zh":"thing / matter","grammar:91478:ex2:words:2:pos":"formal noun","grammar:91478:ex2:words:3:zh":"(object)","grammar:91478:ex2:words:3:pos":"particle","grammar:91478:ex2:words:4:zh":"want to do","grammar:91478:ex2:words:4:note":"；する＋たい","grammar:91478:ex2:words:4:pos":"verb","grammar:91478:ex2:words:5:zh":"(polite)","grammar:91478:ex2:words:5:pos":"copula","grammar:91478:ex2:points:0":"役に立つこと: the dictionary form of a verb placed before a noun modifies it, giving something helpful","grammar:91478:ex2:points:1":"〜がしたい: to want to do 〜; with the たい-form, the object can take 「が」"},"91479":{"example:91479:exzh":"Summer vacation is almost here, isn't it?","example:91479:exzh2":"The train will be here soon.","grammar:91479:ex:trans":"Summer vacation is almost here, isn't it?","grammar:91479:ex:structure":"もうすぐ＋〔noun〕です","grammar:91479:ex:explain":"「もうすぐ」 shows that something will happen very soon. Japanese can say 「もうすぐ夏休みです」 with no verb, and it means summer vacation is almost here. The sentence-final 「ね」 gives it a tone of sharing the feeling with the listener.","grammar:91479:ex:words:0:zh":"soon","grammar:91479:ex:words:0:pos":"adverb","grammar:91479:ex:words:1:zh":"summer vacation","grammar:91479:ex:words:1:note":"なつやすみ","grammar:91479:ex:words:1:pos":"noun","grammar:91479:ex:words:2:zh":"is","grammar:91479:ex:words:2:pos":"copula","grammar:91479:ex:words:3:zh":"right?","grammar:91479:ex:words:3:pos":"particle","grammar:91479:ex:points:0":"もうすぐ = soon, before long; it can go with a noun sentence or a verb sentence","grammar:91479:ex:points:1":"もうすぐ〜です: 〜 is coming soon; a noun sentence alone can express that something is about to arrive","grammar:91479:ex2:trans":"The train is coming soon.","grammar:91479:ex2:structure":"〔noun〕は＋もうすぐ＋〔verb〕","grammar:91479:ex2:words:0:zh":"train","grammar:91479:ex2:words:0:note":"でんしゃ","grammar:91479:ex2:words:0:pos":"noun","grammar:91479:ex2:words:1:zh":"(topic)","grammar:91479:ex2:words:1:pos":"particle","grammar:91479:ex2:words:2:zh":"soon","grammar:91479:ex2:words:2:pos":"adverb","grammar:91479:ex2:words:3:zh":"come","grammar:91479:ex2:words:3:note":"きます; masu-form of 来る","grammar:91479:ex2:words:3:pos":"verb","grammar:91479:ex2:points:0":"もうすぐ + verb: to be about to 〜","grammar:91479:ex2:points:1":"the masu-form of 来る is 「来ます（きます）」; pay attention to the reading"},"91480":{"example:91480:exzh":"The morning trains are very crowded.","example:91480:exzh2":"The department store is crowded on weekends, so I go on weekdays.","grammar:91480:ex:trans":"The morning train is very crowded.","grammar:91480:ex:structure":"〔noun〕は＋混んでいます","grammar:91480:ex:explain":"「混む」 means there are many people or cars and it is crowded. To describe the situation in front of you, use 「混んでいます」. Its opposite is 「すいています」 (uncrowded); memorize the two together.","grammar:91480:ex:words:0:zh":"morning","grammar:91480:ex:words:0:note":"あさ","grammar:91480:ex:words:0:pos":"noun","grammar:91480:ex:words:1:zh":"'s","grammar:91480:ex:words:1:pos":"particle","grammar:91480:ex:words:2:zh":"train","grammar:91480:ex:words:2:note":"でんしゃ","grammar:91480:ex:words:2:pos":"noun","grammar:91480:ex:words:3:zh":"(topic)","grammar:91480:ex:words:3:pos":"particle","grammar:91480:ex:words:4:zh":"extremely","grammar:91480:ex:words:4:pos":"adverb","grammar:91480:ex:words:5:zh":"crowded","grammar:91480:ex:words:5:note":"こんでいます; 混む + ている","grammar:91480:ex:words:5:pos":"verb","grammar:91480:ex:points:0":"混む = to be crowded (with people); to say it is crowded right now, people usually use 「混んでいる」; the opposite is 「すいている」","grammar:91480:ex:points:1":"the te-form of 混む is 「混んで」","grammar:91480:ex2:trans":"The department store is crowded on weekends, so I go on weekdays.","grammar:91480:ex2:structure":"〜から、〜","grammar:91480:ex2:words:0:zh":"weekend","grammar:91480:ex2:words:0:note":"しゅうまつ","grammar:91480:ex2:words:0:pos":"noun","grammar:91480:ex2:words:1:zh":"'s","grammar:91480:ex2:words:1:pos":"particle","grammar:91480:ex2:words:2:zh":"department store","grammar:91480:ex2:words:2:pos":"noun","grammar:91480:ex2:words:3:zh":"(topic)","grammar:91480:ex2:words:3:pos":"particle","grammar:91480:ex2:words:4:zh":"crowded","grammar:91480:ex2:words:4:note":"こむ","grammar:91480:ex2:words:4:pos":"verb","grammar:91480:ex2:words:5:zh":"because","grammar:91480:ex2:words:5:pos":"particle","grammar:91480:ex2:words:6:zh":"weekdays","grammar:91480:ex2:words:6:note":"へいじつ","grammar:91480:ex2:words:6:pos":"noun","grammar:91480:ex2:words:7:zh":"in (time)","grammar:91480:ex2:words:7:pos":"particle","grammar:91480:ex2:words:8:zh":"go","grammar:91480:ex2:words:8:note":"いきます; masu-form of 行く","grammar:91480:ex2:words:8:pos":"verb","grammar:91480:ex2:points:0":"Using the dictionary form of 混む shows that it is generally crowded (a habitual situation)","grammar:91480:ex2:points:1":"〜から: gives a reason, because 〜"},"91481":{"example:91481:exzh":"I haven't been sleeping well lately.","example:91481:exzh2":"Young people these days don't read newspapers much.","grammar:91481:ex:trans":"These days I often cannot sleep well.","grammar:91481:ex:structure":"この頃、〜","grammar:91481:ex:explain":"「この頃」 means these days and is used for a situation that has continued over a recent stretch of time, so it often goes with habits or states. Here 「よく」 means often, and the whole sentence means that lately I often cannot sleep well.","grammar:91481:ex:words:0:zh":"lately","grammar:91481:ex:words:0:note":"このごろ","grammar:91481:ex:words:0:pos":"noun","grammar:91481:ex:words:1:zh":"often","grammar:91481:ex:words:1:pos":"adverb","grammar:91481:ex:words:2:zh":"can't sleep","grammar:91481:ex:words:2:note":"ねむれません; negative potential form of 眠る","grammar:91481:ex:words:2:pos":"verb","grammar:91481:ex:points:0":"この頃 = lately, these days, referring to a stretch of time; a little more casual than 「最近」","grammar:91481:ex:points:1":"眠れない: the negative potential form of 眠る, meaning cannot sleep","grammar:91481:ex2:trans":"Young people these days do not read newspapers much.","grammar:91481:ex2:structure":"この頃の〔noun〕は〜","grammar:91481:ex2:words:0:zh":"lately","grammar:91481:ex2:words:0:note":"このごろ","grammar:91481:ex2:words:0:pos":"noun","grammar:91481:ex2:words:1:zh":"'s","grammar:91481:ex2:words:1:pos":"particle","grammar:91481:ex2:words:2:zh":"young","grammar:91481:ex2:words:2:note":"わかい","grammar:91481:ex2:words:2:pos":"adjective","grammar:91481:ex2:words:3:zh":"person","grammar:91481:ex2:words:3:note":"ひと","grammar:91481:ex2:words:3:pos":"noun","grammar:91481:ex2:words:4:zh":"(topic)","grammar:91481:ex2:words:4:pos":"particle","grammar:91481:ex2:words:5:zh":"(not) much","grammar:91481:ex2:words:5:pos":"adverb","grammar:91481:ex2:words:6:zh":"newspaper","grammar:91481:ex2:words:6:note":"しんぶん","grammar:91481:ex2:words:6:pos":"noun","grammar:91481:ex2:words:7:zh":"(object)","grammar:91481:ex2:words:7:pos":"particle","grammar:91481:ex2:words:8:zh":"do not read","grammar:91481:ex2:words:8:note":"よみません; negative masu-form of 読む","grammar:91481:ex2:words:8:pos":"verb","grammar:91481:ex2:points:0":"この頃の若い人: young people these days","grammar:91481:ex2:points:1":"あまり + negative: not very much, not 〜"},"91482":{"example:91482:exzh":"It was hot, so I lowered the air conditioner's temperature.","example:91482:exzh2":"I hear that shop is lowering its prices starting next month.","grammar:91482:ex:trans":"It was hot, so I turned the air conditioner temperature down.","grammar:91482:ex:structure":"〔noun〕を＋下げました","grammar:91482:ex:explain":"「下げる」 means to make something go down, and the object takes 「を」. It works for temperature, prices, and volume: 「音を下げる」 (to turn the volume down). The intransitive verb 「下がる」 means to go down by itself, as in 「気温が下がる」.","grammar:91482:ex:words:0:zh":"hot","grammar:91482:ex:words:0:note":"あつい","grammar:91482:ex:words:0:pos":"adjective","grammar:91482:ex:words:1:zh":"because","grammar:91482:ex:words:1:pos":"particle","grammar:91482:ex:words:2:zh":"air conditioner","grammar:91482:ex:words:2:pos":"noun","grammar:91482:ex:words:3:zh":"'s","grammar:91482:ex:words:3:pos":"particle","grammar:91482:ex:words:4:zh":"temperature","grammar:91482:ex:words:4:note":"おんど","grammar:91482:ex:words:4:pos":"noun","grammar:91482:ex:words:5:zh":"(object)","grammar:91482:ex:words:5:pos":"particle","grammar:91482:ex:words:6:zh":"lowered","grammar:91482:ex:words:6:note":"さげました; past masu-form of 下げる","grammar:91482:ex:words:6:pos":"verb","grammar:91482:ex:points:0":"下げる = to lower (transitive verb, takes を): 温度を下げる, 値段を下げる; the intransitive verb is 「下がる」","grammar:91482:ex:points:1":"opposite: 上げる (to raise)","grammar:91482:ex2:trans":"I hear that store is going to lower its prices starting next month.","grammar:91482:ex2:structure":"〜を下げる＋そうです","grammar:91482:ex2:words:0:zh":"store","grammar:91482:ex2:words:0:note":"みせ","grammar:91482:ex2:words:0:pos":"noun","grammar:91482:ex2:words:1:zh":"(topic)","grammar:91482:ex2:words:1:pos":"particle","grammar:91482:ex2:words:2:zh":"next month","grammar:91482:ex2:words:2:note":"らいげつ","grammar:91482:ex2:words:2:pos":"noun","grammar:91482:ex2:words:3:zh":"from〜","grammar:91482:ex2:words:3:pos":"particle","grammar:91482:ex2:words:4:zh":"price","grammar:91482:ex2:words:4:note":"ねだん","grammar:91482:ex2:words:4:pos":"noun","grammar:91482:ex2:words:5:zh":"(object)","grammar:91482:ex2:words:5:pos":"particle","grammar:91482:ex2:words:6:zh":"to lower","grammar:91482:ex2:words:6:note":"さげる","grammar:91482:ex2:words:6:pos":"verb","grammar:91482:ex2:words:7:zh":"I hear (that)","grammar:91482:ex2:words:7:pos":"auxiliary verb","grammar:91482:ex2:points:0":"値段を下げる = to lower prices","grammar:91482:ex2:points:1":"plain form + そうです: hearsay, I hear that 〜"},"91483":{"example:91483:exzh":"This weekend I'm going to the park to see the cherry blossoms.","example:91483:exzh2":"I went cherry blossom viewing with the people from work.","grammar:91483:ex:trans":"This weekend I am going to the park to see the cherry blossoms.","grammar:91483:ex:structure":"〔place〕へ＋〔noun〕に行きます","grammar:91483:ex:explain":"「花見」 is a typical Japanese spring activity where people eat and drink under the cherry trees. In 「花見に行く」, the 「に」 marks purpose, the same pattern as 「買い物に行く」. In casual speech people often add 「お」 and say 「お花見」.","grammar:91483:ex:words:0:zh":"weekend","grammar:91483:ex:words:0:note":"しゅうまつ","grammar:91483:ex:words:0:pos":"noun","grammar:91483:ex:words:1:zh":"park","grammar:91483:ex:words:1:note":"こうえん","grammar:91483:ex:words:1:pos":"noun","grammar:91483:ex:words:2:zh":"to","grammar:91483:ex:words:2:pos":"particle","grammar:91483:ex:words:3:zh":"flower viewing","grammar:91483:ex:words:3:note":"はなみ","grammar:91483:ex:words:3:pos":"noun","grammar:91483:ex:words:4:zh":"to go (purpose)","grammar:91483:ex:words:4:pos":"particle","grammar:91483:ex:words:5:zh":"go","grammar:91483:ex:words:5:note":"いきます; masu-form of 行く","grammar:91483:ex:words:5:pos":"verb","grammar:91483:ex:points:0":"花見 = flower viewing; in Japan it usually means viewing cherry blossoms in spring and having a picnic under the trees","grammar:91483:ex:points:1":"〔action noun〕に行く: to go and do something, as in 花見に行く, 買い物に行く","grammar:91483:ex2:trans":"I went flower viewing with people from work.","grammar:91483:ex2:structure":"〔person〕と＋お花見をしました","grammar:91483:ex2:words:0:zh":"company","grammar:91483:ex2:words:0:note":"かいしゃ","grammar:91483:ex2:words:0:pos":"noun","grammar:91483:ex2:words:1:zh":"'s","grammar:91483:ex2:words:1:pos":"particle","grammar:91483:ex2:words:2:zh":"people","grammar:91483:ex2:words:2:note":"ひとたち","grammar:91483:ex2:words:2:pos":"noun","grammar:91483:ex2:words:3:zh":"with","grammar:91483:ex2:words:3:pos":"particle","grammar:91483:ex2:words:4:zh":"flower viewing","grammar:91483:ex2:words:4:note":"おはなみ","grammar:91483:ex2:words:4:pos":"noun","grammar:91483:ex2:words:5:zh":"(object)","grammar:91483:ex2:words:5:pos":"particle","grammar:91483:ex2:words:6:zh":"did","grammar:91483:ex2:words:6:note":"; past masu-form of する","grammar:91483:ex2:words:6:pos":"verb","grammar:91483:ex2:points:0":"お花見をする: to go flower viewing (as an activity)","grammar:91483:ex2:points:1":"〜たち: attached to a person to show plural"},"91484":{"example:91484:exzh":"I'll transfer to the subway at the next station.","example:91484:exzh2":"Where should I transfer?","grammar:91484:ex:trans":"Transfer to the subway at the next station.","grammar:91484:ex:structure":"〔place〕で＋〔means of transport〕に乗り換えます","grammar:91484:ex:explain":"「乗り換える」 is 「乗る」 (to ride) plus 「換える」 (to change), meaning to transfer. The station where you transfer takes 「で」, and the train or line you change to takes 「に」; these two particles are the key point of this word. The noun form 「乗り換え」 is also heard often in station announcements.","grammar:91484:ex:words:0:zh":"next","grammar:91484:ex:words:0:note":"つぎ","grammar:91484:ex:words:0:pos":"noun","grammar:91484:ex:words:1:zh":"'s","grammar:91484:ex:words:1:pos":"particle","grammar:91484:ex:words:2:zh":"station","grammar:91484:ex:words:2:note":"えき","grammar:91484:ex:words:2:pos":"noun","grammar:91484:ex:words:3:zh":"exist","grammar:91484:ex:words:3:pos":"particle","grammar:91484:ex:words:4:zh":"subway","grammar:91484:ex:words:4:note":"ちかてつ","grammar:91484:ex:words:4:pos":"noun","grammar:91484:ex:words:5:zh":"(the train you change to)","grammar:91484:ex:words:5:pos":"particle","grammar:91484:ex:words:6:zh":"transfer","grammar:91484:ex:words:6:note":"のりかえます; masu-form of 乗り換える","grammar:91484:ex:words:6:pos":"verb","grammar:91484:ex:points:0":"乗り換える = to change trains; the line you change to takes 「に」: 〜に乗り換える","grammar:91484:ex:points:1":"the station where you transfer takes 「で」","grammar:91484:ex2:trans":"Where should I transfer?","grammar:91484:ex2:structure":"どこで〜ばいいですか","grammar:91484:ex2:words:0:zh":"where","grammar:91484:ex2:words:0:pos":"question word","grammar:91484:ex2:words:1:zh":"exist","grammar:91484:ex2:words:1:pos":"particle","grammar:91484:ex2:words:2:zh":"if I transfer","grammar:91484:ex2:words:2:note":"のりかえれば; ba-form of 乗り換える","grammar:91484:ex2:words:2:pos":"verb","grammar:91484:ex2:words:3:zh":"good","grammar:91484:ex2:words:3:pos":"adjective","grammar:91484:ex2:words:4:zh":"(polite)","grammar:91484:ex2:words:4:pos":"copula","grammar:91484:ex2:words:5:zh":"(question)","grammar:91484:ex2:words:5:pos":"particle","grammar:91484:ex2:points:0":"〜ばいいですか: asks what one should do; very handy when asking for directions","grammar:91484:ex2:points:1":"乗り換える→乗り換えれば: for ru-verbs, drop る and add れば"},"91485":{"example:91485:exzh":"I said goodbye to my friend at the station.","example:91485:exzh2":"I heard she broke up with her boyfriend.","grammar:91485:ex:trans":"I said goodbye to a friend at the station.","grammar:91485:ex:structure":"〔person〕と＋別れました","grammar:91485:ex:explain":"「別れる」 means people who were together separate, and the other person takes 「と」. This sentence simply means saying goodbye at the station. The same word can also mean a couple breaking up, so you judge from the context.","grammar:91485:ex:words:0:zh":"station","grammar:91485:ex:words:0:note":"えき","grammar:91485:ex:words:0:pos":"noun","grammar:91485:ex:words:1:zh":"exist","grammar:91485:ex:words:1:pos":"particle","grammar:91485:ex:words:2:zh":"friend","grammar:91485:ex:words:2:note":"ともだち","grammar:91485:ex:words:2:pos":"noun","grammar:91485:ex:words:3:zh":"with","grammar:91485:ex:words:3:pos":"particle","grammar:91485:ex:words:4:zh":"split off","grammar:91485:ex:words:4:note":"わかれました; past masu-form of 別れる","grammar:91485:ex:words:4:pos":"verb","grammar:91485:ex:points:0":"別れる = to part from someone, to say goodbye; the other person takes 「と」: 友だちと別れる","grammar:91485:ex:points:1":"it can also mean a couple breaking up","grammar:91485:ex2:trans":"I hear she broke up with her boyfriend.","grammar:91485:ex2:structure":"〔person〕と別れた＋そうです","grammar:91485:ex2:words:0:zh":"she","grammar:91485:ex2:words:0:note":"かのじょ","grammar:91485:ex2:words:0:pos":"pronoun","grammar:91485:ex2:words:1:zh":"(topic)","grammar:91485:ex2:words:1:pos":"particle","grammar:91485:ex2:words:2:zh":"lover, boyfriend or girlfriend","grammar:91485:ex2:words:2:note":"こいびと","grammar:91485:ex2:words:2:pos":"noun","grammar:91485:ex2:words:3:zh":"with","grammar:91485:ex2:words:3:pos":"particle","grammar:91485:ex2:words:4:zh":"broke up","grammar:91485:ex2:words:4:note":"わかれた; ta-form of 別れる","grammar:91485:ex2:words:4:pos":"verb","grammar:91485:ex2:words:5:zh":"I hear (that)","grammar:91485:ex2:words:5:pos":"auxiliary verb","grammar:91485:ex2:points:0":"恋人と別れる = to break up with your partner","grammar:91485:ex2:points:1":"ta-form + そうです: hearsay that something has (already) happened"},"91486":{"example:91486:exzh":"I got gas at the gas station.","example:91486:exzh2":"Is there a gas station near here?","grammar:91486:ex:trans":"I got gas at the gas station.","grammar:91486:ex:structure":"〔place〕で＋ガソリンを入れました","grammar:91486:ex:explain":"「ガソリンスタンド」 is a Japanese-made English word that English speakers do not use. In Japanese, to get gas is 「ガソリンを入れる」, using 「入れる」 (to put in). The place where the action happens takes 「で」.","grammar:91486:ex:words:0:zh":"gas station","grammar:91486:ex:words:0:pos":"noun","grammar:91486:ex:words:1:zh":"exist","grammar:91486:ex:words:1:pos":"particle","grammar:91486:ex:words:2:zh":"gasoline","grammar:91486:ex:words:2:pos":"noun","grammar:91486:ex:words:3:zh":"(object)","grammar:91486:ex:words:3:pos":"particle","grammar:91486:ex:words:4:zh":"added","grammar:91486:ex:words:4:note":"いれました; past masu-form of 入れる","grammar:91486:ex:words:4:pos":"verb","grammar:91486:ex:points:0":"ガソリンスタンド = gas station (a pseudo-English word coined in Japan; English uses gas station)","grammar:91486:ex:points:1":"ガソリンを入れる = to fill up with gas","grammar:91486:ex2:trans":"Is there a gas station near here?","grammar:91486:ex2:structure":"〔place〕に〔noun〕は＋ありますか","grammar:91486:ex2:words:0:zh":"this","grammar:91486:ex2:words:0:pos":"pre-noun adjectival","grammar:91486:ex2:words:1:zh":"nearby","grammar:91486:ex2:words:1:note":"ちかく","grammar:91486:ex2:words:1:pos":"noun","grammar:91486:ex2:words:2:zh":"exist","grammar:91486:ex2:words:2:pos":"particle","grammar:91486:ex2:words:3:zh":"gas station","grammar:91486:ex2:words:3:pos":"noun","grammar:91486:ex2:words:4:zh":"(topic)","grammar:91486:ex2:words:4:pos":"particle","grammar:91486:ex2:words:5:zh":"there is / are","grammar:91486:ex2:words:5:note":"; the masu-form of ある","grammar:91486:ex2:words:5:pos":"verb","grammar:91486:ex2:words:6:zh":"(question)","grammar:91486:ex2:words:6:pos":"particle","grammar:91486:ex2:points:0":"この近くに〜はありますか: an all-purpose phrase for asking whether some facility is nearby","grammar:91486:ex2:points:1":"The question uses 「は」 to make the thing you're looking for the topic"},"91487":{"example:91487:exzh":"Did you sleep well yesterday?","example:91487:exzh2":"The baby is sleeping soundly.","grammar:91487:ex:trans":"Did you sleep well last night?","grammar:91487:ex:structure":"よく＋眠れましたか","grammar:91487:ex:explain":"「眠る」 means actually falling asleep, while 「寝る」 refers to the act of lying down to sleep — the two are not quite the same. To ask whether someone slept well, use the potential form 「よく眠れましたか」, which means \"were you able to sleep properly?\"","grammar:91487:ex:words:0:zh":"yesterday","grammar:91487:ex:words:0:note":"きのう","grammar:91487:ex:words:0:pos":"noun","grammar:91487:ex:words:1:zh":"(topic)","grammar:91487:ex:words:1:pos":"particle","grammar:91487:ex:words:2:zh":"well","grammar:91487:ex:words:2:pos":"adverb","grammar:91487:ex:words:3:zh":"to be able to fall asleep","grammar:91487:ex:words:3:note":"ねむれました; the past form of the potential form of 眠る","grammar:91487:ex:words:3:pos":"verb","grammar:91487:ex:words:4:zh":"(question)","grammar:91487:ex:words:4:pos":"particle","grammar:91487:ex:points:0":"眠る = to fall asleep, to enter sleep; compared with 「寝る」 (to go to bed), it puts more emphasis on actually falling asleep","grammar:91487:ex:points:1":"眠れる: the potential form of 眠る, \"to be able to fall asleep\"","grammar:91487:ex2:trans":"The baby is sleeping soundly.","grammar:91487:ex2:structure":"〔person〕が＋ぐっすり眠っています","grammar:91487:ex2:words:0:zh":"baby","grammar:91487:ex2:words:0:note":"あかちゃん","grammar:91487:ex2:words:0:pos":"noun","grammar:91487:ex2:words:1:zh":"(subject)","grammar:91487:ex2:words:1:pos":"particle","grammar:91487:ex2:words:2:zh":"(sleeping) soundly","grammar:91487:ex2:words:2:pos":"onomatopoeia","grammar:91487:ex2:words:3:zh":"asleep","grammar:91487:ex2:words:3:note":"ねむっています；眠る＋ている","grammar:91487:ex2:words:3:pos":"verb","grammar:91487:ex2:points:0":"ぐっすり眠る = to sleep soundly; a fixed collocation","grammar:91487:ex2:points:1":"眠っている: the state of being asleep"},"91488":{"example:91488:exzh":"Electricity bills will go up starting next month.","example:91488:exzh2":"Please come in (please come up).","grammar:91488:ex:trans":"Electricity bills go up starting next month.","grammar:91488:ex:structure":"〔time〕から＋〔noun〕が上がります","grammar:91488:ex:explain":"「上がる」 means something rises on its own, and it works for prices, temperatures, and grades. This sentence says electricity bills are going up, and the subject is 「電気代」. Its opposite is 「下がる」. To say a shop raises its prices, use the transitive verb 「値段を上げる」.","grammar:91488:ex:words:0:zh":"next month","grammar:91488:ex:words:0:note":"らいげつ","grammar:91488:ex:words:0:pos":"noun","grammar:91488:ex:words:1:zh":"from〜","grammar:91488:ex:words:1:pos":"particle","grammar:91488:ex:words:2:zh":"electricity bill","grammar:91488:ex:words:2:note":"でんきだい","grammar:91488:ex:words:2:pos":"noun","grammar:91488:ex:words:3:zh":"(subject)","grammar:91488:ex:words:3:pos":"particle","grammar:91488:ex:words:4:zh":"to rise","grammar:91488:ex:words:4:note":"あがります; masu-form of 上がる","grammar:91488:ex:words:4:pos":"verb","grammar:91488:ex:points:0":"上がる = to go up; this intransitive verb takes 「が」: 値段が上がる, 気温が上がる; the transitive verb is 「上げる」","grammar:91488:ex:points:1":"〜代: a charge or fee — 電気代 (electricity bill), ガス代 (gas bill)","grammar:91488:ex2:trans":"Please come in (come up and have a seat).","grammar:91488:ex2:structure":"どうぞ、上がってください","grammar:91488:ex2:words:0:zh":"please","grammar:91488:ex2:words:0:pos":"adverb","grammar:91488:ex2:words:1:zh":"go in (into the house)","grammar:91488:ex2:words:1:note":"あがって；上がる的て形","grammar:91488:ex2:words:1:pos":"verb","grammar:91488:ex2:words:2:zh":"please","grammar:91488:ex2:words:2:pos":"auxiliary verb","grammar:91488:ex2:points:0":"上がる also means \"to go inside the house\": Japanese entryways sit lower than the rooms, so you take off your shoes and step up","grammar:91488:ex2:points:1":"a set greeting used when a guest arrives"},"91489":{"example:91489:exzh":"My little sister practices the piano every day.","example:91489:exzh2":"I took piano lessons when I was a child.","grammar:91489:ex:trans":"My little sister practices the piano every day.","grammar:91489:ex:structure":"〔person〕は毎日＋〔noun〕を練習しています","grammar:91489:ex:explain":"「ピアノ」 means piano. The verb for playing is 「弾く（ひく）」, learning is 「習う」, and practicing is 「練習する」. Here 「練習しています」 expresses a habit you do every day, not just this moment.","grammar:91489:ex:words:0:zh":"(my) little sister","grammar:91489:ex:words:0:note":"いもうと","grammar:91489:ex:words:0:pos":"noun","grammar:91489:ex:words:1:zh":"(topic)","grammar:91489:ex:words:1:pos":"particle","grammar:91489:ex:words:2:zh":"every day","grammar:91489:ex:words:2:note":"まいにち","grammar:91489:ex:words:2:pos":"noun","grammar:91489:ex:words:3:zh":"piano","grammar:91489:ex:words:3:pos":"noun","grammar:91489:ex:words:4:zh":"(object)","grammar:91489:ex:words:4:pos":"particle","grammar:91489:ex:words:5:zh":"practice","grammar:91489:ex:words:5:note":"れんしゅうしています；練習する＋ている","grammar:91489:ex:words:5:pos":"verb","grammar:91489:ex:points:0":"ピアノを弾く = to play the piano; ピアノを習う = to learn the piano; ピアノを練習する = to practice the piano","grammar:91489:ex:points:1":"〜ている: shows a habit repeated every day","grammar:91489:ex2:trans":"I took piano lessons as a child.","grammar:91489:ex2:structure":"子どものころ、〜ていました","grammar:91489:ex2:words:0:zh":"child","grammar:91489:ex2:words:0:note":"こども","grammar:91489:ex2:words:0:pos":"noun","grammar:91489:ex2:words:1:zh":"'s","grammar:91489:ex2:words:1:pos":"particle","grammar:91489:ex2:words:2:zh":"time","grammar:91489:ex2:words:2:pos":"formal noun","grammar:91489:ex2:words:3:zh":"piano","grammar:91489:ex2:words:3:pos":"noun","grammar:91489:ex2:words:4:zh":"(object)","grammar:91489:ex2:words:4:pos":"particle","grammar:91489:ex2:words:5:zh":"was learning (at the time)","grammar:91489:ex2:words:5:note":"ならっていました；習う＋ていた","grammar:91489:ex2:words:5:pos":"verb","grammar:91489:ex2:points:0":"ピアノを習う: to learn the piano (as a skill) from a teacher","grammar:91489:ex2:points:1":"子どものころ = when I was a child; 〜ていました describes something that went on for a period in the past"},"91490":{"example:91490:exzh":"This shirt is made of cotton.","example:91490:exzh2":"Cotton clothes feel nice in summer.","grammar:91490:ex:trans":"This shirt is made of cotton.","grammar:91490:ex:structure":"〔thing〕は〔material〕で＋できています","grammar:91490:ex:explain":"「木綿」 is read as a whole as 「もめん」, meaning the cloth woven from cotton. To say what material something is made of, use 「〜でできています」, where 「で」 marks the material. On modern labels you often see 「綿100％」.","grammar:91490:ex:words:0:zh":"this","grammar:91490:ex:words:0:pos":"pre-noun adjectival","grammar:91490:ex:words:1:zh":"shirt","grammar:91490:ex:words:1:pos":"noun","grammar:91490:ex:words:2:zh":"(topic)","grammar:91490:ex:words:2:pos":"particle","grammar:91490:ex:words:3:zh":"cotton","grammar:91490:ex:words:3:note":"もめん","grammar:91490:ex:words:3:pos":"noun","grammar:91490:ex:words:4:zh":"with (ingredients)","grammar:91490:ex:words:4:pos":"particle","grammar:91490:ex:words:5:zh":"to make into","grammar:91490:ex:words:5:note":"；できる＋ている","grammar:91490:ex:words:5:pos":"verb","grammar:91490:ex:points:0":"木綿 = cotton, cotton cloth; the reading もめん is irregular. Today people also say 「綿（めん）」 or 「コットン」","grammar:91490:ex:points:1":"〔material〕でできている: to be made of ~","grammar:91490:ex2:trans":"Cotton clothes feel nice in summer.","grammar:91490:ex2:structure":"〔time〕は〜が＋気持ちいいです","grammar:91490:ex2:words:0:zh":"summer","grammar:91490:ex2:words:0:note":"なつ","grammar:91490:ex2:words:0:pos":"noun","grammar:91490:ex2:words:1:zh":"(topic)","grammar:91490:ex2:words:1:pos":"particle","grammar:91490:ex2:words:2:zh":"cotton","grammar:91490:ex2:words:2:note":"もめん","grammar:91490:ex2:words:2:pos":"noun","grammar:91490:ex2:words:3:zh":"'s","grammar:91490:ex2:words:3:pos":"particle","grammar:91490:ex2:words:4:zh":"clothes","grammar:91490:ex2:words:4:note":"ふく","grammar:91490:ex2:words:4:pos":"noun","grammar:91490:ex2:words:5:zh":"(subject)","grammar:91490:ex2:words:5:pos":"particle","grammar:91490:ex2:words:6:zh":"comfortable","grammar:91490:ex2:words:6:note":"きもちいい","grammar:91490:ex2:words:6:pos":"adjective","grammar:91490:ex2:words:7:zh":"(polite)","grammar:91490:ex2:words:7:pos":"copula","grammar:91490:ex2:points:0":"木綿の服 = cotton clothes","grammar:91490:ex2:points:1":"気持ちいい: feels good physically"},"91491":{"example:91491:exzh":"Japan exports a lot of cars.","example:91491:exzh2":"This country's main export is rice.","grammar:91491:ex:trans":"Japan exports a lot of cars.","grammar:91491:ex:structure":"〔country〕は〔thing〕を＋輸出しています","grammar:91491:ex:explain":"「輸出」 means selling domestic products abroad — exporting. Don't confuse it with the Japanese word 「出口（でぐち）」, which means an exit. Here 「輸出しています」 describes a long-term situation.","grammar:91491:ex:words:0:zh":"Japan","grammar:91491:ex:words:0:note":"にほん","grammar:91491:ex:words:0:pos":"noun","grammar:91491:ex:words:1:zh":"(topic)","grammar:91491:ex:words:1:pos":"particle","grammar:91491:ex:words:2:zh":"car","grammar:91491:ex:words:2:note":"くるま","grammar:91491:ex:words:2:pos":"noun","grammar:91491:ex:words:3:zh":"(object)","grammar:91491:ex:words:3:pos":"particle","grammar:91491:ex:words:4:zh":"a lot","grammar:91491:ex:words:4:pos":"adverb","grammar:91491:ex:words:5:zh":"export","grammar:91491:ex:words:5:note":"ゆしゅつしています；輸出する＋ている","grammar:91491:ex:words:5:pos":"verb","grammar:91491:ex:points:1":"noun＋する turns it into a verb; 〜ている shows something continuing long-term","grammar:91491:ex2:trans":"This country's main export is rice.","grammar:91491:ex2:structure":"〜の主な輸出品は＋〔noun〕です","grammar:91491:ex2:words:0:zh":"this","grammar:91491:ex2:words:0:pos":"pre-noun adjectival","grammar:91491:ex2:words:1:zh":"country","grammar:91491:ex2:words:1:note":"くに","grammar:91491:ex2:words:1:pos":"noun","grammar:91491:ex2:words:2:zh":"'s","grammar:91491:ex2:words:2:pos":"particle","grammar:91491:ex2:words:3:zh":"main","grammar:91491:ex2:words:3:note":"おもな","grammar:91491:ex2:words:3:pos":"pre-noun adjectival","grammar:91491:ex2:words:4:zh":"export goods","grammar:91491:ex2:words:4:note":"ゆしゅつひん","grammar:91491:ex2:words:4:pos":"noun","grammar:91491:ex2:words:5:zh":"(topic)","grammar:91491:ex2:words:5:pos":"particle","grammar:91491:ex2:words:6:zh":"rice","grammar:91491:ex2:words:6:note":"こめ","grammar:91491:ex2:words:6:pos":"noun","grammar:91491:ex2:words:7:zh":"is","grammar:91491:ex2:words:7:pos":"copula","grammar:91491:ex2:points:0":"輸出品 = export goods; 〜品 means an item or product","grammar:91491:ex2:points:1":"主な = main, and it comes before a noun"},"91492":{"example:91492:exzh":"I installed new software on my computer.","example:91492:exzh2":"This bread is soft and delicious.","grammar:91492:ex:trans":"I installed new software on my computer.","grammar:91492:ex:structure":"〔thing〕を〔place〕に＋入れました","grammar:91492:ex:explain":"「ソフト」 is short for 「ソフトウェア」 and means computer software. To install software, the formal verb is 「インストールする」, while casual speech often uses 「入れる」. It also means \"soft\", so watch the context.","grammar:91492:ex:words:0:zh":"new","grammar:91492:ex:words:0:note":"あたらしい","grammar:91492:ex:words:0:pos":"adjective","grammar:91492:ex:words:1:zh":"software","grammar:91492:ex:words:1:pos":"noun","grammar:91492:ex:words:2:zh":"(object)","grammar:91492:ex:words:2:pos":"particle","grammar:91492:ex:words:3:zh":"computer","grammar:91492:ex:words:3:pos":"noun","grammar:91492:ex:words:4:zh":"into (inside)","grammar:91492:ex:words:4:pos":"particle","grammar:91492:ex:words:5:zh":"installed","grammar:91492:ex:words:5:note":"いれました; past masu-form of 入れる","grammar:91492:ex:words:5:pos":"verb","grammar:91492:ex:points:0":"ソフト = software (short for ソフトウェア); it can also mean \"soft\"","grammar:91492:ex:points:1":"ソフトを入れる = to install software; casual speech often uses 「入れる」","grammar:91492:ex2:trans":"This bread is soft and tasty.","grammar:91492:ex2:structure":"〔noun〕は＋ソフトで＋〜です","grammar:91492:ex2:words:0:zh":"this","grammar:91492:ex2:words:0:pos":"pre-noun adjectival","grammar:91492:ex2:words:1:zh":"bread","grammar:91492:ex2:words:1:pos":"noun","grammar:91492:ex2:words:2:zh":"(topic)","grammar:91492:ex2:words:2:pos":"particle","grammar:91492:ex2:words:3:zh":"soft","grammar:91492:ex2:words:3:note":"；ソフトだ的て形語幹","grammar:91492:ex2:words:3:pos":"na-adjective","grammar:91492:ex2:words:4:zh":"and moreover","grammar:91492:ex2:words:4:note":"；だ的て形","grammar:91492:ex2:words:4:pos":"copula","grammar:91492:ex2:words:5:zh":"delicious","grammar:91492:ex2:words:5:pos":"adjective","grammar:91492:ex2:words:6:zh":"(polite)","grammar:91492:ex2:words:6:pos":"copula","grammar:91492:ex2:points:0":"ソフト as a na-adjective: soft, with a fluffy texture","grammar:91492:ex2:points:1":"na-adjective＋で: links two descriptions, \"both ~ and ~\""},"91493":{"example:91493:exzh":"I went to a shrine to pray at New Year's.","example:91493:exzh2":"This shrine is very old.","grammar:91493:ex:trans":"I went to a shrine to pray during New Year.","grammar:91493:ex:structure":"〔place〕へ＋お参りに行きました","grammar:91493:ex:explain":"「神社」 is a place of worship in Japanese Shinto — if you see a red 「鳥居」, it's a shrine. Japanese people visit shrines at New Year, which is called 「初詣（はつもうで）」. In 「お参りに行く」, the 「に」 marks the purpose of going.","grammar:91493:ex:words:0:zh":"New Year","grammar:91493:ex:words:0:note":"おしょうがつ","grammar:91493:ex:words:0:pos":"noun","grammar:91493:ex:words:1:zh":"in (time)","grammar:91493:ex:words:1:pos":"particle","grammar:91493:ex:words:2:zh":"shrine","grammar:91493:ex:words:2:note":"じんじゃ","grammar:91493:ex:words:2:pos":"noun","grammar:91493:ex:words:3:zh":"to","grammar:91493:ex:words:3:pos":"particle","grammar:91493:ex:words:4:zh":"visit (a shrine)","grammar:91493:ex:words:4:note":"おまいり","grammar:91493:ex:words:4:pos":"noun","grammar:91493:ex:words:5:zh":"to go (purpose)","grammar:91493:ex:words:5:pos":"particle","grammar:91493:ex:words:6:zh":"went","grammar:91493:ex:words:6:note":"いきました; past masu-form of 行く","grammar:91493:ex:words:6:pos":"verb","grammar:91493:ex:points:0":"神社 = a place to worship Shinto deities, with a torii gate at the entrance; Buddhist ones are called 「お寺」","grammar:91493:ex:points:1":"お参りに行く: to go and pray; the first shrine visit of the New Year is called 「初詣」","grammar:91493:ex2:trans":"This shrine is very old.","grammar:91493:ex2:structure":"〔noun〕は＋とても〜です","grammar:91493:ex2:words:0:zh":"this","grammar:91493:ex2:words:0:pos":"pre-noun adjectival","grammar:91493:ex2:words:1:zh":"shrine","grammar:91493:ex2:words:1:note":"じんじゃ","grammar:91493:ex2:words:1:pos":"noun","grammar:91493:ex2:words:2:zh":"(topic)","grammar:91493:ex2:words:2:pos":"particle","grammar:91493:ex2:words:3:zh":"extremely","grammar:91493:ex2:words:3:pos":"adverb","grammar:91493:ex2:words:4:zh":"old","grammar:91493:ex2:words:4:note":"ふるい","grammar:91493:ex2:words:4:pos":"adjective","grammar:91493:ex2:words:5:zh":"(polite)","grammar:91493:ex2:words:5:pos":"copula","grammar:91493:ex2:points:0":"In 神社, 「社」 is read 「じゃ」; this is rendaku (sequential voicing).","grammar:91493:ex2:points:1":"古い: old for objects or long-established things; you don't use 古い for people's age"},"91494":{"example:91494:exzh":"My hobby is taking photos.","example:91494:exzh2":"Do you have any hobbies?","grammar:91494:ex:trans":"My hobby is taking photos.","grammar:91494:ex:structure":"わたしの趣味は＋〔verb〕ことです","grammar:91494:ex:explain":"「趣味」 means what you enjoy doing outside of work. When introducing yourself you say 「趣味は〜です」, and if the hobby is an action, add 「こと」 after the verb. 「写真をとる」 means taking photos, written with the kanji 「撮る」.","grammar:91494:ex:words:0:zh":"I","grammar:91494:ex:words:0:pos":"pronoun","grammar:91494:ex:words:1:zh":"'s","grammar:91494:ex:words:1:pos":"particle","grammar:91494:ex:words:2:zh":"interest","grammar:91494:ex:words:2:note":"しゅみ","grammar:91494:ex:words:2:pos":"noun","grammar:91494:ex:words:3:zh":"(topic)","grammar:91494:ex:words:3:pos":"particle","grammar:91494:ex:words:4:zh":"photo","grammar:91494:ex:words:4:note":"しゃしん","grammar:91494:ex:words:4:pos":"noun","grammar:91494:ex:words:5:zh":"(object)","grammar:91494:ex:words:5:pos":"particle","grammar:91494:ex:words:6:zh":"take (a photo)","grammar:91494:ex:words:6:pos":"verb","grammar:91494:ex:words:7:zh":"(turns an action into a noun)","grammar:91494:ex:words:7:pos":"formal noun","grammar:91494:ex:words:8:zh":"is","grammar:91494:ex:words:8:pos":"copula","grammar:91494:ex:points:0":"趣味 = hobby, pastime; 「趣味は〜です」 is a common self-introduction line","grammar:91494:ex:points:1":"verb＋こと: turns an action into a noun — \"the act of taking photos\"","grammar:91494:ex2:trans":"Do you have any hobbies?","grammar:91494:ex2:structure":"何か＋〔noun〕はありますか","grammar:91494:ex2:words:0:zh":"what","grammar:91494:ex2:words:0:note":"なにか","grammar:91494:ex2:words:0:pos":"pronoun","grammar:91494:ex2:words:1:zh":"interest","grammar:91494:ex2:words:1:note":"しゅみ","grammar:91494:ex2:words:1:pos":"noun","grammar:91494:ex2:words:2:zh":"(topic)","grammar:91494:ex2:words:2:pos":"particle","grammar:91494:ex2:words:3:zh":"there is / are","grammar:91494:ex2:words:3:note":"; the masu-form of ある","grammar:91494:ex2:words:3:pos":"verb","grammar:91494:ex2:words:4:zh":"(question)","grammar:91494:ex2:words:4:pos":"particle","grammar:91494:ex2:points:0":"趣味がある / 趣味はありますか: to have a hobby / do you have a hobby?","grammar:91494:ex2:points:1":"何か: \"something\", often used when asking whether something exists"},"91495":{"example:91495:exzh":"I'm going to the station now.","example:91495:exzh2":"I look forward to your continued support.","grammar:91495:ex:trans":"I'm going to the station now.","grammar:91495:ex:structure":"これから＋〔action〕","grammar:91495:ex:explain":"「これから」 means \"from this moment on\" and is used for what you're about to do next; it can also mean \"from now on\". This sentence means \"I'm on my way to the station now\".","grammar:91495:ex:words:0:zh":"from now (on), next","grammar:91495:ex:words:0:pos":"adverb","grammar:91495:ex:words:1:zh":"station","grammar:91495:ex:words:1:note":"えき","grammar:91495:ex:words:1:pos":"noun","grammar:91495:ex:words:2:zh":"to","grammar:91495:ex:words:2:pos":"particle","grammar:91495:ex:words:3:zh":"go","grammar:91495:ex:words:3:note":"いきます; masu-form of 行く","grammar:91495:ex:words:3:pos":"verb","grammar:91495:ex:points:0":"これから = starting now, next; shows something you're about to do","grammar:91495:ex:points:1":"〔place〕へ行きます: to go to a place","grammar:91495:ex2:trans":"I look forward to your continued support.","grammar:91495:ex2:structure":"これからも＋よろしくお願いします","grammar:91495:ex2:words:0:zh":"from now on","grammar:91495:ex2:words:0:pos":"adverb","grammar:91495:ex2:words:1:zh":"also, too","grammar:91495:ex2:words:1:pos":"particle","grammar:91495:ex2:words:2:zh":"please treat me well","grammar:91495:ex2:words:2:pos":"adverb","grammar:91495:ex2:words:3:zh":"please","grammar:91495:ex2:words:3:note":"おねがいします；お願いする的ます形","grammar:91495:ex2:words:3:pos":"verb","grammar:91495:ex2:points:0":"これからも: \"from now on too\", showing that the relationship continues","grammar:91495:ex2:points:1":"よろしくお願いします: an all-purpose phrase asking for someone's goodwill and support"},"91496":{"example:91496:exzh":"At this restaurant you can eat dishes from all kinds of countries.","example:91496:exzh2":"Ways of thinking vary from person to person."},"91497":{"example:91497:exzh":"It's hot, so please let it cool a little before you drink it.","example:91497:exzh2":"Let the cake cool before cutting it."},"91498":{"example:91498:exzh":"I woke up at five this morning.","example:91498:exzh2":"After I drank coffee, my sleepiness went away."},"91499":{"example:91499:exzh":"He left the room without saying a word.","example:91499:exzh2":"After the typhoon passed, the sky cleared up."}};